CREATE OR REPLACE FUNCTION public._apply_table_rls(p_table text, view_perm text, insert_perm text, update_perm text, delete_perm text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_schema text;
  v_table text;
  v_regclass regclass;
BEGIN
  IF position('.' IN p_table) > 0 THEN
    v_schema := split_part(p_table, '.', 1);
    v_table := split_part(p_table, '.', 2);
  ELSE
    v_schema := 'public';
    v_table := p_table;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.tables
    WHERE table_schema = v_schema
      AND table_name = v_table
  ) THEN
    RAISE NOTICE 'Skipping RLS: table %.% does not exist', v_schema, v_table;
    RETURN;
  END IF;

  v_regclass := (format('%I.%I', v_schema, v_table))::regclass;

  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', v_regclass);

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_select', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR SELECT TO authenticated USING (public.require_permission(%L))',
    v_table || '_select',
    v_regclass,
    view_perm
  );

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_insert', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR INSERT TO authenticated WITH CHECK (public.require_permission(%L))',
    v_table || '_insert',
    v_regclass,
    insert_perm
  );

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_update', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR UPDATE TO authenticated USING (public.require_permission(%L)) WITH CHECK (public.require_permission(%L))',
    v_table || '_update',
    v_regclass,
    update_perm,
    update_perm
  );

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_delete', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR DELETE TO authenticated USING (public.require_permission(%L))',
    v_table || '_delete',
    v_regclass,
    delete_perm
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._apply_table_rls(target_table regclass, read_perm text DEFAULT NULL::text, write_perm text DEFAULT NULL::text, manage_perm text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    table_name_str text;
BEGIN
    table_name_str := target_table::text;

    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY;', table_name_str);

    EXECUTE format('DROP POLICY IF EXISTS "select_policy_%s" ON %s;', replace(table_name_str, '.', '_'), table_name_str);
    EXECUTE format('DROP POLICY IF EXISTS "manage_policy_%s" ON %s;', replace(table_name_str, '.', '_'), table_name_str);

    EXECUTE format('
        CREATE POLICY "select_policy_%s" ON %s
        FOR SELECT TO authenticated
        USING (
            public.is_admin() OR 
            (%L IS NOT NULL AND public.has_permission(%L))
        );', 
        replace(table_name_str, '.', '_'), table_name_str, read_perm, read_perm
    );

    EXECUTE format('
        CREATE POLICY "manage_policy_%s" ON %s
        FOR ALL TO authenticated
        USING (
            public.is_admin() OR 
            (%L IS NOT NULL AND public.has_permission(%L))
        );', 
        replace(table_name_str, '.', '_'), table_name_str, manage_perm, manage_perm
    );
EXCEPTION WHEN OTHERS THEN
    -- در صورت نبود جدول یا اشتباه در آرگومان، از آن عبور می‌کند تا میگریشن متوقف نشود
    RAISE NOTICE 'Skipping RLS for table %, Error: %', target_table, SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public._fifo_consume_for_document(p_product_id uuid, p_quantity numeric, p_source_type text, p_source_id uuid, p_fallback_cost numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining NUMERIC := COALESCE(p_quantity, 0);
  v_batch     RECORD;
  v_take      NUMERIC;
  v_cost      NUMERIC := 0;
BEGIN
  IF v_remaining <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_batch IN
    SELECT id, remaining_qty, unit_cost
    FROM public.inventory_batches
    WHERE product_id = p_product_id AND remaining_qty > 0
    ORDER BY created_at ASC, id ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0.0001;
    v_take := LEAST(v_remaining, v_batch.remaining_qty);

    UPDATE public.inventory_batches SET remaining_qty = remaining_qty - v_take WHERE id = v_batch.id;

    INSERT INTO public.inventory_batch_consumptions (
      batch_id, product_id, quantity, unit_cost, cogs_amount, source_type, source_id
    ) VALUES (
      v_batch.id, p_product_id, v_take, v_batch.unit_cost,
      ROUND(v_take * v_batch.unit_cost, 2), p_source_type, p_source_id
    );

    v_cost := v_cost + ROUND(v_take * v_batch.unit_cost, 2);
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining > 0.0001 THEN
    v_cost := v_cost + ROUND(v_remaining * GREATEST(COALESCE(p_fallback_cost, 0), 0), 2);
  END IF;

  RETURN ROUND(v_cost, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public._inventory_count_lock(p_count_id uuid, p_status text[])
 RETURNS public.inventory_counts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc public.inventory_counts;
BEGIN
  SELECT * INTO v_doc FROM public.inventory_counts WHERE id = p_count_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '%', 'İnventarizasiya sənədi tapılmadı' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (v_doc.status = ANY (p_status)) THEN
    RAISE EXCEPTION '%', format('Bu əməliyyat «%s» statusunda mümkün deyil', v_doc.status)
      USING ERRCODE = '22023';
  END IF;
  RETURN v_doc;
END;
$function$

CREATE OR REPLACE FUNCTION public._inventory_count_set_stock(p_product_id uuid, p_warehouse_id uuid, p_new_qty numeric, p_delta numeric, p_piece_lengths jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row_id UUID;
BEGIN
  SELECT id INTO v_row_id FROM public.warehouse_stocks
  WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
  LIMIT 1;

  IF v_row_id IS NULL AND EXISTS (SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id AND is_default) THEN
    SELECT id INTO v_row_id FROM public.warehouse_stocks
    WHERE product_id = p_product_id AND warehouse_id IS NULL
    LIMIT 1;
  END IF;

  IF v_row_id IS NULL THEN
    INSERT INTO public.warehouse_stocks (product_id, warehouse_id, current_stock, updated_at)
    VALUES (p_product_id, p_warehouse_id, 0, clock_timestamp())
    RETURNING id INTO v_row_id;
  ELSE
    UPDATE public.warehouse_stocks SET updated_at = clock_timestamp() WHERE id = v_row_id;
  END IF;

  IF p_delta <> 0 THEN
    UPDATE public.products
    SET stock = GREATEST(COALESCE(stock, 0) + p_delta, 0)
    WHERE id = p_product_id;
  END IF;

  UPDATE public.warehouse_stocks
  SET current_stock = GREATEST(p_new_qty, 0),
      piece_lengths = COALESCE(p_piece_lengths, piece_lengths),
      updated_at = clock_timestamp()
  WHERE id = v_row_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_document_additional_expenses(p_expenses jsonb, p_source_type text, p_source_id uuid, p_doc_ref text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp JSONB;
  v_amount NUMERIC;
  v_total NUMERIC := 0;
  v_account_id UUID;
  v_label TEXT;
  v_paid BOOLEAN;
BEGIN
  IF p_expenses IS NULL OR jsonb_typeof(p_expenses) <> 'array' THEN
    RETURN 0;
  END IF;

  FOR v_exp IN SELECT value FROM jsonb_array_elements(p_expenses)
  LOOP
    v_amount := COALESCE(NULLIF(v_exp->>'amount', '')::numeric, 0);
    IF v_amount <= 0 THEN
      CONTINUE;
    END IF;
    v_total := v_total + v_amount;
    v_paid := COALESCE((v_exp->>'paid_immediately')::boolean, false);
    IF NOT v_paid THEN
      CONTINUE;
    END IF;

    v_account_id := NULLIF(v_exp->>'account_id', '')::uuid;
    IF v_account_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'Ödənilən əlavə xərc üçün kassa/bank hesabı seçilməlidir';
    END IF;

    v_label := COALESCE(NULLIF(trim(v_exp->>'label'), ''), 'Əlavə xərc');

    PERFORM public.post_cash_transaction(
      v_account_id,
      'Məxaric',
      v_amount,
      'Əlavə Xərc',
      format('%s — %s', p_doc_ref, v_label),
      NULL,
      p_source_type,
      p_source_id
    );
  END LOOP;

  RETURN v_total;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_sale_stock_decrement(p_stock_demand jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key TEXT;
  v_product_id UUID;
  v_qty NUMERIC;
BEGIN
  IF p_stock_demand IS NULL OR jsonb_typeof(p_stock_demand) <> 'object' THEN
    RETURN;
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_qty := COALESCE((p_stock_demand->>v_key)::numeric, 0);

    UPDATE public.products
    SET stock = COALESCE(stock, 0) - v_qty
    WHERE id = v_product_id;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_expense_atomic(p_expense_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp     public.expenses%ROWTYPE;
  v_journal UUID;
  v_memo    TEXT;
BEGIN
  IF NOT public.require_permission('can_manage_finance') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Xərci təsdiqləmək üçün icazəniz yoxdur';
  END IF;
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
  END IF;
  IF v_exp.status <> 'submitted' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Yalnız təsdiq gözləyən xərc təsdiqlənə bilər';
  END IF;

  IF v_exp.payment_mode = 'company' THEN
    PERFORM public.post_expense_internal(v_exp.id);
    UPDATE public.expenses SET approved_at = NOW(), approved_by = auth.uid() WHERE id = v_exp.id;
    RETURN jsonb_build_object('id', v_exp.id, 'status', 'posted');
  END IF;

  -- Employee paid: the expense is booked now, the company owes the employee.
  IF v_exp.employee_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Xərci ödəyən işçi seçilməyib';
  END IF;
  PERFORM public.assert_expense_date_postable(v_exp.expense_date);

  v_memo := public.expense_memo(v_exp.id);
  v_journal := public.post_journal_entry(jsonb_build_object(
    'source_type', 'expense',
    'source_id', v_exp.id,
    'document_type', 'expense',
    'document_id', v_exp.id,
    'idempotency_key', 'expense:' || v_exp.id::text,
    'entry_date', v_exp.expense_date,
    'memo', v_memo,
    'lines', jsonb_build_array(
      jsonb_build_object('coa_id', public.expense_coa_id(v_exp.id), 'debit', v_exp.amount, 'credit', 0,
                         'line_memo', v_exp.category),
      jsonb_build_object('coa_code', '2400', 'debit', 0, 'credit', v_exp.amount,
                         'partner_type', 'employee', 'partner_id', v_exp.employee_id, 'line_memo', v_memo)
    )
  ));

  UPDATE public.expenses
  SET status = 'approved', journal_entry_id = v_journal,
      approved_at = NOW(), approved_by = auth.uid(), updated_at = NOW()
  WHERE id = v_exp.id;

  RETURN jsonb_build_object('id', v_exp.id, 'status', 'approved', 'journal_entry_id', v_journal);
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_expense_date_postable(p_date date)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_date > CURRENT_DATE THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Gələcək tarixli xərc təsdiqlənə bilməz';
  END IF;
  IF public.is_accounting_period_closed(p_date) THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = format('%s dövrü bağlıdır — bu tarixə yazılış edilə bilməz', to_char(p_date, 'MM.YYYY'));
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_journal_entry_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_id UUID;
  v_debit NUMERIC;
  v_credit NUMERIC;
  v_line_count INT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_entry_id := OLD.journal_entry_id;
  ELSE
    v_entry_id := NEW.journal_entry_id;
  END IF;

  SELECT
    COALESCE(SUM(debit), 0),
    COALESCE(SUM(credit), 0),
    COUNT(*)
  INTO v_debit, v_credit, v_line_count
  FROM public.journal_entry_lines
  WHERE journal_entry_id = v_entry_id;

  IF v_line_count = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF abs(v_debit - v_credit) > 0.0001 THEN
    RAISE EXCEPTION 'journal_unbalanced'
      USING ERRCODE = '22023',
            MESSAGE = format(
              'Müxabirləşmə balanssızdir: debet=%s, kredit=%s (entry_id=%s)',
              v_debit,
              v_credit,
              v_entry_id
            );
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_attach_trigger(p_table text, p_name text, p_events text, p_module text, p_when text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF to_regclass(format('public.%I', p_table)) IS NULL THEN
    RAISE NOTICE 'audit_logs: skip missing table %', p_table;
    RETURN;
  END IF;

  EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', p_name, p_table);

  IF p_when IS NULL OR btrim(p_when) = '' THEN
    EXECUTE format(
      'CREATE TRIGGER %I AFTER %s ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_log_row_change(%L)',
      p_name,
      p_events,
      p_table,
      p_module
    );
  ELSE
    EXECUTE format(
      'CREATE TRIGGER %I AFTER %s ON public.%I FOR EACH ROW WHEN (%s) EXECUTE FUNCTION public.audit_log_row_change(%L)',
      p_name,
      p_events,
      p_table,
      p_when,
      p_module
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_json_changed_keys(p_old jsonb, p_new jsonb)
 RETURNS jsonb[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb := COALESCE(p_old, '{}'::jsonb);
  v_new jsonb := COALESCE(p_new, '{}'::jsonb);
  v_old_diff jsonb := '{}'::jsonb;
  v_new_diff jsonb := '{}'::jsonb;
  k text;
BEGIN
  FOR k IN
    SELECT DISTINCT key
    FROM (
      SELECT jsonb_object_keys(v_old) AS key
      UNION
      SELECT jsonb_object_keys(v_new) AS key
    ) keys
  LOOP
    IF k IN ('updated_at') THEN
      CONTINUE;
    END IF;
    IF (v_old -> k) IS DISTINCT FROM (v_new -> k) THEN
      v_old_diff := v_old_diff || jsonb_build_object(k, v_old -> k);
      v_new_diff := v_new_diff || jsonb_build_object(k, v_new -> k);
    END IF;
  END LOOP;
  RETURN ARRAY[v_old_diff, v_new_diff];
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_log_read_event(p_module text, p_table text DEFAULT NULL::text, p_meta jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg JSONB;
  v_track BOOLEAN;
  v_module TEXT;
  v_id UUID;
BEGIN
  IF NOT public.is_active_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'audit_config';

  v_track := COALESCE((v_cfg ->> 'track_read_events')::boolean, false);
  IF NOT v_track THEN
    RETURN NULL;
  END IF;

  v_module := upper(COALESCE(NULLIF(p_module, ''), 'FINANCE'));
  IF v_module NOT IN ('FINANCE', 'PRODUCTION', 'INVENTORY', 'PAYROLL', 'SECURITY') THEN
    v_module := 'FINANCE';
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    module,
    table_name,
    record_id,
    old_values_json,
    new_values_json,
    ip_address
  )
  VALUES (
    public.audit_request_user_id(),
    'READ',
    v_module,
    NULLIF(btrim(COALESCE(p_table, '')), ''),
    NULL,
    NULL,
    COALESCE(p_meta, '{}'::jsonb),
    public.audit_request_ip()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_log_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text;
  v_action text;
  v_old jsonb;
  v_new jsonb;
  v_diff jsonb[];
  v_record_id uuid;
  v_payload jsonb;
  v_log_id uuid;
  v_cfg jsonb;
  v_alert boolean;
  v_email text;
BEGIN
  IF TG_TABLE_NAME = 'audit_logs' OR TG_TABLE_NAME = 'audit_alerts' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  v_module := upper(COALESCE(NULLIF(TG_ARGV[0], ''), 'FINANCE'));
  IF v_module NOT IN ('FINANCE', 'PRODUCTION', 'INVENTORY', 'PAYROLL', 'SECURITY') THEN
    v_module := 'FINANCE';
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE';
    v_payload := to_jsonb(NEW);
    v_new := public.audit_sanitize_row(v_payload);
    v_old := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'UPDATE';
    v_payload := to_jsonb(NEW);
    v_old := public.audit_sanitize_row(to_jsonb(OLD));
    v_new := public.audit_sanitize_row(v_payload);
    v_diff := public.audit_json_changed_keys(v_old, v_new);
    IF v_diff[1] = '{}'::jsonb AND v_diff[2] = '{}'::jsonb THEN
      RETURN NEW;
    END IF;
    v_old := v_diff[1];
    v_new := v_diff[2];
  ELSE
    v_action := 'DELETE';
    v_payload := to_jsonb(OLD);
    v_old := public.audit_sanitize_row(v_payload);
    v_new := NULL;
  END IF;

  BEGIN
    IF v_payload ? 'id' AND nullif(v_payload->>'id', '') IS NOT NULL THEN
      v_record_id := (v_payload->>'id')::uuid;
    ELSIF v_payload ? 'product_id' AND nullif(v_payload->>'product_id', '') IS NOT NULL THEN
      v_record_id := (v_payload->>'product_id')::uuid;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_record_id := NULL;
  END;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    module,
    table_name,
    record_id,
    old_values_json,
    new_values_json,
    ip_address
  ) VALUES (
    public.audit_request_user_id(),
    v_action,
    v_module,
    TG_TABLE_NAME,
    v_record_id,
    v_old,
    v_new,
    public.audit_request_ip()
  )
  RETURNING id INTO v_log_id;

  IF v_action = 'DELETE' THEN
    SELECT value INTO v_cfg
      FROM public.system_settings
     WHERE key = 'audit_config';
    v_alert := COALESCE((v_cfg ->> 'alert_on_record_deletion')::boolean, true);

    IF v_alert AND v_module IN ('FINANCE', 'INVENTORY') THEN
      SELECT email INTO v_email FROM public.company_settings LIMIT 1;

      INSERT INTO public.audit_alerts (
        audit_log_id,
        module,
        table_name,
        record_id,
        user_id,
        message,
        email_to,
        email_status
      )
      VALUES (
        v_log_id,
        v_module,
        TG_TABLE_NAME,
        v_record_id,
        public.audit_request_user_id(),
        format(
          'High-risk DELETE: %s.%s (%s)',
          v_module,
          TG_TABLE_NAME,
          COALESCE(v_record_id::text, 'no-id')
        ),
        NULLIF(btrim(COALESCE(v_email, '')), ''),
        CASE
          WHEN NULLIF(btrim(COALESCE(v_email, '')), '') IS NULL THEN 'skipped'
          ELSE 'logged'
        END
      );
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_request_ip()
 RETURNS inet
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_headers jsonb;
  v_xff text;
  v_ip inet;
BEGIN
  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_headers := NULL;
  END;

  IF v_headers IS NOT NULL THEN
    v_xff := COALESCE(
      v_headers ->> 'x-forwarded-for',
      v_headers ->> 'x-real-ip',
      v_headers ->> 'cf-connecting-ip'
    );
    IF v_xff IS NOT NULL AND btrim(v_xff) <> '' THEN
      BEGIN
        v_ip := split_part(btrim(v_xff), ',', 1)::inet;
        RETURN v_ip;
      EXCEPTION WHEN OTHERS THEN
        v_ip := NULL;
      END;
    END IF;
  END IF;

  RETURN inet_client_addr();
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_request_user_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_sub text;
BEGIN
  BEGIN
    v_uid := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_uid := NULL;
  END;
  IF v_uid IS NOT NULL THEN
    RETURN v_uid;
  END IF;

  BEGIN
    v_sub := nullif(current_setting('request.jwt.claim.sub', true), '');
    IF v_sub IS NOT NULL THEN
      RETURN v_sub::uuid;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_when_columns_changed(p_table text, p_columns text[])
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_col text;
  v_parts text := '';
BEGIN
  FOREACH v_col IN ARRAY p_columns LOOP
    IF EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_schema = 'public'
        AND table_name = p_table
        AND column_name = v_col
    ) THEN
      IF v_parts <> '' THEN
        v_parts := v_parts || ' OR ';
      END IF;
      v_parts := v_parts || format('OLD.%I IS DISTINCT FROM NEW.%I', v_col, v_col);
    END IF;
  END LOOP;
  RETURN NULLIF(v_parts, '');
END;
$function$

CREATE OR REPLACE FUNCTION public.az_payroll_statutory(p_gross numeric, p_year integer DEFAULT 2026)
 RETURNS TABLE(dsmf_employee numeric, dsmf_employer numeric, its_employee numeric, its_employer numeric, income_tax numeric, taxable_income numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_gross NUMERIC := GREATEST(COALESCE(p_gross, 0), 0);
  v_cfg JSONB;
  v_ee_rate NUMERIC;
  v_er_rate NUMERIC;
  v_its_rate NUMERIC;
  v_limit NUMERIC;
  v_first NUMERIC;
  v_mid NUMERIC;
  v_above NUMERIC;
  v_dsmf_ee NUMERIC;
  v_dsmf_er NUMERIC;
  v_its NUMERIC;
  v_taxable NUMERIC;
  v_pit_base NUMERIC;
  v_low_rate NUMERIC;
  v_low_tax NUMERIC;
  v_mid_tax NUMERIC;
  v_pit NUMERIC;
BEGIN
  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'tax_payroll_config';

  v_ee_rate := GREATEST(COALESCE((v_cfg ->> 'dsmf_employee_rate')::numeric, 3), 0) / 100.0;
  v_er_rate := GREATEST(COALESCE((v_cfg ->> 'dsmf_employer_rate')::numeric, 22), 0) / 100.0;
  v_its_rate := GREATEST(COALESCE((v_cfg ->> 'its_rate')::numeric, 0.5), 0) / 100.0;
  v_limit := GREATEST(COALESCE((v_cfg ->> 'non_taxable_salary_limit')::numeric, 0), 0);

  v_first := LEAST(v_gross, 200);
  v_mid := LEAST(GREATEST(v_gross - 200, 0), 7800);
  v_above := GREATEST(v_gross - 8000, 0);

  v_dsmf_ee := ROUND(v_first * v_ee_rate + v_mid * 0.10 + v_above * 0.10, 2);
  v_dsmf_er := ROUND(v_first * v_er_rate + v_mid * 0.15 + v_above * 0.11, 2);
  v_its := ROUND(v_gross * v_its_rate, 2);
  v_taxable := GREATEST(v_gross - v_dsmf_ee - v_its, 0);
  v_pit_base := GREATEST(v_taxable - v_limit, 0);

  v_low_rate := CASE
    WHEN COALESCE(p_year, 2026) >= 2028 THEN 0.07
    WHEN COALESCE(p_year, 2026) >= 2027 THEN 0.05
    ELSE 0.03
  END;
  v_low_tax := ROUND(2500 * v_low_rate, 2);
  v_mid_tax := ROUND(5500 * 0.10, 2);

  IF v_pit_base <= 2500 THEN
    v_pit := ROUND(v_pit_base * v_low_rate, 2);
  ELSIF v_pit_base <= 8000 THEN
    v_pit := ROUND(v_low_tax + (v_pit_base - 2500) * 0.10, 2);
  ELSE
    v_pit := ROUND(v_low_tax + v_mid_tax + (v_pit_base - 8000) * 0.14, 2);
  END IF;

  RETURN QUERY SELECT v_dsmf_ee, v_dsmf_er, v_its, v_its, v_pit, v_taxable;
END;
$function$

CREATE OR REPLACE FUNCTION public.build_and_validate_sale_stock_demand(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_polywood_mode TEXT;
  v_skip_stock BOOLEAN;
  v_stock_demand JSONB := '{}'::jsonb;
  v_key TEXT;
  v_stock NUMERIC;
  v_required NUMERIC;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RETURN '{}'::jsonb;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
    v_qty := COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0);
    v_polywood_mode := NULLIF(trim(v_item->>'polywood_sale_mode'), '');
    v_skip_stock := COALESCE((v_item->>'skip_stock')::boolean, false);

    IF v_product_id IS NULL OR v_qty <= 0 OR v_polywood_mode IS NOT NULL OR v_skip_stock THEN
      CONTINUE;
    END IF;

    -- Services carry no stock.
    IF EXISTS (SELECT 1 FROM public.products WHERE id = v_product_id AND is_service) THEN
      CONTINUE;
    END IF;

    v_stock_demand := public.merge_stock_demand(v_stock_demand, v_product_id, v_qty);
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_required := COALESCE((v_stock_demand->>v_key)::numeric, 0);

    SELECT stock INTO v_stock
    FROM public.products
    WHERE id = v_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_found'
        USING ERRCODE = 'P0002', MESSAGE = 'Məhsul tapılmadı: ' || v_key;
    END IF;

    IF COALESCE(v_stock, 0) + 0.000001 < v_required THEN
      RAISE EXCEPTION 'insufficient_stock'
        USING ERRCODE = '22023',
              MESSAGE = format(
                'Stok kifayət etmir (məhsul %s, tələb: %s, mövcud: %s)',
                v_key,
                trim(to_char(v_required, 'FM999999990.00')),
                trim(to_char(COALESCE(v_stock, 0), 'FM999999990.00'))
              );
    END IF;
  END LOOP;

  RETURN v_stock_demand;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_expense_atomic(p_expense_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp    public.expenses%ROWTYPE;
  v_reason TEXT;
  v_count  INTEGER := 0;
BEGIN
  IF NOT public.require_permission('can_manage_expenses') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Xərci ləğv etmək üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
  END IF;
  IF v_exp.status = 'cancelled' THEN
    RETURN jsonb_build_object('id', v_exp.id, 'status', 'cancelled', 'reversed', 0);
  END IF;
  -- Undoing a booked expense is a finance decision.
  IF v_exp.status IN ('approved', 'posted') AND NOT public.require_permission('can_manage_finance')
     AND NOT (v_exp.status = 'posted' AND v_exp.payment_mode = 'company') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Təsdiqlənmiş xərci yalnız maliyyə ləğv edə bilər';
  END IF;
  -- Posted rows not posted by this module (production expenses) have no
  -- 'expense' cash row; they are cancelled where they were written.
  IF v_exp.status = 'posted' AND NOT EXISTS (
    SELECT 1 FROM public.transactions WHERE source_type = 'expense' AND source_id = v_exp.id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'Bu xərc başqa bölmədən (məs. istehsalat) yazılıb və orada ləğv edilməlidir';
  END IF;

  v_reason := COALESCE(NULLIF(trim(p_reason), ''), 'Xərc ləğv edildi');

  IF v_exp.status = 'posted' THEN
    -- Kassa back (storno cash row + storno of its journal).
    v_count := public.reverse_document_cash_transactions('expense', v_exp.id, v_exp.code, v_reason);
  END IF;
  IF v_exp.status IN ('approved', 'posted') THEN
    IF v_exp.journal_entry_id IS NOT NULL THEN
      PERFORM public.reverse_journal_entry(v_exp.journal_entry_id, v_reason);
    END IF;
    IF v_exp.reimbursement_journal_id IS NOT NULL THEN
      PERFORM public.reverse_journal_entry(v_exp.reimbursement_journal_id, v_reason);
    END IF;
  END IF;

  UPDATE public.expenses
  SET status = 'cancelled', cancelled_at = NOW(), cancelled_by = auth.uid(),
      cancel_reason = v_reason, updated_at = NOW()
  WHERE id = v_exp.id;

  RETURN jsonb_build_object('id', v_exp.id, 'status', 'cancelled', 'reversed', v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_purchase_invoice_atomic(p_purchase_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_purchase public.purchases%ROWTYPE;
  v_label    TEXT;
  v_reason   TEXT;
  v_line     RECORD;
  v_stock    NUMERIC;
  v_cash     INTEGER := 0;
  v_journals INTEGER := 0;
BEGIN
  IF p_purchase_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Alış ID göndərilməyib';
  END IF;

  IF NOT (public.require_permission('can_delete_purchases')
          OR public.require_permission('can_edit_purchases')) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501', MESSAGE = 'Alış ləğvi üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_purchase FROM public.purchases WHERE id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Alış fakturası tapılmadı';
  END IF;

  v_label := COALESCE(NULLIF(trim(v_purchase.invoice_number), ''), p_purchase_id::text);
  v_reason := COALESCE(NULLIF(trim(p_reason), ''), format('Alış fakturası %s ləğv edildi', v_label));

  IF v_purchase.status IN ('cancelled', 'void', 'voided') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('%s artıq ləğv edilib', v_label);
  END IF;

  IF v_purchase.status = 'draft' THEN
    UPDATE public.purchases SET status = 'cancelled', debt_amount = 0 WHERE id = p_purchase_id;
    RETURN jsonb_build_object('success', true, 'purchase_id', p_purchase_id,
                              'invoice_number', v_label, 'was', 'draft');
  END IF;

  -- Goods from this purchase that were already sold or used cannot be unbought.
  IF EXISTS (
    SELECT 1 FROM public.inventory_batches
    WHERE document_id = p_purchase_id
      AND remaining_qty + 0.0001 < initial_qty
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = format('%s: bu alışın malının bir hissəsi artıq satılıb və ya istifadə olunub — ləğv etmək olmaz. Qaytarma sənədi ilə düzəldin.', v_label);
  END IF;

  -- 1. Stock out, per product.
  FOR v_line IN
    SELECT pi.product_id, SUM(pi.quantity) AS qty, MAX(p.name) AS product_name
    FROM public.purchase_items pi
    JOIN public.products p ON p.id = pi.product_id
    WHERE pi.purchase_id = p_purchase_id AND COALESCE(pi.quantity, 0) > 0
    GROUP BY pi.product_id
  LOOP
    SELECT stock INTO v_stock FROM public.products WHERE id = v_line.product_id FOR UPDATE;
    IF COALESCE(v_stock, 0) + 0.0001 < v_line.qty THEN
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = format('%s: %s üçün stok kifayət etmir (lazım: %s, mövcud: %s)',
                         v_label, v_line.product_name,
                         trim(to_char(v_line.qty, 'FM999999990.00')),
                         trim(to_char(COALESCE(v_stock, 0), 'FM999999990.00')));
    END IF;
    UPDATE public.products SET stock = COALESCE(v_stock, 0) - v_line.qty WHERE id = v_line.product_id;
  END LOOP;

  -- 2. Its FIFO layers (all unconsumed, checked above).
  DELETE FROM public.inventory_batches WHERE document_id = p_purchase_id;

  -- 3. Cash paid to the supplier (and paid additional expenses) comes back.
  v_cash := public.reverse_document_cash_transactions('purchase', p_purchase_id, v_label, v_reason);

  DELETE FROM public.warehouse_slips
  WHERE source_type = 'purchase' AND source_document_id = p_purchase_id;

  -- 4. Bill journal.
  v_journals := public.reverse_document_journals(p_purchase_id, v_reason);

  UPDATE public.purchases
  SET status = 'cancelled',
      debt_amount = 0
  WHERE id = p_purchase_id;

  PERFORM public.refresh_supplier_ap_balance(v_purchase.supplier_id);

  RETURN jsonb_build_object(
    'success', true,
    'purchase_id', p_purchase_id,
    'invoice_number', v_label,
    'was', 'posted',
    'cash_reversed', v_cash,
    'journals_reversed', v_journals
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_sales_invoice_atomic(p_sale_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale     public.sales%ROWTYPE;
  v_label    TEXT;
  v_reason   TEXT;
  v_line     RECORD;
  v_demand   JSONB := '{}'::jsonb;
  v_key      TEXT;
  v_units    NUMERIC;
  v_cash     INTEGER := 0;
  v_journals INTEGER := 0;
BEGIN
  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Satış ID göndərilməyib';
  END IF;

  IF NOT (public.require_permission('can_delete_sales')
          OR public.require_permission('can_edit_sales')) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501', MESSAGE = 'Satış ləğvi üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_sale FROM public.sales WHERE id = p_sale_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Satış fakturası tapılmadı';
  END IF;

  v_label := COALESCE(NULLIF(trim(v_sale.doc_no), ''), NULLIF(trim(v_sale.invoice_number), ''), p_sale_id::text);
  v_reason := COALESCE(NULLIF(trim(p_reason), ''), format('Satış fakturası %s ləğv edildi', v_label));

  IF v_sale.status IN ('cancelled', 'void', 'voided') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('%s artıq ləğv edilib', v_label);
  END IF;

  -- A draft never moved stock, cash or the ledger.
  IF v_sale.status = 'draft' THEN
    UPDATE public.sales SET status = 'cancelled', remaining_balance = 0 WHERE id = p_sale_id;
    RETURN jsonb_build_object('success', true, 'sale_id', p_sale_id, 'doc_no', v_label,
                              'was', 'draft');
  END IF;

  -- 1. Stock lines (not dimensional, not services): give the quantity back,
  --    exploding kits through their BOM exactly as posting did.
  FOR v_line IN
    SELECT si.id, si.product_id, si.quantity, si.warehouse_id, si.unit, p.name AS product_name
    FROM public.sale_items si
    JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
      AND COALESCE(si.quantity, 0) > 0
      AND NULLIF(btrim(si.polywood_sale_mode), '') IS NULL
      AND COALESCE(si.sale_item_type, 'standard') <> 'service'
      AND NOT COALESCE(p.is_service, false)
  LOOP
    v_demand := public.merge_stock_demand(v_demand, v_line.product_id, v_line.quantity);

    INSERT INTO public.stock_movements (
      product_id, warehouse_id, movement_type, quantity, unit,
      reference_type, reference_id, source_line_id, description, created_by
    )
    VALUES (
      v_line.product_id, v_line.warehouse_id, 'in', v_line.quantity,
      COALESCE(v_line.unit, 'Ədəd'), 'sale_void', p_sale_id, v_line.id,
      format('Ləğv: satış fakturası %s — %s', v_label, COALESCE(v_line.product_name, '')),
      auth.uid()
    );
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_demand)
  LOOP
    UPDATE public.products
    SET stock = COALESCE(stock, 0) + (v_demand->>v_key)::numeric
    WHERE id = v_key::uuid;
  END LOOP;

  -- 2. Dimensional (Polywood) lines: put the cut pieces back.
  FOR v_line IN
    SELECT si.*, COALESCE(p.full_sheet_length_m, p.base_length, 4) AS sheet_length_m
    FROM public.sale_items si
    JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
      AND NULLIF(btrim(si.polywood_sale_mode), '') IS NOT NULL
  LOOP
    IF v_line.polywood_cut_details IS NOT NULL THEN
      PERFORM public.rollback_mixed_dimensional_sale(v_line.id);
      IF v_line.warehouse_id IS NOT NULL THEN
        UPDATE public.products
        SET stock = (
          SELECT COALESCE(SUM(length_m), 0)
          FROM public.polywood_pieces
          WHERE product_id = v_line.product_id
            AND warehouse_id = v_line.warehouse_id
            AND status = 'available'
        )
        WHERE id = v_line.product_id;
      END IF;
    ELSE
      -- Sold before piece tracking: restore the metres.
      v_units := CASE
        WHEN v_line.polywood_sale_mode = 'full_sheet'
          THEN COALESCE(v_line.quantity, 0) * v_line.sheet_length_m
        WHEN v_line.sale_item_type = 'dimensional'
          THEN COALESCE(v_line.polywood_length_m, v_line.quantity, 0) * GREATEST(COALESCE(v_line.piece_count, 1), 1)
        ELSE COALESCE(v_line.polywood_length_m, v_line.quantity, 0)
      END;
      IF v_units > 0 THEN
        UPDATE public.products SET stock = COALESCE(stock, 0) + v_units WHERE id = v_line.product_id;
      END IF;
    END IF;
  END LOOP;

  -- 3. FIFO: give consumed quantities back to their layers.
  UPDATE public.inventory_batches b
  SET remaining_qty = b.remaining_qty + c.qty
  FROM (
    SELECT batch_id, SUM(quantity) AS qty
    FROM public.inventory_batch_consumptions
    WHERE sale_id = p_sale_id AND batch_id IS NOT NULL
    GROUP BY batch_id
  ) c
  WHERE b.id = c.batch_id;

  DELETE FROM public.inventory_batch_consumptions WHERE sale_id = p_sale_id;
  UPDATE public.sale_items SET cogs_amount = 0 WHERE sale_id = p_sale_id;

  -- 4. Cash received for the invoice (and paid additional expenses).
  v_cash := public.reverse_document_cash_transactions('sale', p_sale_id, v_label, v_reason);

  -- 5. Pending warehouse slips for the invoice are void with it.
  DELETE FROM public.warehouse_slips
  WHERE source_type = 'sale' AND source_document_id = p_sale_id;

  -- 6. Invoice and COGS journals.
  v_journals := public.reverse_document_journals(p_sale_id, v_reason);

  UPDATE public.sales
  SET status = 'cancelled',
      remaining_balance = 0,
      total_cogs = 0
  WHERE id = p_sale_id;

  PERFORM public.refresh_customer_ar_balance(v_sale.customer_id);

  RETURN jsonb_build_object(
    'success', true,
    'sale_id', p_sale_id,
    'doc_no', v_label,
    'was', 'posted',
    'cash_reversed', v_cash,
    'journals_reversed', v_journals
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.coa_credit_for_cash_in(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_cat TEXT := trim(COALESCE(p_category, ''));
BEGIN
  IF v_cat = 'İlkin Qalıq' THEN
    RETURN '3900';
  END IF;
  IF v_cat IN ('Satış Ödənişi', 'Satış') OR v_cat ILIKE '%satış%' THEN
    RETURN '1200';
  END IF;
  IF v_cat = 'Satış gəliri' THEN
    RETURN '4100';
  END IF;
  RETURN '4990';
END;
$function$

CREATE OR REPLACE FUNCTION public.coa_debit_for_cash_out(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_cat TEXT := trim(COALESCE(p_category, ''));
BEGIN
  IF v_cat = 'İlkin Qalıq' THEN
    RETURN '3900';
  END IF;
  IF v_cat IN ('Alış Ödənişi', 'Alış') OR v_cat ILIKE '%alış%' THEN
    RETURN '2100';
  END IF;
  IF v_cat IN (
    'İcarə', 'Elektrik', 'Yanacaq', 'İnternet', 'Reklam', 'Təmir', 'Maaş', 'Digər',
    'transport', 'delivery', 'installation', 'tools', 'other'
  ) THEN
    RETURN '6100';
  END IF;
  RETURN '6190';
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_custom_production_delivery_atomic(p_order_id uuid, p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_order RECORD;
    v_product_id UUID;
    v_sale_id UUID;
    v_total_amount NUMERIC(12,2);
    v_advance_amount NUMERIC(12,2);
    v_remaining_balance NUMERIC(12,2);
    v_doc_no TEXT;
BEGIN
    -- 1. Lock and Check Order
    SELECT * INTO v_order FROM public.production_orders WHERE id = p_order_id FOR UPDATE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Sifariş tapılmadı');
    END IF;

    IF v_order.status = 'Delivered' AND v_order.sale_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Bu sifariş artıq təhvil verilib və satış fakturası yaradılıb');
    END IF;

    IF v_order.customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Təhvil üçün sifarişə müştəri təyin edilməlidir');
    END IF;

    v_total_amount := COALESCE(v_order.total_price, 0);
    v_advance_amount := COALESCE(v_order.advance_payment, 0);
    v_remaining_balance := v_total_amount - v_advance_amount;

    -- 2. Create/Reuse Product SKU
    IF v_order.finished_product_id IS NOT NULL THEN
        v_product_id := v_order.finished_product_id;
    ELSE
        INSERT INTO public.products (name, category, subcategory, sell_price, stock)
        VALUES (
            COALESCE(v_order.project_name, 'Custom Product #' || LEFT(p_order_id::text, 8)),
            'Fərdi istehsal',
            'Make-to-Order',
            v_total_amount,
            0
        )
        RETURNING id INTO v_product_id;
    END IF;

    -- 3. Create Sales Invoice Header
    v_doc_no := 'SF-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(FLOOR(RANDOM() * 10000)::text, 4, '0');

    INSERT INTO public.sales (
        doc_no,
        customer_id,
        customer_name,
        subtotal,
        total_amount,
        paid_amount,
        remaining_balance,
        production_order_id,
        created_at
    ) VALUES (
        v_doc_no,
        v_order.customer_id,
        v_order.customer_name,
        v_total_amount,
        v_total_amount,
        v_advance_amount,
        v_remaining_balance,
        p_order_id,
        NOW()
    ) RETURNING id INTO v_sale_id;

    -- 4. Create Sales Line Item
    INSERT INTO public.sale_items (
        sale_id,
        product_id,
        product_name,
        quantity,
        unit_price,
        total_price
    ) VALUES (
        v_sale_id,
        v_product_id,
        COALESCE(v_order.project_name, 'Custom Product'),
        1,
        v_total_amount,
        v_total_amount
    );

    -- 5. Advance Payment Handling
    IF v_advance_amount > 0 AND p_account_id IS NOT NULL THEN
        INSERT INTO public.transactions (
            type, category, amount, account_id, description, created_at
        ) VALUES (
            'Mədaxil', 'Satış Ödənişi', v_advance_amount, p_account_id,
            'Avans ödənişi - Satış #' || v_doc_no, NOW()
        );

        UPDATE public.accounts 
        SET balance = COALESCE(balance, 0) + v_advance_amount 
        WHERE id = p_account_id;
    END IF;

    -- 6. Accounts Receivable Update
    IF v_remaining_balance > 0 THEN
        UPDATE public.customers 
        SET balance = COALESCE(balance, 0) + v_remaining_balance 
        WHERE id = v_order.customer_id;
    END IF;

    -- 7. Update Production Order
    UPDATE public.production_orders
    SET 
        status = 'Delivered',
        sale_id = v_sale_id,
        finished_product_id = v_product_id,
        delivered_at = NOW(),
        finished_goods_posted = true,
        updated_at = NOW()
    WHERE id = p_order_id;

    RETURN jsonb_build_object(
        'success', true,
        'sale_id', v_sale_id,
        'doc_no', v_doc_no
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_production_wip_cost(p_order_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_material NUMERIC := 0;
  v_outsource NUMERIC := 0;
  v_expense NUMERIC := 0;
  v_contractor NUMERIC := 0;
  v_sub_fee NUMERIC := 0;
BEGIN
  SELECT public.compute_production_issued_material_cost(p_order_id) INTO v_material;

  SELECT COALESCE(SUM(COALESCE(total_cost, 0)), 0)
  INTO v_outsource
  FROM public.production_outsourcing
  WHERE production_order_id = p_order_id;

  SELECT COALESCE(SUM(COALESCE(amount, 0)), 0)
  INTO v_expense
  FROM public.production_expenses
  WHERE production_order_id = p_order_id;

  SELECT COALESCE(SUM(COALESCE(calculated_fee, 0)), 0)
  INTO v_contractor
  FROM public.production_contractors
  WHERE production_order_id = p_order_id;

  SELECT COALESCE(subcontractor_fee_amount, 0)
  INTO v_sub_fee
  FROM public.production_orders
  WHERE id = p_order_id;

  RETURN COALESCE(v_material, 0)
    + COALESCE(v_outsource, 0)
    + COALESCE(v_expense, 0)
    + COALESCE(v_contractor, 0)
    + COALESCE(v_sub_fee, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.consignment_adjust_warehouse_stock(p_product_id uuid, p_warehouse_id uuid, p_delta numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
  v_current NUMERIC;
  v_next NUMERIC;
BEGIN
  SELECT id, current_stock INTO v_id, v_current
  FROM public.warehouse_stocks
  WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
  FOR UPDATE;

  v_next := GREATEST(0, COALESCE(v_current, 0) + p_delta);

  IF v_id IS NOT NULL THEN
    UPDATE public.warehouse_stocks
    SET current_stock = v_next, updated_at = NOW()
    WHERE id = v_id;
  ELSE
    INSERT INTO public.warehouse_stocks (product_id, warehouse_id, current_stock, updated_at)
    VALUES (p_product_id, p_warehouse_id, v_next, NOW());
  END IF;

  UPDATE public.products
  SET stock = GREATEST(0, COALESCE(stock, 0) + p_delta)
  WHERE id = p_product_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_account_atomic(p_code text, p_name text, p_type text, p_opening_balance numeric DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id UUID;
  v_code TEXT;
  v_name TEXT;
  v_type TEXT;
  v_opening NUMERIC;
BEGIN
  IF NOT (
    public.require_permission('can_manage_finance')
    OR public.require_permission('can_manage_settings')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Hesab yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_name := trim(COALESCE(p_name, ''));
  v_type := trim(COALESCE(p_type, ''));
  v_code := trim(COALESCE(p_code, ''));

  IF v_name = '' THEN
    RAISE EXCEPTION 'invalid_name'
      USING ERRCODE = '22023',
            MESSAGE = 'Hesab adı tələb olunur';
  END IF;

  IF v_type NOT IN ('Kassa', 'Bank') THEN
    RAISE EXCEPTION 'invalid_type'
      USING ERRCODE = '22023',
            MESSAGE = 'Hesab növü Kassa və ya Bank olmalıdır';
  END IF;

  v_opening := GREATEST(COALESCE(p_opening_balance, 0), 0);

  IF v_code = '' THEN
    v_code := 'ACC-' || floor(100 + random() * 900)::int;
  END IF;

  INSERT INTO accounts (code, name, type, balance)
  VALUES (v_code, v_name, v_type, 0)
  RETURNING id INTO v_account_id;

  IF v_opening > 0.0001 THEN
    PERFORM public.post_cash_transaction(
      v_account_id,
      'Mədaxil',
      v_opening,
      'İlkin Qalıq',
      format('İlkin qalıq — %s (%s)', v_name, v_code)
    );
  END IF;

  RETURN v_account_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_consignment_dispatch_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID := NULLIF(p_payload->>'partner_id', '')::uuid;
  v_warehouse_id UUID := NULLIF(p_payload->>'warehouse_id', '')::uuid;
  v_warehouse_name TEXT := NULLIF(p_payload->>'warehouse_name', '');
  v_dispatch_date DATE := COALESCE(NULLIF(p_payload->>'dispatch_date', '')::date, CURRENT_DATE);
  v_notes TEXT := NULLIF(btrim(p_payload->>'notes'), '');
  v_sales_rep_id UUID := NULLIF(p_payload->>'sales_rep_id', '')::uuid;
  v_sales_rep_name TEXT := NULLIF(p_payload->>'sales_rep_name', '');
  v_dispatch_no TEXT := NULLIF(btrim(p_payload->>'dispatch_no'), '');
  v_items JSONB := COALESCE(p_payload->'items', '[]'::jsonb);
  v_item JSONB;
  v_product_id UUID;
  v_quantity NUMERIC;
  v_unit_price NUMERIC;
  v_available NUMERIC;
  v_product_name TEXT;
  v_dispatch_id UUID;
  v_now TIMESTAMPTZ := NOW();
  v_inv_id UUID;
  v_delivered NUMERIC;
  v_sold NUMERIC;
  v_returned NUMERIC;
  v_partner_name TEXT;
  v_result JSONB;
  v_created_by UUID := NULLIF(p_payload->>'created_by', '')::uuid;
BEGIN
  -- Permission is checked in JS (requirePermissionAction) before this RPC is
  -- called via the service-role admin client, which has no auth.uid() /
  -- session context - same convention as create_product_with_bom_atomic and
  -- set_customer_opening_balance_atomic.

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'partner_required' USING ERRCODE = '22023', MESSAGE = 'Tərəfdaş seçin';
  END IF;
  IF v_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_required' USING ERRCODE = '22023', MESSAGE = 'Anbar seçin';
  END IF;
  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required' USING ERRCODE = '22023', MESSAGE = 'Ən azı bir məhsul əlavə edin';
  END IF;

  -- Validate every line against live per-warehouse stock before touching anything.
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
    v_quantity := COALESCE((v_item->>'quantity')::numeric, 0);
    IF v_product_id IS NULL OR v_quantity <= 0 THEN
      RAISE EXCEPTION 'invalid_item' USING ERRCODE = '22023', MESSAGE = 'Sətirdə məhsul və ya miqdar yanlışdır';
    END IF;

    SELECT current_stock INTO v_available
    FROM public.warehouse_stocks
    WHERE product_id = v_product_id AND warehouse_id = v_warehouse_id
    FOR UPDATE;

    SELECT name INTO v_product_name FROM public.products WHERE id = v_product_id;
    IF v_product_name IS NULL THEN
      RAISE EXCEPTION 'product_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Məhsul tapılmadı';
    END IF;

    IF COALESCE(v_available, 0) + 0.0001 < v_quantity THEN
      RAISE EXCEPTION 'insufficient_stock'
        USING ERRCODE = '22023',
              MESSAGE = format('%s: seçilmiş anbarda qalıq kifayət etmir (mövcud: %s)', v_product_name, COALESCE(v_available, 0));
    END IF;
  END LOOP;

  IF v_dispatch_no IS NULL THEN
    v_dispatch_no := 'CD-' || EXTRACT(YEAR FROM v_now)::text || '-' || floor(random() * 90000 + 10000)::int::text;
  END IF;

  INSERT INTO public.consignment_dispatches (
    dispatch_no, partner_id, warehouse_id, warehouse_name, dispatch_date,
    status, items, notes, sales_rep_id, sales_rep_name, created_by
  )
  VALUES (
    v_dispatch_no, v_partner_id, v_warehouse_id, v_warehouse_name, v_dispatch_date,
    'delivered', v_items, v_notes, v_sales_rep_id, v_sales_rep_name, v_created_by
  )
  RETURNING id INTO v_dispatch_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_quantity := (v_item->>'quantity')::numeric;
    v_unit_price := COALESCE((v_item->>'unit_price')::numeric, 0);

    PERFORM public.consignment_adjust_warehouse_stock(v_product_id, v_warehouse_id, -v_quantity);

    INSERT INTO public.stock_movements (
      product_id, warehouse_id, movement_type, quantity, unit,
      reference_type, reference_id, description, created_by
    )
    VALUES (
      v_product_id, v_warehouse_id, 'out', v_quantity, COALESCE(v_item->>'unit', 'Ədəd'),
      'consignment_dispatch', v_dispatch_id,
      format('Əmanət mal çıxışı %s', v_dispatch_no), v_created_by
    );

    SELECT id, delivered_qty, sold_qty, returned_qty INTO v_inv_id, v_delivered, v_sold, v_returned
    FROM public.consignment_inventory
    WHERE partner_id = v_partner_id AND product_id = v_product_id
    FOR UPDATE;

    IF v_inv_id IS NOT NULL THEN
      v_delivered := COALESCE(v_delivered, 0) + v_quantity;
      UPDATE public.consignment_inventory
      SET delivered_qty = v_delivered,
          remaining_qty = GREATEST(0, v_delivered - COALESCE(v_sold, 0) - COALESCE(v_returned, 0)),
          unit_price = COALESCE(v_unit_price, unit_price),
          product_name = COALESCE(v_item->>'product_name', product_name),
          product_code = COALESCE(v_item->>'product_code', product_code),
          category = COALESCE(v_item->>'category', category),
          unit = COALESCE(v_item->>'unit', unit),
          last_dispatch_at = v_now,
          updated_at = v_now
      WHERE id = v_inv_id;
    ELSE
      INSERT INTO public.consignment_inventory (
        partner_id, product_id, product_code, product_name, category, unit,
        delivered_qty, sold_qty, returned_qty, remaining_qty, unit_price,
        last_dispatch_at, updated_at
      )
      VALUES (
        v_partner_id, v_product_id, v_item->>'product_code', v_item->>'product_name',
        v_item->>'category', COALESCE(v_item->>'unit', 'Ədəd'),
        v_quantity, 0, 0, v_quantity, v_unit_price, v_now, v_now
      );
    END IF;
  END LOOP;

  SELECT COALESCE(company_name, name) INTO v_partner_name
  FROM public.consignment_partners WHERE id = v_partner_id;

  SELECT to_jsonb(d) || jsonb_build_object('partner_name', v_partner_name)
  INTO v_result
  FROM public.consignment_dispatches d
  WHERE d.id = v_dispatch_id;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_inventory_batch(p_product_id uuid, p_document_id uuid, p_document_type text, p_unit_cost numeric, p_quantity numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id UUID;
  v_qty NUMERIC := COALESCE(p_quantity, 0);
  v_cost NUMERIC := COALESCE(p_unit_cost, 0);
BEGIN
  IF p_product_id IS NULL OR v_qty <= 0 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.inventory_batches (
    product_id,
    document_id,
    document_type,
    unit_cost,
    initial_qty,
    remaining_qty
  )
  VALUES (
    p_product_id,
    p_document_id,
    COALESCE(NULLIF(trim(p_document_type), ''), 'purchase'),
    GREATEST(v_cost, 0),
    v_qty,
    v_qty
  )
  RETURNING id INTO v_batch_id;

  RETURN v_batch_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_journal_entry(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lines JSONB;
  v_line JSONB;
  v_entry_id UUID;
  v_entry_no TEXT;
  v_idempotency TEXT;
  v_total_debit NUMERIC := 0;
  v_total_credit NUMERIC := 0;
  v_account_id UUID;
  v_account_code TEXT;
  v_line_account_id UUID;
  v_cash_account_id UUID;
  v_debit NUMERIC;
  v_credit NUMERIC;
  v_idx INT := 0;
  v_document_type TEXT;
  v_document_id UUID;
  v_description TEXT;
  v_date TIMESTAMPTZ;
  v_entry_date DATE;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Journal payload tələb olunur';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    SELECT id INTO v_entry_id
    FROM public.journal_entries
    WHERE idempotency_key = v_idempotency
    LIMIT 1;
    IF FOUND THEN
      RETURN v_entry_id;
    END IF;
  END IF;

  v_lines := COALESCE(p_payload->'lines', '[]'::jsonb);
  IF jsonb_typeof(v_lines) <> 'array' OR jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Journal sətirləri tələb olunur';
  END IF;

  FOR v_idx IN 0 .. jsonb_array_length(v_lines) - 1 LOOP
    v_line := v_lines->v_idx;
    v_debit := COALESCE((v_line->>'debit')::numeric, 0);
    v_credit := COALESCE((v_line->>'credit')::numeric, 0);

    IF v_debit < 0 OR v_credit < 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Debet və kredit mənfi ola bilməz';
    END IF;

    IF v_debit > 0 AND v_credit > 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Eyni sətirdə debet və kredit eyni vaxtda ola bilməz';
    END IF;

    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
  END LOOP;

  IF abs(v_total_debit - v_total_credit) > 0.0001 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = format('Journal balanssızdir (debet=%s, kredit=%s)', v_total_debit, v_total_credit);
  END IF;

  v_document_type := COALESCE(
    NULLIF(trim(p_payload->>'document_type'), ''),
    NULLIF(trim(p_payload->>'source_type'), ''),
    'manual'
  );
  v_document_id := COALESCE(
    NULLIF(p_payload->>'document_id', '')::uuid,
    NULLIF(p_payload->>'source_id', '')::uuid
  );
  v_description := COALESCE(
    NULLIF(trim(p_payload->>'description'), ''),
    NULLIF(trim(p_payload->>'memo'), '')
  );
  v_date := COALESCE(
    NULLIF(p_payload->>'date', '')::timestamptz,
    NULLIF(p_payload->>'entry_date', '')::date::timestamptz,
    NOW()
  );
  v_entry_date := COALESCE(
    NULLIF(p_payload->>'entry_date', '')::date,
    (v_date AT TIME ZONE 'UTC')::date,
    CURRENT_DATE
  );

  v_entry_no := COALESCE(
    NULLIF(trim(p_payload->>'entry_no'), ''),
    'JE-' || to_char(v_entry_date, 'YYYYMMDD') || '-' || floor(1000 + random() * 9000)::int
  );

  INSERT INTO public.journal_entries (
    entry_no,
    entry_date,
    date,
    source_type,
    source_id,
    document_type,
    document_id,
    description,
    idempotency_key,
    memo,
    created_by
  )
  VALUES (
    v_entry_no,
    v_entry_date,
    v_date,
    v_document_type,
    v_document_id,
    v_document_type,
    v_document_id,
    v_description,
    v_idempotency,
    v_description,
    auth.uid()
  )
  RETURNING id INTO v_entry_id;

  FOR v_idx IN 0 .. jsonb_array_length(v_lines) - 1 LOOP
    v_line := v_lines->v_idx;

    v_line_account_id := NULLIF(v_line->>'account_id', '')::uuid;
    v_cash_account_id := NULLIF(v_line->>'cash_account_id', '')::uuid;
    v_account_id := NULLIF(v_line->>'coa_id', '')::uuid;
    v_account_code := COALESCE(
      NULLIF(trim(v_line->>'account_code'), ''),
      NULLIF(trim(v_line->>'coa_code'), '')
    );

    IF v_account_id IS NULL AND v_account_code IS NOT NULL THEN
      v_account_id := public.resolve_gl_account_id(v_account_code);
    END IF;

    IF v_account_id IS NULL AND v_line_account_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.chart_of_accounts WHERE id = v_line_account_id) THEN
      v_account_id := v_line_account_id;
    END IF;

    IF v_cash_account_id IS NULL AND v_line_account_id IS NOT NULL
       AND v_line_account_id IS DISTINCT FROM v_account_id
       AND EXISTS (SELECT 1 FROM public.accounts WHERE id = v_line_account_id) THEN
      v_cash_account_id := v_line_account_id;
    END IF;

    IF v_account_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0002',
        MESSAGE = format(
          'Hesab tapılmadı: %s',
          COALESCE(v_account_code, v_line->>'coa_id', v_line->>'account_id')
        );
    END IF;

    INSERT INTO public.journal_entry_lines (
      journal_entry_id,
      coa_id,
      debit,
      credit,
      partner_type,
      partner_id,
      account_id,
      line_memo
    )
    VALUES (
      v_entry_id,
      v_account_id,
      COALESCE((v_line->>'debit')::numeric, 0),
      COALESCE((v_line->>'credit')::numeric, 0),
      NULLIF(trim(v_line->>'partner_type'), ''),
      NULLIF(v_line->>'partner_id', '')::uuid,
      v_cash_account_id,
      COALESCE(
        NULLIF(trim(v_line->>'line_memo'), ''),
        NULLIF(trim(v_line->>'memo'), '')
      )
    );
  END LOOP;

  RETURN v_entry_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_manual_expense_transaction(p_category text, p_amount numeric, p_account_id uuid, p_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx_id UUID;
  v_category_id UUID;
  v_desc TEXT;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required' USING ERRCODE = '22023';
  END IF;

  v_category_id := resolve_financial_category_id(p_category, 'EXPENSE');
  v_desc := COALESCE(NULLIF(trim(p_description), ''), NULLIF(trim(p_notes), ''), p_category, 'Əl ilə xərc');

  v_tx_id := post_cash_transaction(
    p_account_id,
    'Məxaric',
    p_amount,
    COALESCE(p_category, 'Digər'),
    v_desc,
    NULL,
    'manual_expense',
    NULL
  );

  UPDATE transactions
  SET
    unified_type = 'EXPENSE',
    category_id = v_category_id,
    reference_type = 'manual_expense',
    description = v_desc,
    transaction_date = COALESCE(transaction_date, created_at, NOW()),
    created_by = p_created_by
  WHERE id = v_tx_id;

  RETURN v_tx_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_partner_payment(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_existing public.payments%ROWTYPE;
  v_partner_id UUID;
  v_amount NUMERIC;
  v_payment_type TEXT;
  v_payment_method TEXT;
  v_payment_date TIMESTAMPTZ;
  v_reference_note TEXT;
  v_cash_account_id UUID;
  v_balance NUMERIC;
  v_payment_id UUID;
  v_tx_id UUID;
  v_journal_id UUID;
  v_tx_type TEXT;
  v_category TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Ödəniş payload tələb olunur';
  END IF;

  IF NOT public.require_permission('can_manage_finance') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501', MESSAGE = 'Maliyyə əməliyyatı üçün icazəniz yoxdur';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.payments
    WHERE idempotency_key = v_idempotency
    LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_existing.id,
        'journal_entry_id', v_existing.journal_entry_id,
        'transaction_id', v_existing.transaction_id,
        'idempotent', true
      );
    END IF;
  END IF;

  v_partner_id := NULLIF(p_payload->>'partner_id', '')::uuid;
  v_amount := COALESCE(NULLIF(p_payload->>'amount', '')::numeric, 0);
  v_payment_type := lower(trim(COALESCE(p_payload->>'payment_type', '')));
  v_payment_method := lower(trim(COALESCE(p_payload->>'payment_method', 'cash')));
  v_payment_date := COALESCE(NULLIF(p_payload->>'payment_date', '')::timestamptz, NOW());
  v_reference_note := NULLIF(trim(p_payload->>'reference_note'), '');
  v_cash_account_id := NULLIF(p_payload->>'cash_account_id', '')::uuid;

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Tərəfdaş seçilməlidir';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  IF v_payment_type NOT IN ('in', 'out') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'payment_type «in» və ya «out» olmalıdır';
  END IF;

  IF v_payment_method NOT IN ('cash', 'bank') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'payment_method «cash» və ya «bank» olmalıdır';
  END IF;

  PERFORM id FROM public.partners WHERE id = v_partner_id AND is_deleted = FALSE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'partner_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Tərəfdaş tapılmadı';
  END IF;

  IF v_cash_account_id IS NULL THEN
    v_cash_account_id := public.resolve_default_cash_account_id(v_payment_method);
  END IF;

  IF v_cash_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;

  SELECT balance INTO v_balance
  FROM public.accounts
  WHERE id = v_cash_account_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;

  IF v_payment_type = 'out' AND COALESCE(v_balance, 0) + 0.0001 < v_amount THEN
    RAISE EXCEPTION 'insufficient_balance' USING ERRCODE = '22023', MESSAGE = 'Hesab balansı kifayət etmir';
  END IF;

  INSERT INTO public.payments (
    payment_date,
    partner_id,
    amount,
    payment_type,
    payment_method,
    reference_note,
    cash_account_id,
    idempotency_key,
    created_by
  )
  VALUES (
    v_payment_date,
    v_partner_id,
    v_amount,
    v_payment_type,
    v_payment_method,
    v_reference_note,
    v_cash_account_id,
    v_idempotency,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  v_tx_type := CASE WHEN v_payment_type = 'in' THEN 'Mədaxil' ELSE 'Məxaric' END;
  v_category := CASE
    WHEN v_payment_type = 'in' THEN 'Tərəfdaşdan mədaxil'
    ELSE 'Tərəfdaşa məxaric'
  END;

  INSERT INTO public.transactions (
    account_id,
    amount,
    type,
    unified_type,
    category,
    notes,
    description,
    transaction_date,
    created_at,
    reference_type,
    reference_id,
    source_type,
    source_id
  )
  VALUES (
    v_cash_account_id,
    v_amount,
    v_tx_type,
    CASE WHEN v_payment_type = 'in' THEN 'INCOME' ELSE 'EXPENSE' END,
    v_category,
    COALESCE(v_reference_note, v_category),
    COALESCE(v_reference_note, v_category),
    v_payment_date,
    NOW(),
    'partner_payment',
    v_payment_id,
    'partner_payment',
    v_payment_id
  )
  RETURNING id INTO v_tx_id;

  IF v_payment_type = 'in' THEN
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) + v_amount
    WHERE id = v_cash_account_id;
  ELSE
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) - v_amount
    WHERE id = v_cash_account_id;
  END IF;

  v_journal_id := public.post_partner_payment_gl_journal(
    v_payment_id,
    v_partner_id,
    v_amount,
    v_payment_type,
    v_payment_method,
    v_cash_account_id,
    v_reference_note
  );

  UPDATE public.payments
  SET journal_entry_id = v_journal_id,
      transaction_id = v_tx_id
  WHERE id = v_payment_id;

  UPDATE public.transactions
  SET journal_entry_id = v_journal_id
  WHERE id = v_tx_id;

  PERFORM public.refresh_partner_linked_balances(v_partner_id);

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'journal_entry_id', v_journal_id,
    'transaction_id', v_tx_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_production_expense_atomic(p_production_order_id uuid, p_code text, p_category text, p_description text, p_amount numeric, p_expense_date date, p_account_id uuid, p_account_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx_id UUID;
  v_finance_expense_id UUID;
  v_production_expense_id UUID;
  v_memo TEXT;
  v_category_id UUID;
BEGIN
  IF NOT public.user_has_permission('can_manage_production') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'İcazəniz yoxdur';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;
  IF p_category NOT IN ('transport', 'delivery', 'installation', 'tools', 'other') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Xərc kateqoriyası keçərli deyil';
  END IF;
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.production_orders WHERE id = p_production_order_id) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'İstehsal sifarişi tapılmadı';
  END IF;

  v_memo := COALESCE(
    NULLIF(trim(p_notes), ''),
    format('İstehsalat: %s', trim(p_description))
  );

  v_tx_id := public.post_cash_transaction(
    p_account_id,
    'Məxaric',
    p_amount,
    'Digər',
    v_memo,
    p_production_order_id,
    'production_expense',
    p_production_order_id
  );

  INSERT INTO public.expenses (code, category, amount, account_id, production_order_id, notes)
  VALUES (
    trim(p_code),
    'Digər',
    p_amount,
    p_account_id,
    p_production_order_id,
    NULLIF(trim(p_notes), '')
  )
  RETURNING id INTO v_finance_expense_id;

  INSERT INTO public.production_expenses (
    production_order_id, category, description, amount, expense_date,
    account_id, account_name, finance_expense_id, finance_transaction_id,
    is_posted_to_finance, notes, created_by, created_by_name
  )
  VALUES (
    p_production_order_id, p_category, trim(p_description), p_amount,
    COALESCE(p_expense_date, CURRENT_DATE), p_account_id, NULLIF(trim(p_account_name), ''),
    v_finance_expense_id, v_tx_id, true, NULLIF(trim(p_notes), ''), auth.uid(),
    NULLIF(trim(p_actor_name), '')
  )
  RETURNING id INTO v_production_expense_id;

  v_category_id := public.resolve_financial_category_id(COALESCE(p_category, 'İstehsalat xərci'), 'EXPENSE');

  UPDATE public.transactions
  SET
    unified_type = 'EXPENSE',
    category_id = v_category_id,
    reference_type = 'production_expense',
    reference_id = v_production_expense_id,
    source_type = 'production_expense',
    source_id = v_production_expense_id,
    production_order_id = p_production_order_id,
    description = v_memo
  WHERE id = v_tx_id;

  RETURN v_production_expense_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_supplier_id UUID;
  v_purchase_id UUID;
  v_invoice_number TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_debt_amount NUMERIC;
  v_item JSONB;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_unit_price NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_account_balance NUMERIC;
  v_supplier_balance NUMERIC;
  v_account_name TEXT;
  v_pay_note TEXT;
  v_stock_demand JSONB := '{}'::jsonb;
  v_price_map JSONB := '{}'::jsonb;
  v_key TEXT;
BEGIN
  IF NOT public.require_permission('can_edit_purchases') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Alış yaratmaq üçün icazəniz yoxdur';
  END IF;

  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Alış məlumatları göndərilməyib';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir məhsul tələb olunur';
  END IF;

  v_supplier_id := NULLIF(v_header->>'supplier_id', '')::uuid;
  IF v_supplier_id IS NULL THEN
    RAISE EXCEPTION 'supplier_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Təchizatçı seçilməlidir';
  END IF;

  PERFORM id FROM suppliers WHERE id = v_supplier_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Təchizatçı tapılmadı';
  END IF;

  v_total_amount := COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0);
  v_paid_amount := COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0);
  v_debt_amount := COALESCE(
    NULLIF(v_header->>'debt_amount', '')::numeric,
    GREATEST(v_total_amount - v_paid_amount, 0)
  );

  IF v_paid_amount > v_total_amount + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  IF abs((v_paid_amount + v_debt_amount) - v_total_amount) > 0.01 THEN
    RAISE EXCEPTION 'amount_mismatch'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən və borc məbləğlərinin cəmi ümumi məbləğə bərabər olmalıdır';
  END IF;

  -- Aggregate stock increases per product (last unit_price wins per key)
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
    v_qty := COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0);
    v_unit_price := COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0);

    IF v_product_id IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'invalid_item'
        USING ERRCODE = '22023',
              MESSAGE = 'Hər sətirdə məhsul və miqdar tələb olunur';
    END IF;

    v_key := v_product_id::text;
    v_stock_demand := jsonb_set(
      v_stock_demand,
      ARRAY[v_key],
      to_jsonb(COALESCE((v_stock_demand->>v_key)::numeric, 0) + v_qty),
      true
    );
    v_price_map := jsonb_set(v_price_map, ARRAY[v_key], to_jsonb(v_unit_price), true);
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    PERFORM id FROM products WHERE id = v_key::uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Məhsul tapılmadı: ' || v_key;
    END IF;
  END LOOP;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  v_invoice_number := COALESCE(
    NULLIF(trim(v_header->>'invoice_number'), ''),
    NULLIF(trim(p_payload->>'invoice_number'), ''),
    'PUR-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int
  );

  INSERT INTO purchases (
    invoice_number,
    supplier_id,
    warehouse_id,
    doc_date,
    responsible_id,
    responsible_name,
    total_amount,
    paid_amount,
    debt_amount,
    status,
    notes
  )
  VALUES (
    v_invoice_number,
    v_supplier_id,
    NULLIF(v_header->>'warehouse_id', '')::uuid,
    COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
    NULLIF(v_header->>'responsible_id', '')::uuid,
    NULLIF(trim(v_header->>'responsible_name'), ''),
    v_total_amount,
    v_paid_amount,
    v_debt_amount,
    COALESCE(
      NULLIF(trim(v_header->>'status'), ''),
      CASE WHEN v_debt_amount > 0.0001 THEN 'Borclu' ELSE 'Ödənilib' END
    ),
    NULLIF(trim(v_header->>'notes'), '')
  )
  RETURNING id INTO v_purchase_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    INSERT INTO purchase_items (
      purchase_id,
      product_id,
      product_code,
      product_name,
      quantity,
      unit,
      unit_price,
      total_price
    )
    VALUES (
      v_purchase_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ədəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(
        NULLIF(v_item->>'total_price', '')::numeric,
        NULLIF(v_item->>'total', '')::numeric,
        0
      )
    );
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);
    v_unit_price := COALESCE((v_price_map->>v_key)::numeric, 0);

    SELECT stock INTO v_stock
    FROM products
    WHERE id = v_product_id
    FOR UPDATE;

    UPDATE products
    SET
      stock = COALESCE(v_stock, 0) + v_qty,
      buy_price = v_unit_price
    WHERE id = v_product_id;
  END LOOP;

  IF v_debt_amount > 0.0001 THEN
    SELECT balance INTO v_supplier_balance
    FROM suppliers
    WHERE id = v_supplier_id
    FOR UPDATE;

    UPDATE suppliers
    SET balance = COALESCE(v_supplier_balance, 0) + v_debt_amount
    WHERE id = v_supplier_id;
  END IF;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      SELECT balance, name
      INTO v_account_balance, v_account_name
      FROM accounts
      WHERE id = v_account_id
      FOR UPDATE;

      v_pay_note := COALESCE(
        NULLIF(trim(v_pay->>'note'), ''),
        format('Alış fakturası %s', v_invoice_number)
      );
      IF NULLIF(trim(v_pay->>'payment_date'), '') IS NOT NULL THEN
        v_pay_note := trim(v_pay->>'payment_date') || ' — ' || v_pay_note;
      END IF;
      IF v_account_name IS NOT NULL THEN
        v_pay_note := v_pay_note || ' — ' || v_account_name;
      END IF;

      INSERT INTO transactions (account_id, type, amount, category, notes)
      VALUES (
        v_account_id,
        'Məxaric',
        v_pay_amount,
        'Alış Ödənişi',
        v_pay_note
      );

      UPDATE accounts
      SET balance = COALESCE(v_account_balance, 0) - v_pay_amount
      WHERE id = v_account_id;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'purchase_id', v_purchase_id,
    'invoice_number', v_invoice_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_safety_stock_request(p_product_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product RECORD;
  v_min NUMERIC;
  v_stock NUMERIC;
  v_qty NUMERIC;
  v_existing UUID;
  v_request_id UUID;
  v_no TEXT;
  v_cfg JSONB;
  v_auto BOOLEAN;
  v_lead INT;
BEGIN
  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'procurement_config';

  v_auto := COALESCE((v_cfg ->> 'auto_create_purchase_request')::boolean, true);
  IF NOT v_auto THEN
    RETURN NULL;
  END IF;

  v_lead := GREATEST(COALESCE((v_cfg ->> 'default_lead_time_days')::int, 7), 0);

  SELECT
    id,
    code,
    name,
    unit,
    COALESCE(is_service, FALSE) AS is_service,
    COALESCE(stock, 0) AS stock,
    COALESCE(min_stock_level, min_stock, 0) AS min_level
    INTO v_product
    FROM public.products
   WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_product.is_service THEN
    RETURN NULL;
  END IF;

  v_min := COALESCE(v_product.min_level, 0);
  v_stock := COALESCE(v_product.stock, 0);

  IF v_min <= 0 OR v_stock > v_min THEN
    RETURN NULL;
  END IF;

  SELECT id
    INTO v_existing
    FROM public.purchase_requests
   WHERE product_id = p_product_id
     AND status IN ('auto_triggered', 'pending', 'ordered')
     AND source = 'safety_stock'
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  v_qty := GREATEST(v_min, v_min - v_stock, 1);
  v_no := 'ASR-' || to_char(NOW(), 'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);

  INSERT INTO public.purchase_requests (
    request_no,
    production_order_id,
    product_id,
    product_code,
    product_name,
    warehouse_id,
    quantity,
    unit,
    status,
    source,
    notes
  )
  VALUES (
    v_no,
    NULL,
    v_product.id,
    v_product.code,
    v_product.name,
    NULL,
    v_qty,
    COALESCE(v_product.unit, 'Ədəd'),
    'auto_triggered',
    'safety_stock',
    format(
      'Avtomatik: stok %s ≤ minimum hədd %s. Təxmini çatdırılma: %s gün',
      to_char(v_stock, 'FM999999990.00'),
      to_char(v_min, 'FM999999990.00'),
      v_lead::text
    )
  )
  RETURNING id INTO v_request_id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_sale_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_decrement_stock BOOLEAN := true;
  v_customer_id UUID;
  v_customer_name TEXT;
  v_sale_id UUID;
  v_doc_no TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_item JSONB;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_pay_method TEXT;
  v_skip_stock BOOLEAN;
  v_polywood_mode TEXT;
  v_item_ids JSONB := '[]'::jsonb;
  v_item_id UUID;
  v_idx INT := 0;
  v_stock_demand JSONB := '{}'::jsonb;
  v_key TEXT;
BEGIN
  IF NOT public.require_permission('can_edit_sales') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış yaratmaq üçün icazəniz yoxdur';
  END IF;

  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış məlumatları göndərilməyib';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir satış sətri tələb olunur';
  END IF;

  IF (p_payload ? 'decrement_stock') THEN
    v_decrement_stock := COALESCE((p_payload->>'decrement_stock')::boolean, true);
  END IF;

  v_customer_id := NULLIF(v_header->>'customer_id', '')::uuid;
  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Müştəri seçilməlidir';
  END IF;

  SELECT COALESCE(NULLIF(trim(full_name), ''), NULLIF(trim(name), ''), NULLIF(trim(company_name), ''), '')
  INTO v_customer_name
  FROM customers
  WHERE id = v_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  v_total_amount := COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0);
  v_paid_amount := COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0);
  v_remaining := GREATEST(
    COALESCE(
      NULLIF(v_header->>'remaining_balance', '')::numeric,
      v_total_amount - v_paid_amount
    ),
    0
  );

  IF v_paid_amount > v_total_amount + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  -- Aggregate stock demand per product (standard lines only)
  IF v_decrement_stock THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
    LOOP
      v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
      v_qty := COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0);
      v_polywood_mode := NULLIF(trim(v_item->>'polywood_sale_mode'), '');
      v_skip_stock := COALESCE((v_item->>'skip_stock')::boolean, false);

      IF v_product_id IS NULL OR v_qty <= 0 OR v_polywood_mode IS NOT NULL OR v_skip_stock THEN
        CONTINUE;
      END IF;

      v_key := v_product_id::text;
      v_stock_demand := jsonb_set(
        v_stock_demand,
        ARRAY[v_key],
        to_jsonb(COALESCE((v_stock_demand->>v_key)::numeric, 0) + v_qty),
        true
      );
    END LOOP;

    FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
    LOOP
      v_product_id := v_key::uuid;
      v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);

      SELECT stock INTO v_stock
      FROM products
      WHERE id = v_product_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'product_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Məhsul tapılmadı: ' || v_key;
      END IF;

      IF COALESCE(v_stock, 0) + 0.000001 < v_qty THEN
        RAISE EXCEPTION 'insufficient_stock'
          USING ERRCODE = '22023',
                MESSAGE = format(
                  'Stok kifayət etmir (məhsul %s, tələb: %s, mövcud: %s)',
                  v_key,
                  trim(to_char(v_qty, 'FM999999990.00')),
                  trim(to_char(COALESCE(v_stock, 0), 'FM999999990.00'))
                );
      END IF;
    END LOOP;
  END IF;

  -- Validate payment accounts before writing
  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  v_doc_no := NULLIF(trim(v_header->>'doc_no'), '');
  IF v_doc_no IS NULL THEN
    v_doc_no := 'SF-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int;
  END IF;

  INSERT INTO sales (
    doc_no,
    invoice_number,
    doc_date,
    customer_id,
    customer_name,
    seller_id,
    seller_name,
    warehouse_name,
    subtotal,
    discount_total,
    vat_total,
    total_amount,
    paid_amount,
    remaining_balance,
    delivery_address,
    delivery_type,
    delivery_fee,
    note,
    notes,
    payments,
    created_at
  )
  VALUES (
    v_doc_no,
    COALESCE(NULLIF(trim(v_header->>'invoice_number'), ''), v_doc_no),
    COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
    v_customer_id,
    COALESCE(NULLIF(trim(v_header->>'customer_name'), ''), v_customer_name),
    NULLIF(v_header->>'seller_id', '')::uuid,
    NULLIF(trim(v_header->>'seller_name'), ''),
    NULLIF(trim(v_header->>'warehouse_name'), ''),
    COALESCE(NULLIF(v_header->>'subtotal', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'discount_total', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'vat_total', '')::numeric, 0),
    v_total_amount,
    v_paid_amount,
    v_remaining,
    NULLIF(trim(v_header->>'delivery_address'), ''),
    COALESCE(NULLIF(trim(v_header->>'delivery_type'), ''), 'free'),
    COALESCE(NULLIF(v_header->>'delivery_fee', '')::numeric, 0),
    NULLIF(trim(v_header->>'note'), ''),
    NULLIF(trim(v_header->>'notes'), ''),
    COALESCE(v_header->'payments', v_payments, '[]'::jsonb),
    COALESCE(NULLIF(v_header->>'created_at', '')::timestamptz, NOW())
  )
  RETURNING id INTO v_sale_id;

  -- Insert line items
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    INSERT INTO sale_items (
      sale_id,
      product_id,
      product_code,
      product_name,
      warehouse_id,
      warehouse_name,
      quantity,
      unit,
      unit_price,
      discount_percent,
      vat_rate,
      line_total,
      extra_info,
      polywood_sale_mode,
      polywood_length_m
    )
    VALUES (
      v_sale_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      NULLIF(v_item->>'warehouse_id', '')::uuid,
      NULLIF(trim(v_item->>'warehouse_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ədəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'discount_percent', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'vat_rate', '')::numeric, 0),
      COALESCE(
        NULLIF(v_item->>'line_total', '')::numeric,
        NULLIF(v_item->>'total', '')::numeric,
        0
      ),
      NULLIF(trim(v_item->>'extra_info'), ''),
      NULLIF(trim(v_item->>'polywood_sale_mode'), ''),
      NULLIF(v_item->>'polywood_length_m', '')::numeric
    )
    RETURNING id INTO v_item_id;

    v_item_ids := v_item_ids || jsonb_build_array(
      jsonb_build_object(
        'index', v_idx,
        'id', v_item_id,
        'product_id', NULLIF(v_item->>'product_id', '')::uuid,
        'polywood_sale_mode', NULLIF(trim(v_item->>'polywood_sale_mode'), '')
      )
    );
    v_idx := v_idx + 1;
  END LOOP;

  -- Deduct aggregated stock
  IF v_decrement_stock THEN
    FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
    LOOP
      v_product_id := v_key::uuid;
      v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);

      UPDATE products
      SET stock = COALESCE(stock, 0) - v_qty
      WHERE id = v_product_id;
    END LOOP;
  END IF;

  -- Cash payments: transactions + account balance
  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      v_pay_method := COALESCE(NULLIF(trim(v_pay->>'method'), ''), 'Ödəniş');

      SELECT balance INTO v_stock
      FROM accounts
      WHERE id = v_account_id
      FOR UPDATE;

      INSERT INTO transactions (account_id, type, amount, category, notes)
      VALUES (
        v_account_id,
        'Mədaxil',
        v_pay_amount,
        'Satış Ödənişi',
        format('Satış fakturası %s — %s', v_doc_no, v_pay_method)
      );

      UPDATE accounts
      SET balance = COALESCE(v_stock, 0) + v_pay_amount
      WHERE id = v_account_id;
    END LOOP;
  END IF;

  -- Accounts receivable on customer master
  IF v_remaining > 0.0001 THEN
    SELECT balance INTO v_stock
    FROM customers
    WHERE id = v_customer_id
    FOR UPDATE;

    UPDATE customers
    SET balance = COALESCE(v_stock, 0) + v_remaining
    WHERE id = v_customer_id;
  END IF;

  RETURN jsonb_build_object(
    'sale_id', v_sale_id,
    'doc_no', v_doc_no,
    'items', v_item_ids
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_document_cash_transactions(p_source_type text, p_source_id uuid, p_doc_label text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx RECORD;
  v_deleted INT := 0;
  v_account_ids UUID[] := ARRAY[]::UUID[];
  v_label TEXT;
BEGIN
  v_label := trim(COALESCE(p_doc_label, ''));

  FOR v_tx IN
    SELECT id, account_id
    FROM transactions
    WHERE (
      (p_source_id IS NOT NULL AND source_type = p_source_type AND source_id = p_source_id)
      OR (
        v_label <> ''
        AND COALESCE(source_type, '') = ''
        AND COALESCE(source_id::text, '') = ''
        AND notes ILIKE '%' || v_label || '%'
      )
    )
  LOOP
    DELETE FROM transactions WHERE id = v_tx.id;
    v_deleted := v_deleted + 1;
    IF v_tx.account_id IS NOT NULL
       AND NOT v_tx.account_id = ANY (v_account_ids) THEN
      v_account_ids := array_append(v_account_ids, v_tx.account_id);
    END IF;
  END LOOP;

  PERFORM public.reconcile_accounts_for_transactions(v_account_ids);
  RETURN v_deleted;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_sale_invoice_audit_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_delegate BOOLEAN;
  v_profile_id UUID;
  v_employee_id UUID;
  v_display_name TEXT;
BEGIN
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.created_by := v_actor;
  v_delegate := public.can_delegate_invoice_issuer();

  IF v_delegate AND NEW.issued_by IS NOT NULL AND NEW.issued_by <> v_actor THEN
    SELECT p.id, p.employee_id, COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(p.full_name), ''), '')
    INTO v_profile_id, v_employee_id, v_display_name
    FROM profiles p
    LEFT JOIN employees e ON e.id = p.employee_id
    WHERE p.id = NEW.issued_by
      AND COALESCE(p.is_active, true);

    IF NOT FOUND THEN
      NEW.issued_by := v_actor;
    ELSE
      IF NEW.seller_id IS NULL AND v_employee_id IS NOT NULL THEN
        NEW.seller_id := v_employee_id;
      END IF;
      IF COALESCE(NULLIF(trim(NEW.seller_name), ''), '') = '' AND v_display_name <> '' THEN
        NEW.seller_name := v_display_name;
      END IF;
    END IF;
  ELSIF v_delegate AND NEW.seller_id IS NOT NULL THEN
    SELECT p.id, COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(p.full_name), ''), '')
    INTO v_profile_id, v_display_name
    FROM profiles p
    LEFT JOIN employees e ON e.id = p.employee_id
    WHERE p.employee_id = NEW.seller_id
      AND COALESCE(p.is_active, true)
    ORDER BY p.created_at
    LIMIT 1;

    NEW.issued_by := COALESCE(v_profile_id, v_actor);
    IF COALESCE(NULLIF(trim(NEW.seller_name), ''), '') = '' AND v_display_name <> '' THEN
      NEW.seller_name := v_display_name;
    END IF;
  ELSE
    NEW.issued_by := v_actor;

    SELECT p.employee_id, COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(p.full_name), ''), '')
    INTO v_employee_id, v_display_name
    FROM profiles p
    LEFT JOIN employees e ON e.id = p.employee_id
    WHERE p.id = v_actor;

    IF NOT v_delegate THEN
      IF v_employee_id IS NOT NULL THEN
        NEW.seller_id := v_employee_id;
      END IF;
      IF COALESCE(NULLIF(trim(NEW.seller_name), ''), '') = '' AND v_display_name <> '' THEN
        NEW.seller_name := v_display_name;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_inventory_barcode()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.barcode IS NULL OR btrim(NEW.barcode) = '' THEN
    NEW.barcode := CASE TG_TABLE_NAME
      WHEN 'polywood_pieces' THEN 'PW'
      ELSE 'DG'
    END || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 11));
  END IF;
  IF NEW.qr_code IS NULL OR btrim(NEW.qr_code) = '' THEN
    NEW.qr_code := NEW.barcode;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expense_cash_out(p_expense_id uuid, p_account_id uuid, p_amount numeric, p_date date, p_memo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp     public.expenses%ROWTYPE;
  v_balance NUMERIC;
  v_tx_id   UUID;
BEGIN
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id;

  SELECT balance INTO v_balance FROM public.accounts WHERE id = p_account_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;
  IF COALESCE(v_balance, 0) + 0.0001 < p_amount THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = format('Kassa/bank balansı kifayət etmir (lazım: %s, mövcud: %s)',
        trim(to_char(p_amount, 'FM999999990.00')),
        trim(to_char(COALESCE(v_balance, 0), 'FM999999990.00')));
  END IF;

  INSERT INTO public.transactions (
    account_id, type, amount, category, category_id, notes, description,
    source_type, source_id, reference_type, reference_id,
    unified_type, transaction_date, created_by, production_order_id
  )
  VALUES (
    p_account_id, 'Məxaric', p_amount, v_exp.category, v_exp.category_id,
    NULLIF(trim(v_exp.notes), ''), p_memo,
    'expense', v_exp.id, 'expense', v_exp.id,
    'EXPENSE', p_date::timestamptz, auth.uid(), v_exp.production_order_id
  )
  RETURNING id INTO v_tx_id;

  UPDATE public.accounts SET balance = COALESCE(v_balance, 0) - p_amount WHERE id = p_account_id;
  RETURN v_tx_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fifo_deplete_product(p_product_id uuid, p_quantity numeric, p_sale_id uuid, p_sale_item_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining NUMERIC := COALESCE(p_quantity, 0);
  v_batch RECORD;
  v_take NUMERIC;
  v_line_cogs NUMERIC := 0;
  v_fallback_cost NUMERIC := 0;
BEGIN
  IF p_product_id IS NULL OR v_remaining <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_batch IN
    SELECT id, remaining_qty, unit_cost
    FROM public.inventory_batches
    WHERE product_id = p_product_id
      AND remaining_qty > 0
    ORDER BY created_at ASC, id ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0.0001;

    v_take := LEAST(v_remaining, v_batch.remaining_qty);

    UPDATE public.inventory_batches
    SET remaining_qty = remaining_qty - v_take
    WHERE id = v_batch.id;

    INSERT INTO public.inventory_batch_consumptions (
      sale_id,
      sale_item_id,
      batch_id,
      product_id,
      quantity,
      unit_cost,
      cogs_amount
    )
    VALUES (
      p_sale_id,
      p_sale_item_id,
      v_batch.id,
      p_product_id,
      v_take,
      v_batch.unit_cost,
      ROUND(v_take * v_batch.unit_cost, 2)
    );

    v_line_cogs := v_line_cogs + ROUND(v_take * v_batch.unit_cost, 2);
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining > 0.0001 THEN
    SELECT COALESCE(buy_price, 0) INTO v_fallback_cost
    FROM public.products
    WHERE id = p_product_id;

    IF COALESCE(v_fallback_cost, 0) <= 0 THEN
      RAISE EXCEPTION 'insufficient_fifo_batches'
        USING ERRCODE = '22023',
              MESSAGE = format(
                'FIFO batch stoku kifayət etmir (məhsul %s, qalıq miqdar %s)',
                p_product_id,
                trim(to_char(v_remaining, 'FM999999990.00'))
              );
    END IF;

    INSERT INTO public.inventory_batch_consumptions (
      sale_id,
      sale_item_id,
      batch_id,
      product_id,
      quantity,
      unit_cost,
      cogs_amount
    )
    VALUES (
      p_sale_id,
      p_sale_item_id,
      NULL,
      p_product_id,
      v_remaining,
      v_fallback_cost,
      ROUND(v_remaining * v_fallback_cost, 2)
    );

    v_line_cogs := v_line_cogs + ROUND(v_remaining * v_fallback_cost, 2);
  END IF;

  RETURN ROUND(v_line_cogs, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.fifo_deplete_sale_item(p_sale_item_id uuid, p_product_id uuid, p_quantity numeric, p_sale_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_composite BOOLEAN := false;
  v_bom RECORD;
  v_component_qty NUMERIC;
  v_line_cogs NUMERIC := 0;
  v_component_cogs NUMERIC;
BEGIN
  IF p_product_id IS NULL OR COALESCE(p_quantity, 0) <= 0 THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(is_composite, false)
  INTO v_is_composite
  FROM public.products
  WHERE id = p_product_id;

  IF COALESCE(v_is_composite, false) THEN
    FOR v_bom IN
      SELECT component_product_id, quantity
      FROM public.product_bom
      WHERE parent_product_id = p_product_id
      ORDER BY component_product_id
    LOOP
      v_component_qty := COALESCE(p_quantity, 0) * COALESCE(v_bom.quantity, 1);
      v_component_cogs := public.fifo_deplete_product(
        v_bom.component_product_id,
        v_component_qty,
        p_sale_id,
        p_sale_item_id
      );
      v_line_cogs := v_line_cogs + COALESCE(v_component_cogs, 0);
    END LOOP;
  ELSE
    v_line_cogs := public.fifo_deplete_product(
      p_product_id,
      p_quantity,
      p_sale_id,
      p_sale_item_id
    );
  END IF;

  RETURN ROUND(COALESCE(v_line_cogs, 0), 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.find_erp_event_by_idempotency(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.erp_events%ROWTYPE;
BEGIN
  IF p_key IS NULL OR trim(p_key) = '' THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_row
  FROM public.erp_events
  WHERE idempotency_key = trim(p_key)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'event_id', v_row.id,
    'event_type', v_row.event_type,
    'source_table', v_row.source_table,
    'source_id', v_row.source_id,
    'journal_entry_id', v_row.journal_entry_id,
    'result', COALESCE(v_row.result, '{}'::jsonb),
    'already_processed', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_composite_available_stock(p_product_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_min NUMERIC;
BEGIN
  SELECT MIN(
    FLOOR(
      public.get_batch_available_stock(pb.component_product_id)
      / GREATEST(pb.quantity, 0.0001)
    )
  )
  INTO v_min
  FROM public.product_bom pb
  WHERE pb.parent_product_id = p_product_id;

  IF v_min IS NULL THEN
    RETURN 0;
  END IF;

  RETURN GREATEST(v_min, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_product_available_stock(p_product_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_composite BOOLEAN := false;
BEGIN
  SELECT COALESCE(is_composite, false)
  INTO v_is_composite
  FROM public.products
  WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  IF v_is_composite THEN
    RETURN public.get_composite_available_stock(p_product_id);
  END IF;

  RETURN public.get_batch_available_stock(p_product_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_journal_entry_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date DATE;
BEGIN
  v_date := COALESCE(
    (CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_date ELSE NEW.entry_date END),
    (CASE WHEN TG_OP = 'DELETE' THEN OLD.date::date ELSE NEW.date::date END),
    CURRENT_DATE
  );
  PERFORM public.assert_accounting_period_open(v_date);
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_profile_sensitive_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.id = auth.uid() AND NOT public.has_permission('can_manage_users') THEN
    IF NEW.role_id IS DISTINCT FROM OLD.role_id
       OR NEW.is_active IS DISTINCT FROM OLD.is_active
       OR NEW.employee_id IS DISTINCT FROM OLD.employee_id
       OR NEW.email IS DISTINCT FROM OLD.email
       OR NEW.id IS DISTINCT FROM OLD.id THEN
      RAISE EXCEPTION 'profile_update_forbidden'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.hr_unpaid_leave_deduction(p_employee_id uuid, p_month integer, p_year integer, p_base_salary numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_days INT := 0;
  v_daily_rate NUMERIC;
BEGIN
  SELECT COALESCE(SUM(public.hr_leave_days_in_month(l.start_date, l.end_date, p_month, p_year)), 0)
    INTO v_days
    FROM public.employee_leaves l
   WHERE l.employee_id = p_employee_id
     AND l.status = 'APPROVED'
     AND l.leave_type = 'UNPAID'
     AND l.start_date <= (date_trunc('month', make_date(p_year, p_month, 1)) + INTERVAL '1 month' - INTERVAL '1 day')::date
     AND l.end_date >= make_date(p_year, p_month, 1);

  IF v_days <= 0 OR COALESCE(p_base_salary, 0) <= 0 THEN
    RETURN 0;
  END IF;

  v_daily_rate := p_base_salary / 22.0;
  RETURN ROUND(v_daily_rate * v_days, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_book_qty(p_product_id uuid, p_warehouse_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_qty NUMERIC;
BEGIN
  IF EXISTS (SELECT 1 FROM public.products WHERE id = p_product_id AND inventory_mode = 'polywood') THEN
    SELECT ROUND(COALESCE(SUM(length_m), 0), 3) INTO v_qty
    FROM public.polywood_pieces
    WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id AND status = 'available';
    RETURN v_qty;
  END IF;

  SELECT current_stock INTO v_qty
  FROM public.warehouse_stocks
  WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
  LIMIT 1;
  IF FOUND THEN
    RETURN COALESCE(v_qty, 0);
  END IF;

  IF EXISTS (SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id AND is_default) THEN
    SELECT current_stock INTO v_qty
    FROM public.warehouse_stocks
    WHERE product_id = p_product_id AND warehouse_id IS NULL
    LIMIT 1;
    RETURN COALESCE(v_qty, 0);
  END IF;

  RETURN 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_item_derive()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_metric AND NEW.actual_full_sheets IS NULL AND NEW.actual_cut_pieces IS NULL THEN
    NEW.actual_qty := NULL;
  ELSIF NEW.is_metric THEN
    NEW.actual_qty := ROUND(
      COALESCE(NEW.actual_full_sheets, 0) * COALESCE(NEW.full_sheet_length_m, 0)
      + COALESCE((
          SELECT SUM(value::numeric)
          FROM jsonb_array_elements_text(COALESCE(NEW.actual_cut_pieces, '[]'::jsonb))
        ), 0),
      3
    );
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_post(p_count_id uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor     UUID := COALESCE(auth.uid(), p_actor);
  v_doc       public.inventory_counts;
  v_line      public.inventory_count_items;
  v_ref       CONSTANT TEXT := 'inventory_adjustment';
  v_book      NUMERIC;
  v_delta     NUMERIC;
  v_new_qty   NUMERIC;
  v_value     NUMERIC;
  v_surplus   NUMERIC := 0;
  v_shortage  NUMERIC := 0;
  v_moves     INTEGER := 0;
  v_journal   UUID;
  v_lines     JSONB;
  -- polywood piece reconciliation
  v_targets   NUMERIC[];
  v_target    NUMERIC;
  v_matched   UUID[];
  v_scanned   UUID[];
  v_piece_id  UUID;
  v_lengths   JSONB;
BEGIN
  PERFORM public._inventory_count_authorize('can_post_inventory_count');
  v_doc := public._inventory_count_lock(p_count_id, ARRAY['review']);

  IF public.is_accounting_period_closed(v_doc.count_date) THEN
    RAISE EXCEPTION '%', format(
      'Sənəd tarixi bağlı maliyyə dövrünə düşür (%s). Əvvəlcə dövrü açın.',
      to_char(v_doc.count_date, 'YYYY-MM')
    ) USING ERRCODE = '22023';
  END IF;

  FOR v_line IN
    SELECT * FROM public.inventory_count_items
    WHERE count_id = v_doc.id AND actual_qty IS NOT NULL
    ORDER BY line_no
    FOR UPDATE
  LOOP
    PERFORM 1 FROM public.products WHERE id = v_line.product_id FOR UPDATE;
    v_book := public.inventory_count_book_qty(v_line.product_id, v_doc.warehouse_id);

    IF v_line.is_metric THEN
      -- Pieces are physical identities: make the available set equal the
      -- counted set, keeping existing pieces (and their barcodes) wherever a
      -- counted length matches, scanned pieces first.
      SELECT COALESCE(array_agg(value::uuid), '{}') INTO v_scanned
      FROM jsonb_array_elements_text(v_line.scanned_piece_ids);

      SELECT COALESCE(array_agg(len ORDER BY len DESC), '{}') INTO v_targets
      FROM (
        SELECT v_line.full_sheet_length_m AS len
        FROM generate_series(1, COALESCE(v_line.actual_full_sheets, 0))
        UNION ALL
        SELECT value::numeric FROM jsonb_array_elements_text(COALESCE(v_line.actual_cut_pieces, '[]'::jsonb))
      ) t;

      v_matched := '{}';
      FOREACH v_target IN ARRAY v_targets LOOP
        SELECT pp.id INTO v_piece_id
        FROM public.polywood_pieces pp
        WHERE pp.product_id = v_line.product_id
          AND pp.warehouse_id = v_doc.warehouse_id
          AND pp.status = 'available'
          AND abs(pp.length_m - v_target) < 0.0005
          AND NOT (pp.id = ANY (v_matched))
        ORDER BY (pp.id = ANY (v_scanned)) DESC, pp.created_at
        LIMIT 1;

        IF v_piece_id IS NOT NULL THEN
          v_matched := v_matched || v_piece_id;
        ELSE
          INSERT INTO public.polywood_pieces (
            product_id, warehouse_id, length_m, piece_type, status, notes, source_document_id, updated_at
          ) VALUES (
            v_line.product_id, v_doc.warehouse_id, v_target,
            CASE WHEN abs(v_target - v_line.full_sheet_length_m) < 0.0005 THEN 'full' ELSE 'cut' END,
            'available', 'İnventarizasiya artığı — ' || v_doc.document_number, v_doc.id, NOW()
          )
          RETURNING id INTO v_piece_id;
          v_matched := v_matched || v_piece_id;
        END IF;
      END LOOP;

      UPDATE public.polywood_pieces
      SET status = 'consumed',
          notes = 'İnventarizasiya çatışmazlığı — ' || v_doc.document_number,
          updated_at = NOW()
      WHERE product_id = v_line.product_id
        AND warehouse_id = v_doc.warehouse_id
        AND status = 'available'
        AND NOT (id = ANY (v_matched));

      SELECT ROUND(COALESCE(SUM(length_m), 0), 3),
             COALESCE(jsonb_agg(length_m ORDER BY length_m DESC), '[]'::jsonb)
      INTO v_new_qty, v_lengths
      FROM public.polywood_pieces
      WHERE product_id = v_line.product_id AND warehouse_id = v_doc.warehouse_id AND status = 'available';

      v_delta := ROUND(v_new_qty - v_book, 3);
      PERFORM public._inventory_count_set_stock(v_line.product_id, v_doc.warehouse_id, v_new_qty, v_delta, v_lengths);
      v_value := ROUND(v_delta * v_line.unit_cost, 2);
    ELSE
      -- Apply the counted difference to today's stock (sales made after the
      -- shelf was counted stay booked).
      v_delta := ROUND(v_line.actual_qty - v_line.expected_qty, 4);
      v_new_qty := GREATEST(v_book + v_delta, 0);
      v_delta := v_new_qty - v_book;

      IF abs(v_delta) > 0.00005 THEN
        PERFORM public._inventory_count_set_stock(v_line.product_id, v_doc.warehouse_id, v_new_qty, v_delta);
      END IF;

      IF v_delta > 0 THEN
        PERFORM public.create_inventory_batch(v_line.product_id, v_doc.id, v_ref, v_line.unit_cost, v_delta);
        v_value := ROUND(v_delta * v_line.unit_cost, 2);
      ELSIF v_delta < 0 THEN
        v_value := -public._fifo_consume_for_document(
          v_line.product_id, -v_delta, v_ref, v_doc.id, v_line.unit_cost
        );
      ELSE
        v_value := 0;
      END IF;
    END IF;

    IF abs(v_delta) > 0.00005 THEN
      INSERT INTO public.stock_movements (
        product_id, warehouse_id, movement_type, quantity, unit,
        reference_type, reference_id, source_line_id, description, created_by
      ) VALUES (
        v_line.product_id, v_doc.warehouse_id,
        CASE WHEN v_delta > 0 THEN 'in' ELSE 'out' END,
        abs(v_delta), v_line.unit, v_ref, v_doc.id, v_line.id,
        'İnventarizasiya — ' || v_doc.document_number, v_actor
      );
      v_moves := v_moves + 1;
    END IF;

    IF v_value > 0 THEN
      v_surplus := v_surplus + v_value;
    ELSE
      v_shortage := v_shortage - v_value;
    END IF;

    UPDATE public.inventory_count_items
    SET applied_qty = v_delta, applied_value = v_value
    WHERE id = v_line.id;
  END LOOP;

  v_lines := '[]'::jsonb;
  IF v_surplus > 0 THEN
    v_lines := v_lines
      || jsonb_build_object('account_code', '1300', 'debit', v_surplus, 'credit', 0, 'line_memo', 'İnventarizasiya artığı — anbar')
      || jsonb_build_object('account_code', '4950', 'debit', 0, 'credit', v_surplus, 'line_memo', 'İnventarizasiya artığı');
  END IF;
  IF v_shortage > 0 THEN
    v_lines := v_lines
      || jsonb_build_object('account_code', '6250', 'debit', v_shortage, 'credit', 0, 'line_memo', 'İnventarizasiya çatışmazlığı')
      || jsonb_build_object('account_code', '1300', 'debit', 0, 'credit', v_shortage, 'line_memo', 'İnventarizasiya çatışmazlığı — anbar');
  END IF;

  IF jsonb_array_length(v_lines) > 0 THEN
    v_journal := public.create_journal_entry(jsonb_build_object(
      'document_type', 'inventory_count',
      'document_id', v_doc.id,
      'source_type', 'inventory_count',
      'source_id', v_doc.id,
      'idempotency_key', 'inventory_count:' || v_doc.id::text,
      'entry_date', v_doc.count_date,
      'description', format('İnventarizasiya — %s (%s)', v_doc.document_number, COALESCE(v_doc.warehouse_name, '')),
      'lines', v_lines
    ));
  END IF;

  UPDATE public.inventory_counts
  SET status = 'posted',
      posted_at = NOW(),
      posted_by = v_actor,
      journal_entry_id = v_journal,
      updated_at = NOW()
  WHERE id = v_doc.id;

  PERFORM public.inventory_count_refresh_totals(v_doc.id);

  RETURN jsonb_build_object(
    'document_number', v_doc.document_number,
    'movements', v_moves,
    'surplus_value', v_surplus,
    'shortage_value', v_shortage,
    'journal_entry_id', v_journal
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_reopen(p_count_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc public.inventory_counts;
BEGIN
  PERFORM public._inventory_count_authorize('can_writeoff_inventory');
  v_doc := public._inventory_count_lock(p_count_id, ARRAY['review']);
  UPDATE public.inventory_counts
  SET status = 'in_progress', submitted_at = NULL, updated_at = NOW()
  WHERE id = v_doc.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_resync_book(p_count_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc public.inventory_counts;
BEGIN
  PERFORM public._inventory_count_authorize('can_writeoff_inventory');
  v_doc := public._inventory_count_lock(p_count_id, ARRAY['in_progress', 'review']);

  UPDATE public.inventory_count_items i
  SET expected_qty = public.inventory_count_book_qty(i.product_id, v_doc.warehouse_id),
      unit_cost = public.inventory_count_unit_cost(i.product_id),
      drift_qty = 0
  WHERE i.count_id = v_doc.id;

