CREATE OR REPLACE FUNCTION public.inventory_count_scan(p_count_id uuid, p_code text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor   UUID := COALESCE(auth.uid(), p_actor);
  v_doc     public.inventory_counts;
  v_code    TEXT := NULLIF(trim(p_code), '');
  v_piece   public.polywood_pieces;
  v_product public.products;
  v_line    public.inventory_count_items;
  v_metric  BOOLEAN;
BEGIN
  PERFORM public._inventory_count_authorize('can_writeoff_inventory');
  v_doc := public._inventory_count_lock(p_count_id, ARRAY['in_progress']);

  IF v_code IS NULL THEN
    RAISE EXCEPTION '%', 'Barkod boşdur' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_piece FROM public.polywood_pieces
  WHERE barcode = v_code OR qr_code = v_code
  LIMIT 1;

  IF v_piece.id IS NOT NULL THEN
    SELECT * INTO v_product FROM public.products WHERE id = v_piece.product_id;
  ELSE
    SELECT * INTO v_product FROM public.products
    WHERE barcode = v_code OR qr_code = v_code OR code = v_code
    ORDER BY (barcode = v_code) IS TRUE DESC, (qr_code = v_code) IS TRUE DESC
    LIMIT 1;
  END IF;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION '%', format('Məhsul tapılmadı: %s', v_code) USING ERRCODE = 'P0002';
  END IF;
  IF COALESCE(v_product.is_service, FALSE) OR COALESCE(v_product.is_composite, FALSE) THEN
    RAISE EXCEPTION '%', format('«%s» anbarda sayılmır (xidmət/komplekt)', v_product.name) USING ERRCODE = '22023';
  END IF;

  v_metric := v_product.inventory_mode = 'polywood';
  IF v_metric AND v_piece.id IS NULL THEN
    RAISE EXCEPTION '%',
      format('«%s» hissə-hissə sayılır — hissənin barkodunu oxudun və ya bölgünü əl ilə daxil edin', v_product.name)
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_line FROM public.inventory_count_items
  WHERE count_id = v_doc.id AND product_id = v_product.id
  FOR UPDATE;

  IF v_line.id IS NULL THEN
    -- Found on the shelf but not in the count list: add it with its book qty.
    INSERT INTO public.inventory_count_items (
      count_id, line_no, product_id, product_code, product_name, unit, barcode,
      is_metric, full_sheet_length_m, expected_qty, expected_full_sheets, expected_cut_pieces, unit_cost
    )
    VALUES (
      v_doc.id,
      COALESCE((SELECT MAX(line_no) FROM public.inventory_count_items WHERE count_id = v_doc.id), 0) + 1,
      v_product.id, v_product.code, v_product.name,
      CASE WHEN v_metric THEN 'Metr' ELSE COALESCE(v_product.unit, 'Ədəd') END,
      v_product.barcode, v_metric,
      CASE WHEN v_metric THEN COALESCE(NULLIF(v_product.full_sheet_length_m, 0), 4) END,
      public.inventory_count_book_qty(v_product.id, v_doc.warehouse_id),
      NULL, NULL,
      public.inventory_count_unit_cost(v_product.id)
    )
    RETURNING * INTO v_line;
  END IF;

  IF v_piece.id IS NOT NULL THEN
    IF v_line.scanned_piece_ids ? v_piece.id::text THEN
      RAISE EXCEPTION '%', format('Bu hissə artıq sayılıb (%s m)', v_piece.length_m) USING ERRCODE = '22023';
    END IF;
    UPDATE public.inventory_count_items
    SET scanned_piece_ids = scanned_piece_ids || to_jsonb(v_piece.id::text),
        actual_full_sheets = COALESCE(actual_full_sheets, 0)
          + CASE WHEN v_piece.piece_type = 'full' THEN 1 ELSE 0 END,
        actual_cut_pieces = CASE WHEN v_piece.piece_type = 'cut'
          THEN COALESCE(actual_cut_pieces, '[]'::jsonb) || to_jsonb(v_piece.length_m)
          ELSE COALESCE(actual_cut_pieces, '[]'::jsonb) END,
        counted_at = NOW(), counted_by = v_actor
    WHERE id = v_line.id
    RETURNING * INTO v_line;
  ELSE
    UPDATE public.inventory_count_items
    SET actual_qty = COALESCE(actual_qty, 0) + 1,
        counted_at = NOW(), counted_by = v_actor
    WHERE id = v_line.id
    RETURNING * INTO v_line;
  END IF;

  PERFORM public.inventory_count_refresh_totals(v_doc.id);

  RETURN jsonb_build_object(
    'line_id', v_line.id,
    'product_name', v_line.product_name,
    'actual_qty', v_line.actual_qty,
    'unit', v_line.unit,
    'piece_length', v_piece.length_m
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_submit(p_count_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc     public.inventory_counts;
  v_counted INTEGER;
  v_drift   INTEGER;
BEGIN
  PERFORM public._inventory_count_authorize('can_writeoff_inventory');
  v_doc := public._inventory_count_lock(p_count_id, ARRAY['in_progress']);

  SELECT COUNT(*) INTO v_counted FROM public.inventory_count_items
  WHERE count_id = v_doc.id AND actual_qty IS NOT NULL;
  IF v_counted = 0 THEN
    RAISE EXCEPTION '%', 'Heç bir məhsul sayılmayıb' USING ERRCODE = '22023';
  END IF;

  UPDATE public.inventory_count_items i
  SET drift_qty = ROUND(public.inventory_count_book_qty(i.product_id, v_doc.warehouse_id) - i.expected_qty, 3)
  WHERE i.count_id = v_doc.id;

  SELECT COUNT(*) INTO v_drift FROM public.inventory_count_items
  WHERE count_id = v_doc.id AND actual_qty IS NOT NULL AND abs(drift_qty) > 0.0005;

  UPDATE public.inventory_counts
  SET status = 'review', submitted_at = NOW(), updated_at = NOW()
  WHERE id = v_doc.id;

  PERFORM public.inventory_count_refresh_totals(v_doc.id);
  RETURN jsonb_build_object('counted', v_counted, 'drift_lines', v_drift);
END;
$function$

CREATE OR REPLACE FUNCTION public.merge_partners(p_source_partner_id uuid, p_target_partner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source partners%ROWTYPE;
  v_target partners%ROWTYPE;
  v_sales_moved INT := 0;
  v_purchases_moved INT := 0;
BEGIN
  IF p_source_partner_id IS NULL OR p_target_partner_id IS NULL THEN
    RAISE EXCEPTION 'partner_ids_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Hər iki tərəfdaş seçilməlidir';
  END IF;

  IF p_source_partner_id = p_target_partner_id THEN
    RAISE EXCEPTION 'same_partner'
      USING ERRCODE = '22023',
            MESSAGE = 'Eyni tərəfdaş seçilə bilməz';
  END IF;

  SELECT * INTO v_source FROM partners WHERE id = p_source_partner_id AND is_deleted = FALSE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'source_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Mənbə tərəfdaş tapılmadı';
  END IF;

  SELECT * INTO v_target FROM partners WHERE id = p_target_partner_id AND is_deleted = FALSE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hədəf tərəfdaş tapılmadı';
  END IF;

  UPDATE sales
  SET partner_id = p_target_partner_id
  WHERE partner_id = p_source_partner_id;
  GET DIAGNOSTICS v_sales_moved = ROW_COUNT;

  IF v_source.customer_id IS NOT NULL THEN
    UPDATE sales
    SET partner_id = p_target_partner_id
    WHERE partner_id IS NULL
      AND customer_id = v_source.customer_id;
    v_sales_moved := v_sales_moved + ROW_COUNT;
  END IF;

  UPDATE purchases
  SET partner_id = p_target_partner_id
  WHERE partner_id = p_source_partner_id;
  GET DIAGNOSTICS v_purchases_moved = ROW_COUNT;

  IF v_source.supplier_id IS NOT NULL THEN
    UPDATE purchases
    SET partner_id = p_target_partner_id
    WHERE partner_id IS NULL
      AND supplier_id = v_source.supplier_id;
    v_purchases_moved := v_purchases_moved + ROW_COUNT;
  END IF;

  UPDATE partners
  SET
    is_customer = (v_target.is_customer OR v_source.is_customer),
    is_supplier = (v_target.is_supplier OR v_source.is_supplier),
    customer_id = COALESCE(v_target.customer_id, v_source.customer_id),
    supplier_id = COALESCE(v_target.supplier_id, v_source.supplier_id),
    email = COALESCE(NULLIF(trim(v_target.email), ''), NULLIF(trim(v_source.email), '')),
    bank_name = COALESCE(NULLIF(trim(v_target.bank_name), ''), NULLIF(trim(v_source.bank_name), '')),
    iban = COALESCE(NULLIF(trim(v_target.iban), ''), NULLIF(trim(v_source.iban), '')),
    credit_limit = GREATEST(COALESCE(v_target.credit_limit, 0), COALESCE(v_source.credit_limit, 0)),
    voen = COALESCE(NULLIF(trim(v_target.voen), ''), NULLIF(trim(v_source.voen), ''))
  WHERE id = p_target_partner_id;

  UPDATE partners
  SET
    is_deleted = TRUE,
    deleted_at = NOW()
  WHERE id = p_source_partner_id;

  RETURN jsonb_build_object(
    'target_partner_id', p_target_partner_id,
    'source_partner_id', p_source_partner_id,
    'sales_moved', v_sales_moved,
    'purchases_moved', v_purchases_moved
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.merge_stock_demand(p_demand jsonb, p_product_id uuid, p_quantity numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_composite BOOLEAN := false;
  v_bom RECORD;
  v_key TEXT;
  v_component_qty NUMERIC;
  v_result JSONB := COALESCE(p_demand, '{}'::jsonb);
BEGIN
  IF p_product_id IS NULL OR COALESCE(p_quantity, 0) <= 0 THEN
    RETURN v_result;
  END IF;

  SELECT COALESCE(is_composite, false)
  INTO v_is_composite
  FROM public.products
  WHERE id = p_product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'product_not_found'
      USING ERRCODE = 'P0002', MESSAGE = format('Məhsul tapılmadı: %s', p_product_id);
  END IF;

  IF v_is_composite THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.product_bom WHERE parent_product_id = p_product_id
    ) THEN
      RAISE EXCEPTION 'composite_bom_missing'
        USING ERRCODE = '22023',
              MESSAGE = format('Komplekt məhsul üçün BOM təyin edilməyib: %s', p_product_id);
    END IF;

    FOR v_bom IN
      SELECT component_product_id, quantity
      FROM public.product_bom
      WHERE parent_product_id = p_product_id
    LOOP
      v_key := v_bom.component_product_id::text;
      v_component_qty := COALESCE(p_quantity, 0) * COALESCE(v_bom.quantity, 1);
      v_result := jsonb_set(
        v_result,
        ARRAY[v_key],
        to_jsonb(COALESCE((v_result->>v_key)::numeric, 0) + v_component_qty),
        true
      );
    END LOOP;
  ELSE
    v_key := p_product_id::text;
    v_result := jsonb_set(
      v_result,
      ARRAY[v_key],
      to_jsonb(COALESCE((v_result->>v_key)::numeric, 0) + COALESCE(p_quantity, 0)),
      true
    );
  END IF;

  RETURN v_result;
END;
$function$

