CREATE OR REPLACE FUNCTION public.next_sales_doc_no(p_prefix text DEFAULT 'SS'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM CURRENT_DATE)::INT;
  v_no INT;
  v_prefix TEXT := COALESCE(NULLIF(trim(p_prefix), ''), 'SS');
  v_doc TEXT;
  v_attempts INT := 0;
BEGIN
  LOOP
    INSERT INTO public.document_number_counters (doc_type, year, last_no)
    VALUES ('sales_invoice', v_year, 1)
    ON CONFLICT (doc_type, year)
    DO UPDATE SET last_no = public.document_number_counters.last_no + 1
    RETURNING last_no INTO v_no;

    v_doc := v_prefix || '-' || v_year::TEXT || '-' || lpad(v_no::TEXT, 5, '0');

    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM public.sales s
      WHERE s.doc_no = v_doc
         OR s.invoice_number = v_doc
    );

    v_attempts := v_attempts + 1;
    IF v_attempts > 10000 THEN
      RAISE EXCEPTION 'doc_no_exhausted'
        USING ERRCODE = 'P0001',
              MESSAGE = 'Satış sənəd nömrəsi yaradıla bilmədi';
    END IF;
  END LOOP;

  RETURN v_doc;
END;
$function$

CREATE OR REPLACE FUNCTION public.pay_employee_advance_atomic(p_employee_id uuid, p_amount numeric, p_account_id uuid, p_description text DEFAULT NULL::text, p_request_date date DEFAULT CURRENT_DATE, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_balance NUMERIC;
  v_employee_name TEXT;
  v_advance_id UUID;
  v_tx_id UUID;
  v_category_id UUID;
  v_desc TEXT;
BEGIN
  IF NOT public.require_permission('can_manage_hr') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;

  SELECT full_name INTO v_employee_name
    FROM public.employees
   WHERE id = p_employee_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.reconcile_account_balance_atomic(p_account_id);

  SELECT balance INTO v_balance
    FROM public.accounts
   WHERE id = p_account_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_balance, 0) < p_amount THEN
    RAISE EXCEPTION 'insufficient_balance' USING ERRCODE = '22023';
  END IF;

  v_desc := COALESCE(
    NULLIF(trim(p_description), ''),
    format('Avans: %s', v_employee_name)
  );

  v_tx_id := public.post_cash_transaction(
    p_account_id,
    'Məxaric',
    p_amount,
    'Əmək Haqqı',
    v_desc,
    NULL,
    'employee_advance',
    NULL
  );

  v_category_id := public.resolve_financial_category_id('Maaş', 'EXPENSE');

  UPDATE public.transactions
     SET unified_type = 'EXPENSE',
         category_id = v_category_id,
         reference_type = 'employee_advance',
         description = v_desc,
         transaction_date = COALESCE(transaction_date, created_at, NOW()),
         created_by = p_created_by
   WHERE id = v_tx_id;

  INSERT INTO public.employee_advances (
    employee_id,
    amount,
    request_date,
    status,
    account_id,
    transaction_id,
    description
  )
  VALUES (
    p_employee_id,
    p_amount,
    COALESCE(p_request_date, CURRENT_DATE),
    'PAID',
    p_account_id,
    v_tx_id,
    NULLIF(trim(p_description), '')
  )
  RETURNING id INTO v_advance_id;

  UPDATE public.transactions
     SET reference_id = v_advance_id
   WHERE id = v_tx_id;

  RETURN v_advance_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.pay_payroll_run_atomic(p_payroll_id uuid, p_account_id uuid, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payroll RECORD;
  v_balance NUMERIC;
  v_employee_name TEXT;
  v_tx_id UUID;
  v_category_id UUID;
  v_desc TEXT;
  v_salary_payment_id UUID;
  v_month_label TEXT;
BEGIN
  IF NOT public.require_permission('can_manage_hr') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT *
    INTO v_payroll
    FROM public.payrolls
   WHERE id = p_payroll_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payroll_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_payroll.status = 'PAID' THEN
    RAISE EXCEPTION 'payroll_already_paid' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_payroll.net_salary, 0) <= 0 THEN
    RAISE EXCEPTION 'net_amount_zero' USING ERRCODE = '22023';
  END IF;

  SELECT full_name INTO v_employee_name
    FROM public.employees
   WHERE id = v_payroll.employee_id;

  PERFORM public.reconcile_account_balance_atomic(p_account_id);

  SELECT balance INTO v_balance
    FROM public.accounts
   WHERE id = p_account_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_balance, 0) < v_payroll.net_salary THEN
    RAISE EXCEPTION 'insufficient_balance' USING ERRCODE = '22023';
  END IF;

  v_month_label := to_char(make_date(v_payroll.period_year, v_payroll.period_month, 1), 'TMMonth YYYY');

  v_desc := format(
    'Maaş bordrosu: %s — %s (Əsas: %s, Bonus: %s, Avans: %s, Tutulma: %s)',
    v_employee_name,
    v_month_label,
    to_char(v_payroll.base_salary, 'FM999999990.00'),
    to_char(v_payroll.bonuses_commissions, 'FM999999990.00'),
    to_char(v_payroll.advances_deducted, 'FM999999990.00'),
    to_char(v_payroll.other_deductions, 'FM999999990.00')
  );

  v_tx_id := public.post_cash_transaction(
    p_account_id,
    'Məxaric',
    v_payroll.net_salary,
    'Əmək Haqqı',
    v_desc,
    NULL,
    'payroll',
    p_payroll_id
  );

  v_category_id := public.resolve_financial_category_id('Maaş', 'EXPENSE');

  UPDATE public.transactions
     SET unified_type = 'EXPENSE',
         category_id = v_category_id,
         reference_type = 'payroll',
         reference_id = p_payroll_id,
         description = v_desc,
         transaction_date = COALESCE(transaction_date, created_at, NOW()),
         created_by = p_created_by
   WHERE id = v_tx_id;

  INSERT INTO public.salary_payments (
    employee_id,
    account_id,
    amount,
    net_amount,
    base_salary,
    commission_total,
    deductions,
    month_year,
    notes,
    status
  )
  VALUES (
    v_payroll.employee_id,
    p_account_id,
    v_payroll.net_salary,
    v_payroll.net_salary,
    v_payroll.base_salary,
    v_payroll.bonuses_commissions,
    v_payroll.advances_deducted + v_payroll.other_deductions,
    v_month_label,
    v_desc,
    'paid'
  )
  RETURNING id INTO v_salary_payment_id;

  UPDATE public.sales_commissions
     SET status = 'paid',
         payroll_id = v_salary_payment_id
   WHERE employee_id = v_payroll.employee_id
     AND status = 'pending';

  UPDATE public.employee_advances
     SET status = 'DEDUCTED',
         updated_at = NOW()
   WHERE employee_id = v_payroll.employee_id
     AND status = 'PAID'
     AND EXTRACT(YEAR FROM COALESCE(request_date, created_at)::date) = v_payroll.period_year
     AND EXTRACT(MONTH FROM COALESCE(request_date, created_at)::date) = v_payroll.period_month;

  UPDATE public.payrolls
     SET status = 'PAID',
         paid_at = NOW(),
         account_id = p_account_id,
         transaction_id = v_tx_id,
         salary_payment_id = v_salary_payment_id,
         updated_at = NOW()
   WHERE id = p_payroll_id;

  RETURN v_tx_id;
END;
$function$

