CREATE OR REPLACE FUNCTION public.post_cash_transaction(p_account_id uuid, p_type text, p_amount numeric, p_category text, p_notes text DEFAULT NULL::text, p_production_order_id uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_balance NUMERIC;
  v_tx_id UUID;
  v_type TEXT;
  v_category TEXT;
  v_journal_id UUID;
  v_counter_coa TEXT;
  v_memo TEXT;
BEGIN
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı mütləqdir';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  v_type := trim(COALESCE(p_type, ''));
  -- Legacy migrations stored Azerbaijani labels with broken encoding (MÉ™daxil / MÉ™xaric).
  IF v_type LIKE 'M%daxil' THEN
    v_type := 'Mədaxil';
  ELSIF v_type LIKE 'M%xaric' THEN
    v_type := 'Məxaric';
  END IF;

  IF v_type IS DISTINCT FROM 'Mədaxil' AND v_type IS DISTINCT FROM 'Məxaric' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Əməliyyat növü Mədaxil və ya Məxaric olmalıdır';
  END IF;

  v_category := COALESCE(NULLIF(trim(p_category), ''), 'Digər');
  v_memo := COALESCE(NULLIF(trim(p_notes), ''), v_category);

  IF public.resolve_coa_id('1100') IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = 'Hesab planında 1100 (Kassa/Bank) tapılmadı — chart-of-accounts miqrasiyasını yoxlayın';
  END IF;

  SELECT balance INTO v_balance
  FROM public.accounts
  WHERE id = p_account_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;

  IF v_type = 'Məxaric' AND COALESCE(v_balance, 0) + 0.0001 < p_amount THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank balansı kifayət etmir';
  END IF;

  INSERT INTO public.transactions (
    account_id, type, amount, category, notes, production_order_id, source_type, source_id
  )
  VALUES (
    p_account_id,
    v_type,
    p_amount,
    v_category,
    NULLIF(trim(p_notes), ''),
    p_production_order_id,
    NULLIF(trim(p_source_type), ''),
    p_source_id
  )
  RETURNING id INTO v_tx_id;

  IF v_type = 'Mədaxil' THEN
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) + p_amount
    WHERE id = p_account_id;

    v_counter_coa := public.coa_credit_for_cash_in(v_category);
    v_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'cash_transaction',
        'source_id', v_tx_id,
        'idempotency_key', 'cash_tx:' || v_tx_id::text,
        'memo', v_memo,
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', '1100',
            'debit', p_amount,
            'credit', 0,
            'account_id', p_account_id,
            'line_memo', v_memo
          ),
          jsonb_build_object(
            'coa_code', v_counter_coa,
            'debit', 0,
            'credit', p_amount,
            'line_memo', v_category
          )
        )
      )
    );
  ELSE
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) - p_amount
    WHERE id = p_account_id;

    v_counter_coa := public.coa_debit_for_cash_out(v_category);
    v_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'cash_transaction',
        'source_id', v_tx_id,
        'idempotency_key', 'cash_tx:' || v_tx_id::text,
        'memo', v_memo,
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', v_counter_coa,
            'debit', p_amount,
            'credit', 0,
            'line_memo', v_category
          ),
          jsonb_build_object(
            'coa_code', '1100',
            'debit', 0,
            'credit', p_amount,
            'account_id', p_account_id,
            'line_memo', v_memo
          )
        )
      )
    );
  END IF;

  UPDATE public.transactions
  SET journal_entry_id = v_journal_id
  WHERE id = v_tx_id;

  RETURN v_tx_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_cash_transaction(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_tx_id UUID;
    v_account_id UUID;
    v_amount NUMERIC(14,2);
    v_type TEXT;
    v_journal_id UUID;
    v_coa_cash_id UUID;
    v_coa_counter_id UUID;
    v_category TEXT;
BEGIN
    v_account_id := (p_payload->>'account_id')::UUID;
    v_amount := (p_payload->>'amount')::NUMERIC;
    v_type := COALESCE(p_payload->>'type', 'Mədaxil');
    v_category := COALESCE(p_payload->>'category', 'Satış Ödənişi');

    IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'Kassa və ya bank hesabı (account_id) seçilməlidir';
    END IF;

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RAISE EXCEPTION 'Məbləğ düzgün daxil edilməyib';
    END IF;

    -- Insert into transactions table
    INSERT INTO public.transactions (
        type, category, amount, account_id, description, created_at
    ) VALUES (
        v_type,
        v_category,
        v_amount,
        v_account_id,
        COALESCE(p_payload->>'description', 'Ödəniş'),
        NOW()
    ) RETURNING id INTO v_tx_id;

    -- DIRECT UPDATE to Accounts Balance
    IF v_type = 'Mədaxil' THEN
        UPDATE public.accounts 
        SET balance = COALESCE(balance, 0) + v_amount 
        WHERE id = v_account_id;
    ELSIF v_type = 'Məxaric' THEN
        UPDATE public.accounts 
        SET balance = COALESCE(balance, 0) - v_amount 
        WHERE id = v_account_id;
    END IF;

    -- Get COA Accounts for Journal
    SELECT id INTO v_coa_cash_id FROM public.chart_of_accounts WHERE code = '1100' LIMIT 1;
    SELECT id INTO v_coa_counter_id FROM public.chart_of_accounts WHERE code = (CASE WHEN v_type = 'Mədaxil' THEN '1200' ELSE '2100' END) LIMIT 1;

    -- Post Journal Entry if COA exists
    IF v_coa_cash_id IS NOT NULL AND v_coa_counter_id IS NOT NULL THEN
        v_journal_id := public.post_journal_entry(jsonb_build_object(
            'source_type', 'cash_transaction',
            'source_id', v_tx_id,
            'memo', COALESCE(p_payload->>'description', 'Maliyyə əməliyyatı'),
            'lines', jsonb_build_array(
                jsonb_build_object('coa_id', CASE WHEN v_type = 'Mədaxil' THEN v_coa_cash_id ELSE v_coa_counter_id END, 'debit', v_amount, 'credit', 0, 'account_id', v_account_id),
                jsonb_build_object('coa_id', CASE WHEN v_type = 'Mədaxil' THEN v_coa_counter_id ELSE v_coa_cash_id END, 'debit', 0, 'credit', v_amount, 'account_id', v_account_id)
            )
        ));

        UPDATE public.transactions SET journal_entry_id = v_journal_id WHERE id = v_tx_id;
    END IF;

    RETURN v_tx_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_expense_atomic(p_expense_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.require_permission('can_manage_expenses') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Xərc təsdiqləmək üçün icazəniz yoxdur';
  END IF;
  RETURN public.post_expense_internal(p_expense_id);
