CREATE OR REPLACE FUNCTION public.post_expense_internal(p_expense_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp      public.expenses%ROWTYPE;
  v_tx_id    UUID;
  v_vat_tx   UUID;
  v_journal  UUID;
  v_memo     TEXT;
  v_split    BOOLEAN;
  v_main     NUMERIC(14,2);
  v_vat      NUMERIC(14,2);
  v_lines    JSONB;
BEGIN
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
  END IF;
  IF v_exp.payment_mode = 'employee' THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'İşçinin ödədiyi xərc təsdiqlənir, sonra işçiyə kompensasiya ödənilir';
  END IF;
  IF v_exp.status NOT IN ('draft', 'submitted') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Yalnız qaralama və ya təsdiq gözləyən xərc ödənilə bilər';
  END IF;
  IF v_exp.account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;
  IF COALESCE(v_exp.amount, 0) <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;
  PERFORM public.assert_expense_date_postable(v_exp.expense_date);
  IF public.resolve_coa_id('1100') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002',
      MESSAGE = 'Hesab planında 1100 (Kassa/Bank) tapılmadı — chart-of-accounts miqrasiyasını yoxlayın';
  END IF;

  v_vat   := COALESCE(v_exp.vat_amount, 0);
  v_split := v_exp.vat_account_id IS NOT NULL AND v_vat > 0;
  IF v_split AND v_exp.vat_account_id = v_exp.account_id THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ƏDV hesabı əsas hesabdan fərqli olmalıdır';
  END IF;
  IF v_split AND public.resolve_coa_id('1410') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002',
      MESSAGE = 'Hesab planında 1410 (Əvəzləşdirilən ƏDV) tapılmadı';
  END IF;
  v_main := CASE WHEN v_split THEN v_exp.amount - v_vat ELSE v_exp.amount END;

  v_memo := public.expense_memo(v_exp.id);
  -- Lock both accounts in a fixed order so two payments never deadlock.
  IF v_split AND v_exp.vat_account_id < v_exp.account_id THEN
    v_vat_tx := public.expense_cash_out(v_exp.id, v_exp.vat_account_id, v_vat, v_exp.expense_date, v_memo || ' (ƏDV)');
    v_tx_id  := public.expense_cash_out(v_exp.id, v_exp.account_id, v_main, v_exp.expense_date, v_memo);
  ELSE
    v_tx_id := public.expense_cash_out(v_exp.id, v_exp.account_id, v_main, v_exp.expense_date, v_memo);
    IF v_split THEN
      v_vat_tx := public.expense_cash_out(v_exp.id, v_exp.vat_account_id, v_vat, v_exp.expense_date, v_memo || ' (ƏDV)');
    END IF;
  END IF;

  IF v_split THEN
    v_lines := jsonb_build_array(
      jsonb_build_object('coa_id', public.expense_coa_id(v_exp.id), 'debit', v_main, 'credit', 0,
                         'line_memo', v_exp.category),
      jsonb_build_object('coa_code', '1410', 'debit', v_vat, 'credit', 0,
                         'line_memo', 'ƏDV — ' || v_exp.code),
      jsonb_build_object('coa_code', '1100', 'debit', 0, 'credit', v_main,
                         'account_id', v_exp.account_id, 'line_memo', v_memo),
      jsonb_build_object('coa_code', '1100', 'debit', 0, 'credit', v_vat,
                         'account_id', v_exp.vat_account_id, 'line_memo', v_memo || ' (ƏDV)')
    );
  ELSE
    v_lines := jsonb_build_array(
      jsonb_build_object('coa_id', public.expense_coa_id(v_exp.id), 'debit', v_exp.amount, 'credit', 0,
                         'line_memo', v_exp.category),
      jsonb_build_object('coa_code', '1100', 'debit', 0, 'credit', v_exp.amount,
                         'account_id', v_exp.account_id, 'line_memo', v_memo)
    );
  END IF;

  v_journal := public.post_journal_entry(jsonb_build_object(
    'source_type', 'expense',
    'source_id', v_exp.id,
    'document_type', 'expense',
    'document_id', v_exp.id,
    'idempotency_key', 'expense:' || v_exp.id::text,
    'entry_date', v_exp.expense_date,
    'memo', v_memo,
    'lines', v_lines
  ));

  UPDATE public.transactions SET journal_entry_id = v_journal WHERE id IN (v_tx_id, v_vat_tx);

  UPDATE public.expenses
  SET status = 'posted',
      transaction_id = v_tx_id,
      vat_transaction_id = v_vat_tx,
      journal_entry_id = v_journal,
      posted_at = NOW(),
      posted_by = auth.uid(),
      updated_at = NOW()
  WHERE id = v_exp.id;

  RETURN v_tx_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_initial_balance_journal(p_document_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc       public.inventory_initial_balances%ROWTYPE;
  v_existing  UUID;
  v_amount    NUMERIC;
  v_counter   TEXT;
  v_label     TEXT;
  v_cycle     INTEGER;
BEGIN
  SELECT * INTO v_doc
  FROM public.inventory_initial_balances
  WHERE id = p_document_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'İlkin qalıq sənədi tapılmadı';
  END IF;

  IF v_doc.status NOT IN ('draft', 'posted') THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = format('%s: ləğv edilmiş sənəd üçün mühasibat yazılışı edilmir', v_doc.document_number);
  END IF;

  SELECT id INTO v_existing
  FROM public.journal_entries
  WHERE COALESCE(document_id, source_id) = p_document_id
    AND reversal_of IS NULL
    AND reversed_by IS NULL
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  SELECT round(SUM(initial_qty * unit_cost), 2) INTO v_amount
  FROM public.inventory_batches
  WHERE document_id = p_document_id;

  IF v_amount IS NULL OR v_amount <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = format('%s: FIFO partiyası tapılmadı — mühasibat yazılışı edilmədi', v_doc.document_number);
  END IF;

  IF v_doc.entry_type = 'receipt' THEN
    v_counter := '2150';
    v_label := 'Stok qəbulu';
  ELSE
    v_counter := '3900';
    v_label := 'İlkin qalıq';
  END IF;

  SELECT COUNT(*) + 1 INTO v_cycle
  FROM public.journal_entries
  WHERE COALESCE(document_id, source_id) = p_document_id
    AND reversal_of IS NULL;

  RETURN public.create_journal_entry(
    jsonb_build_object(
      'entry_date', v_doc.doc_date,
      'source_type', 'inventory_initial_balance',
      'source_id', p_document_id,
      'document_type', 'inventory_initial_balance',
      'document_id', p_document_id,
      'idempotency_key', format('inventory_initial_balance:%s:%s', p_document_id, v_cycle),
      'memo', format('%s — %s', v_label, v_doc.document_number),
      'lines', jsonb_build_array(
        jsonb_build_object('coa_code', '1300', 'debit', v_amount, 'credit', 0,
                           'line_memo', v_doc.document_number),
        jsonb_build_object('coa_code', v_counter, 'debit', 0, 'credit', v_amount,
                           'line_memo', v_doc.document_number)
      )
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.post_purchase_invoice_draft(p_purchase_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_purchase RECORD;
  v_item RECORD;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_unit_price NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_account_name TEXT;
  v_pay_note TEXT;
  v_stock_demand JSONB := '{}'::jsonb;
  v_price_map JSONB := '{}'::jsonb;
  v_key TEXT;
  v_journal_id UUID;
  v_add_exp_total NUMERIC;
  v_idempotency TEXT;
  v_result JSONB;
  v_event_id UUID;
BEGIN
  IF p_purchase_id IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Alış ID göndərilməyib';
  END IF;

  IF NOT (
    public.require_permission('can_edit_purchases')
    OR public.require_permission('can_create_purchase')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Alış təsdiqləmək üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_purchase FROM purchases WHERE id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Alış sənədi tapılmadı';
  END IF;

  IF v_purchase.status = 'posted' THEN
    RAISE EXCEPTION 'already_posted'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd artıq təsdiqlənib';
  END IF;

  IF v_purchase.status IN ('cancelled', 'void', 'voided') THEN
    RAISE EXCEPTION 'cancelled_document'
      USING ERRCODE = '22023',
            MESSAGE = 'Ləğv edilmiş sənəd təsdiqlənə bilməz';
  END IF;

  IF COALESCE(v_purchase.total_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'invalid_total_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Alış məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF COALESCE(v_purchase.paid_amount, 0) > COALESCE(v_purchase.total_amount, 0) + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  FOR v_item IN
    SELECT product_id, quantity, unit_price
    FROM purchase_items
    WHERE purchase_id = p_purchase_id
  LOOP
    v_product_id := v_item.product_id;
    v_qty := COALESCE(v_item.quantity, 0);
    v_unit_price := COALESCE(v_item.unit_price, 0);

    IF v_product_id IS NULL OR v_qty <= 0 OR v_unit_price <= 0 THEN
      RAISE EXCEPTION 'invalid_item'
        USING ERRCODE = '22023',
              MESSAGE = 'Hər sətirdə məhsul, miqdar və qiymət tələb olunur';
    END IF;

    v_key := v_product_id::text;
    v_stock_demand := jsonb_set(
      v_stock_demand,
      ARRAY[v_key],
      to_jsonb(COALESCE((v_stock_demand->>v_key)::numeric, 0) + v_qty),
      true
    );
    v_price_map := jsonb_set(v_price_map, ARRAY[v_key], to_jsonb(v_unit_price), true);
  END LOOP;

  IF jsonb_object_length(v_stock_demand) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir məhsul tələb olunur';
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    PERFORM id FROM products WHERE id = v_key::uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Məhsul tapılmadı: ' || v_key;
    END IF;
  END LOOP;

  IF jsonb_typeof(v_purchase.payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_purchase.payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);
    v_unit_price := COALESCE((v_price_map->>v_key)::numeric, 0);

    SELECT stock INTO v_stock
    FROM products
    WHERE id = v_product_id
    FOR UPDATE;

    UPDATE products
    SET stock = COALESCE(v_stock, 0) + v_qty,
        buy_price = v_unit_price
    WHERE id = v_product_id;

    PERFORM public.create_inventory_batch(
      v_product_id,
      p_purchase_id,
      'purchase',
      v_unit_price,
      v_qty
    );
  END LOOP;

  IF jsonb_typeof(v_purchase.payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_purchase.payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;

      SELECT name INTO v_account_name
      FROM accounts
      WHERE id = v_account_id;

      v_pay_note := COALESCE(
        NULLIF(trim(v_pay->>'note'), ''),
        format('Alış fakturası %s', v_purchase.invoice_number)
      );
      IF NULLIF(trim(v_pay->>'payment_date'), '') IS NOT NULL THEN
        v_pay_note := trim(v_pay->>'payment_date') || ' — ' || v_pay_note;
      END IF;
      IF v_account_name IS NOT NULL THEN
        v_pay_note := v_pay_note || ' — ' || v_account_name;
      END IF;

      PERFORM public.post_cash_transaction(
        v_account_id,
        'Məxaric',
        v_pay_amount,
        'Alış Ödənişi',
        v_pay_note,
        NULL,
        'purchase',
        p_purchase_id
      );
    END LOOP;
  END IF;

  v_add_exp_total := public.apply_document_additional_expenses(
    COALESCE(v_purchase.additional_expenses, '[]'::jsonb),
    'purchase',
    p_purchase_id,
    v_purchase.invoice_number
  );

  v_idempotency := 'purchase_receipt:' || p_purchase_id::text;

  v_journal_id := public.post_purchase_bill_gl_journal(
    p_purchase_id,
    v_purchase.invoice_number,
    v_purchase.total_amount,
    v_purchase.supplier_id,
    v_idempotency
  );

  PERFORM public.refresh_supplier_ap_balance(v_purchase.supplier_id);

  UPDATE purchases
  SET status = 'posted',
      posted_at = NOW(),
      additional_expenses_total = v_add_exp_total
  WHERE id = p_purchase_id;

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'purchase_invoice_post',
    'purchase_id', p_purchase_id,
    'invoice_number', v_purchase.invoice_number,
    'status', 'posted',
    'journal_entry_id', v_journal_id,
    'total_amount', v_purchase.total_amount,
    'paid_amount', v_purchase.paid_amount,
    'debt_amount', v_purchase.debt_amount
  );

  v_event_id := public.log_erp_event(
    'purchase_receipt',
    'purchases',
    p_purchase_id,
    jsonb_build_object('purchase_id', p_purchase_id, 'posted_from', 'draft'),
    v_journal_id,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.post_sale(p_customer_id uuid, p_warehouse_id uuid, p_seller_id uuid, p_account_id uuid, p_items jsonb, p_paid_amount numeric, p_notes text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_sale_id UUID;
    v_doc_no TEXT;
    v_subtotal NUMERIC := 0;
    v_total_vat NUMERIC := 0;
    v_grand_total NUMERIC := 0;
    v_item JSONB;
    v_product_id UUID;
    v_qty NUMERIC;
    v_unit_price NUMERIC;
    v_category_id UUID;
    v_current_stock NUMERIC;
    v_line_total NUMERIC;
    v_remaining_balance NUMERIC;
BEGIN
    -- ۱. تولید شماره سند ترتیبی و یکتا (مثال: INV-1001)
    SELECT 'INV-' || LPAD((COALESCE(MAX(CAST(SUBSTRING(doc_no FROM 5) AS INTEGER)), 1000) + 1)::TEXT, 6, '0')
    INTO v_doc_no
    FROM sales
    WHERE doc_no LIKE 'INV-%';

    -- ۲. محاسبه مبالغ کل بر اساس اقلام
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_qty := (v_item->>'qty')::NUMERIC;
        v_unit_price := (v_item->>'unit_price')::NUMERIC;
        v_subtotal := v_subtotal + (v_qty * v_unit_price);
    END LOOP;

    v_grand_total := v_subtotal; -- در صورت داشتن ارزش افزوده سیستمیک قابل اضافه شدن است
    v_remaining_balance := v_grand_total - p_paid_amount;

    -- ۳. ایجاد هدر فاکتور فروش
    INSERT INTO sales (
        doc_no, customer_id, warehouse_id, seller_id, 
        subtotal, grand_total, paid_amount, remaining_balance, 
        notes, status, created_at
    ) VALUES (
        v_doc_no, p_customer_id, p_warehouse_id, p_seller_id,
        v_subtotal, v_grand_total, p_paid_amount, v_remaining_balance,
        p_notes, 'completed', NOW()
    )
    RETURNING id INTO v_sale_id;

    -- ۴. پردازش تک‌تک اقلام، بررسی سقف موجودی و کسر از انبار
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_qty := (v_item->>'qty')::NUMERIC;
        v_unit_price := (v_item->>'unit_price')::NUMERIC;
        v_category_id := (v_item->>'category_id')::UUID;
        v_line_total := v_qty * v_unit_price;

        -- قفل کردن ردیف موجودی انبار جهت جلوگیری از همزمانی (Race Condition)
        SELECT stock INTO v_current_stock
        FROM warehouse_stock
        WHERE warehouse_id = p_warehouse_id AND product_id = v_product_id
        FOR UPDATE;

        IF v_current_stock IS NULL OR v_current_stock < v_qty THEN
            RAISE EXCEPTION 'موجودی کالا (ID: %) در انبار کافی نیست. موجودی فعلی: %', v_product_id, COALESCE(v_current_stock, 0);
        END IF;

        -- ثبت ردیف فاکتور
        INSERT INTO sales_items (
            sale_id, product_id, category_id, qty, unit_price, total_price
        ) VALUES (
            v_sale_id, v_product_id, v_category_id, v_qty, v_unit_price, v_line_total
        );

        -- کسر از جدول موجودی انبار
        UPDATE warehouse_stock
        SET stock = stock - v_qty, updated_at = NOW()
        WHERE warehouse_id = p_warehouse_id AND product_id = v_product_id;

        -- ثبت گردش انبار (Stock Movement Log)
        INSERT INTO stock_movements (
            warehouse_id, product_id, reference_type, reference_id, qty_change
        ) VALUES (
            p_warehouse_id, v_product_id, 'sale', v_sale_id, -v_qty
        );
    END LOOP;

    -- ۵. به‌روزرسانی مانده بدهی مشتری (AR)
    UPDATE customers
    SET balance = balance + v_remaining_balance,
        updated_at = NOW()
    WHERE id = p_customer_id;

    -- ۶. ثبت دریافتی در صندوق/بانک (در صورت پرداخت نقدی)
    IF p_paid_amount > 0 THEN
        IF p_account_id IS NULL THEN
            RAISE EXCEPTION 'حساب دریافتی (صندوق/بانک) مشخص نشده است.';
        END IF;

        INSERT INTO transactions (
            account_id, reference_type, reference_id, 
            type, amount, party_id, notes
        ) VALUES (
            p_account_id, 'sale_payment', v_sale_id, 
            'inflow', p_paid_amount, p_customer_id, 'دریافتی بابت فاکتور ' || v_doc_no
        );

        UPDATE accounts
        SET balance = balance + p_paid_amount,
            updated_at = NOW()
        WHERE id = p_account_id;
    END IF;

    RETURN v_sale_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.post_sales_invoice_draft(p_sale_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale RECORD;
  v_items JSONB := '[]'::jsonb;
  v_payments JSONB;
  v_stock_demand JSONB := '{}'::jsonb;
  v_pay JSONB;
  v_pay_amount NUMERIC;
  v_account_id UUID;
  v_pay_method TEXT;
  v_journal_id UUID;
  v_cogs_result JSONB;
  v_total_cogs NUMERIC := 0;
  v_cogs_journal_id UUID;
  v_add_exp_total NUMERIC;
  v_idempotency TEXT;
  v_result JSONB;
  v_event_id UUID;
BEGIN
  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış ID göndərilməyib';
  END IF;

  IF NOT (
    public.require_permission('can_edit_sales')
    OR public.require_permission('can_create_invoice')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış təsdiqləmək üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_sale FROM sales WHERE id = p_sale_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Satış sənədi tapılmadı';
  END IF;

  IF v_sale.status = 'posted' THEN
    RAISE EXCEPTION 'already_posted'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd artıq təsdiqlənib';
  END IF;

  IF v_sale.status IN ('cancelled', 'void', 'voided') THEN
    RAISE EXCEPTION 'cancelled_document'
      USING ERRCODE = '22023',
            MESSAGE = 'Ləğv edilmiş sənəd təsdiqlənə bilməz';
  END IF;

  IF COALESCE(v_sale.total_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'invalid_total_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF COALESCE(v_sale.paid_amount, 0) > COALESCE(v_sale.total_amount, 0) + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  SELECT COALESCE(jsonb_agg(item_json ORDER BY ord), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT
      row_number() OVER (ORDER BY id) AS ord,
      jsonb_build_object(
        'product_id', product_id,
        'quantity', quantity,
        'warehouse_id', warehouse_id,
        'polywood_sale_mode', polywood_sale_mode,
        'polywood_length_m', polywood_length_m,
        'skip_stock', (polywood_sale_mode IS NOT NULL AND btrim(polywood_sale_mode) <> '')
      ) AS item_json
    FROM sale_items
    WHERE sale_id = p_sale_id
  ) lined;

  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir satış sətri tələb olunur';
  END IF;

  -- Stock deduction is handled by trg_sales_posted_inventory when status becomes posted.
  -- Pre-validate demand so posting fails before side effects if stock is insufficient.
  PERFORM public.build_and_validate_sale_stock_demand(v_items);

  v_idempotency := 'sale_invoice:' || p_sale_id::text;
  v_cogs_result := public.process_sale_fifo_cogs(
    p_sale_id,
    v_sale.doc_no,
    v_idempotency || ':cogs'
  );
  v_total_cogs := COALESCE((v_cogs_result->>'total_cogs')::numeric, 0);
  v_cogs_journal_id := NULLIF(v_cogs_result->>'cogs_journal_entry_id', '')::uuid;

  v_payments := COALESCE(v_sale.payments, '[]'::jsonb);
  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;

      v_pay_method := COALESCE(NULLIF(trim(v_pay->>'method'), ''), 'Ödəniş');
      PERFORM public.post_cash_transaction(
        v_account_id,
        'Mədaxil',
        v_pay_amount,
        'Satış Ödənişi',
        format('Satış fakturası %s — %s', v_sale.doc_no, v_pay_method),
        NULL,
        'sale',
        p_sale_id
      );
    END LOOP;
  END IF;

  v_add_exp_total := public.apply_document_additional_expenses(
    COALESCE(v_sale.additional_expenses, '[]'::jsonb),
    'sale',
    p_sale_id,
    v_sale.doc_no
  );

  v_journal_id := public.post_sale_invoice_gl_journal(
    p_sale_id,
    v_sale.doc_no,
    v_sale.total_amount,
    v_sale.customer_id,
    v_idempotency
  );

  UPDATE sales
  SET status = 'posted',
      posted_at = NOW(),
      additional_expenses_total = v_add_exp_total
  WHERE id = p_sale_id;

  PERFORM public.refresh_customer_ar_balance(v_sale.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'sales_invoice_post',
    'sale_id', p_sale_id,
    'doc_no', v_sale.doc_no,
    'status', 'posted',
    'journal_entry_id', v_journal_id,
    'cogs_journal_entry_id', v_cogs_journal_id,
    'total_cogs', v_total_cogs,
    'total_amount', v_sale.total_amount,
    'paid_amount', v_sale.paid_amount,
    'remaining_balance', v_sale.remaining_balance
  );

  -- log_erp_event takes seven arguments:
  --   (p_event_type TEXT, p_source_table TEXT, p_source_id UUID, p_payload JSONB,
  --    p_journal_entry_id UUID, p_idempotency_key TEXT, p_result JSONB)
  -- The phase-4 rewrite passed six in the wrong order, so every attempt to post a
  -- sales invoice failed with:
  --   function public.log_erp_event(unknown, unknown, uuid, unknown, jsonb, uuid) does not exist
  -- PL/pgSQL resolves the call only when it runs, which is why this shipped.
  v_event_id := public.log_erp_event(
    'sales_invoice',
    'sales',
    p_sale_id,
    jsonb_build_object('sale_id', p_sale_id, 'posted_from', 'draft', 'posted_by', auth.uid()),
    COALESCE(v_cogs_journal_id, v_journal_id),
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_invoice_payment_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_document_type TEXT;
  v_document_id UUID;
  v_amount NUMERIC;
  v_account_id UUID;
  v_method TEXT;
  v_notes TEXT;
  v_payment_id TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_debt_amount NUMERIC;
  v_new_paid NUMERIC;
  v_new_remaining NUMERIC;
  v_new_debt NUMERIC;
  v_customer_id UUID;
  v_supplier_id UUID;
  v_doc_label TEXT;
  v_payments JSONB;
  v_new_payment JSONB;
  v_status TEXT;
  v_tx_id UUID;
  v_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_event_type TEXT;
  v_source_table TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödəniş event payload göndərilməyib';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    v_cached := public.find_erp_event_by_idempotency(v_idempotency);
    IF v_cached IS NOT NULL THEN
      RETURN v_cached->'result';
    END IF;
  END IF;

  v_document_type := lower(trim(COALESCE(p_payload->>'document_type', '')));
  v_document_id := NULLIF(p_payload->>'document_id', '')::uuid;
  v_amount := COALESCE(NULLIF(p_payload->>'amount', '')::numeric, 0);
  v_account_id := NULLIF(p_payload->>'account_id', '')::uuid;
  v_method := COALESCE(NULLIF(trim(p_payload->>'method'), ''), 'Ödəniş');
  v_notes := NULLIF(trim(p_payload->>'notes'), '');
  v_payment_id := COALESCE(NULLIF(trim(p_payload->>'payment_id'), ''), gen_random_uuid()::text);

  IF v_document_id IS NULL THEN
    RAISE EXCEPTION 'document_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd identifikatoru tələb olunur';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;

  PERFORM id FROM accounts WHERE id = v_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
  END IF;

  IF v_document_type = 'sale' THEN
    IF NOT (
      public.require_permission('can_edit_sales')
      OR public.require_permission('can_create_invoice')
      OR public.require_permission('can_manage_finance')
    ) THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Satış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT total_amount, paid_amount, remaining_balance, customer_id, doc_no, payments
    INTO v_total_amount, v_paid_amount, v_remaining, v_customer_id, v_doc_label, v_payments
    FROM sales
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'sale_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Satış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_remaining := GREATEST(COALESCE(v_remaining, v_total_amount - v_paid_amount), 0);

    IF v_amount > v_remaining + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_remaining, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_remaining := GREATEST(v_total_amount - v_new_paid, 0);

    v_new_payment := jsonb_build_object(
      'id', v_payment_id,
      'account_id', v_account_id::text,
      'method', v_method,
      'amount', v_amount
    );
    v_payments := COALESCE(v_payments, '[]'::jsonb) || jsonb_build_array(v_new_payment);

    UPDATE sales
    SET paid_amount = v_new_paid,
        remaining_balance = v_new_remaining,
        payments = v_payments
    WHERE id = v_document_id;

    v_tx_id := public.post_cash_transaction(
      v_account_id,
      'Mədaxil',
      v_amount,
      'Satış Ödənişi',
      COALESCE(v_notes, format('Satış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)),
      NULL,
      'sale',
      v_document_id
    );

    SELECT journal_entry_id INTO v_journal_id
    FROM transactions
    WHERE id = v_tx_id;

    IF v_customer_id IS NOT NULL THEN
      PERFORM public.refresh_customer_ar_balance(v_customer_id);
    END IF;

    v_event_type := 'invoice_payment_sale';
    v_source_table := 'sales';

    v_result := jsonb_build_object(
      'success', true,
      'event_type', v_event_type,
      'document_type', 'sale',
      'document_id', v_document_id,
      'transaction_id', v_tx_id,
      'journal_entry_id', v_journal_id,
      'paid_amount', v_new_paid,
      'remaining_balance', v_new_remaining
    );
  ELSIF v_document_type = 'purchase' THEN
    IF NOT (
      public.require_permission('can_edit_purchases')
      OR public.require_permission('can_create_purchase')
      OR public.require_permission('can_manage_finance')
    ) THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Alış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT total_amount, paid_amount, debt_amount, supplier_id, invoice_number
    INTO v_total_amount, v_paid_amount, v_debt_amount, v_supplier_id, v_doc_label
    FROM purchases
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Alış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_debt_amount := GREATEST(COALESCE(v_debt_amount, v_total_amount - v_paid_amount), 0);

    IF v_amount > v_debt_amount + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_debt_amount, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_debt := GREATEST(v_total_amount - v_new_paid, 0);
    v_status := CASE WHEN v_new_debt > 0.0001 THEN 'Borclu' ELSE 'Ödənilib' END;

    UPDATE purchases
    SET paid_amount = v_new_paid,
        debt_amount = v_new_debt,
        status = v_status
    WHERE id = v_document_id;

    v_tx_id := public.post_cash_transaction(
      v_account_id,
      'Məxaric',
      v_amount,
      'Alış Ödənişi',
      COALESCE(v_notes, format('Alış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)),
      NULL,
      'purchase',
      v_document_id
    );

    SELECT journal_entry_id INTO v_journal_id
    FROM transactions
    WHERE id = v_tx_id;

    IF v_supplier_id IS NOT NULL THEN
      PERFORM public.refresh_supplier_ap_balance(v_supplier_id);
    END IF;

    v_event_type := 'invoice_payment_purchase';
    v_source_table := 'purchases';

    v_result := jsonb_build_object(
      'success', true,
      'event_type', v_event_type,
      'document_type', 'purchase',
      'document_id', v_document_id,
      'transaction_id', v_tx_id,
      'journal_entry_id', v_journal_id,
      'paid_amount', v_new_paid,
      'debt_amount', v_new_debt,
      'status', v_status
    );
  ELSE
    RAISE EXCEPTION 'invalid_document_type'
      USING ERRCODE = '22023',
            MESSAGE = 'document_type «sale» və ya «purchase» olmalıdır';
  END IF;

  v_event_id := public.log_erp_event(
    v_event_type,
    v_source_table,
    v_document_id,
    p_payload,
    v_journal_id,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_mixed_dimensional_sale(p_product_id uuid, p_warehouse_id uuid, p_item_type text, p_sale_mode text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_piece_count integer DEFAULT 1, p_sale_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product RECORD;
  v_base_length NUMERIC;
  v_remaining NUMERIC;
  v_target INTEGER;
  v_piece RECORD;
  v_new_piece_id UUID;
  v_leftover NUMERIC;
  v_steps JSONB := '[]'::jsonb;
  v_scrap JSONB := '[]'::jsonb;
  v_i INTEGER;
BEGIN
  IF p_item_type IS NULL THEN
    RAISE EXCEPTION 'item_type is required';
  END IF;

  IF p_item_type = 'service' THEN
    RETURN jsonb_build_object('ok', true, 'item_type', 'service', 'steps', v_steps);
  END IF;

  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'product_id is required';
  END IF;

  SELECT * INTO v_product FROM products WHERE id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Product % not found', p_product_id;
  END IF;

  IF p_item_type = 'accessory' THEN
    IF p_amount IS NULL OR p_amount <= 0 THEN
      RAISE EXCEPTION 'Accessory quantity must be positive';
    END IF;
    IF COALESCE(v_product.stock, 0) < p_amount THEN
      RAISE EXCEPTION 'Insufficient stock for "%": have %, need %', v_product.name, v_product.stock, p_amount;
    END IF;
    UPDATE products SET stock = stock - p_amount WHERE id = p_product_id;
    RETURN jsonb_build_object('ok', true, 'item_type', 'accessory', 'deducted', p_amount);
  END IF;

  IF p_item_type <> 'dimensional' THEN
    RAISE EXCEPTION 'Unknown item_type %', p_item_type;
  END IF;

  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id is required for dimensional items';
  END IF;

  v_base_length := COALESCE(v_product.base_length, v_product.full_sheet_length_m, 4);

  IF p_sale_mode = 'full_sheet' THEN
    v_target := ROUND(COALESCE(p_amount, 0))::INTEGER;
    IF v_target <= 0 THEN
      RAISE EXCEPTION 'Full sheet quantity must be positive';
    END IF;

    FOR v_piece IN
      SELECT * FROM polywood_pieces
      WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
        AND status = 'available' AND piece_type = 'full'
        AND ABS(length_m - v_base_length) < 0.001
      ORDER BY created_at ASC
      LIMIT v_target
      FOR UPDATE
    LOOP
      UPDATE polywood_pieces
      SET status = 'sold', sale_item_id = p_sale_item_id, updated_at = NOW()
      WHERE id = v_piece.id;
      v_steps := v_steps || jsonb_build_object(
        'piece_id', v_piece.id, 'action', 'consume', 'used_length', v_base_length
      );
      v_target := v_target - 1;
    END LOOP;

    IF v_target > 0 THEN
      RAISE EXCEPTION 'Insufficient full sheets for "%": missing % sheet(s)', v_product.name, v_target;
    END IF;

  ELSIF p_sale_mode IN ('meter', 'linear_m') THEN
    IF p_amount IS NULL OR p_amount <= 0 THEN
      RAISE EXCEPTION 'Length must be positive';
    END IF;

    FOR v_i IN 1..GREATEST(COALESCE(p_piece_count, 1), 1) LOOP
      v_remaining := ROUND(p_amount, 3);

      -- 1) Exact-length piece first (prefer an off-cut over a full sheet).
      SELECT * INTO v_piece FROM polywood_pieces
      WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
        AND status = 'available' AND ABS(length_m - v_remaining) < 0.001
      ORDER BY (piece_type = 'cut') DESC, created_at ASC
      LIMIT 1
      FOR UPDATE;

      IF FOUND THEN
        UPDATE polywood_pieces
        SET status = 'sold', sale_item_id = p_sale_item_id, updated_at = NOW()
        WHERE id = v_piece.id;
        v_steps := v_steps || jsonb_build_object(
          'piece_id', v_piece.id, 'action', 'consume', 'used_length', v_remaining
        );
        CONTINUE;
      END IF;

      -- 2) Smallest larger off-cut, else smallest larger full sheet.
      SELECT * INTO v_piece FROM polywood_pieces
      WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
        AND status = 'available' AND piece_type = 'cut'
        AND length_m > v_remaining + 0.001
      ORDER BY length_m ASC
      LIMIT 1
      FOR UPDATE;

      IF NOT FOUND THEN
        SELECT * INTO v_piece FROM polywood_pieces
        WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
          AND status = 'available' AND piece_type = 'full'
          AND length_m > v_remaining + 0.001
        ORDER BY length_m ASC
        LIMIT 1
        FOR UPDATE;
      END IF;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient material for "%" (need %m more)', v_product.name, v_remaining;
      END IF;

      v_leftover := ROUND(v_piece.length_m - v_remaining, 3);

      IF v_piece.piece_type = 'full' THEN
        -- Full sheet is consumed as raw material; remnant becomes a new off-cut.
        UPDATE polywood_pieces
        SET status = 'consumed', sale_item_id = p_sale_item_id, updated_at = NOW()
        WHERE id = v_piece.id;
        v_steps := v_steps || jsonb_build_object(
          'piece_id', v_piece.id, 'action', 'split_full',
          'used_length', v_remaining, 'scrap_length', v_leftover
        );

        IF v_leftover > 0.001 THEN
          INSERT INTO polywood_pieces (product_id, warehouse_id, length_m, piece_type, status, notes)
          VALUES (
            p_product_id, p_warehouse_id, v_leftover, 'cut', 'available',
            'Auto remnant from sale item ' || COALESCE(p_sale_item_id::text, 'n/a')
          )
          RETURNING id INTO v_new_piece_id;
          v_scrap := v_scrap || jsonb_build_object('piece_id', v_new_piece_id, 'length_m', v_leftover);
        END IF;
      ELSE
        -- Off-cut: shrink the existing piece in place, no new row needed.
        UPDATE polywood_pieces
        SET length_m = v_leftover, updated_at = NOW()
        WHERE id = v_piece.id;
        v_steps := v_steps || jsonb_build_object(
          'piece_id', v_piece.id, 'action', 'partial',
          'used_length', v_remaining, 'remaining_on_piece', v_leftover
        );
      END IF;
    END LOOP;
  ELSE
    RAISE EXCEPTION 'Unknown sale_mode % for dimensional item', p_sale_mode;
  END IF;

  IF p_sale_item_id IS NOT NULL THEN
    UPDATE sale_items
    SET polywood_cut_details = jsonb_build_object('steps', v_steps, 'scrap_created', v_scrap)
    WHERE id = p_sale_item_id;
  END IF;

  -- Keep products.stock in sync as "total metres currently in stock" for dimensional items.
  UPDATE products
  SET stock = (
    SELECT COALESCE(SUM(length_m), 0)
    FROM polywood_pieces
    WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id AND status = 'available'
  )
  WHERE id = p_product_id;

  RETURN jsonb_build_object('ok', true, 'item_type', 'dimensional', 'steps', v_steps, 'scrap_created', v_scrap);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_advance_payment_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_order_id UUID;
  v_account_id UUID;
  v_amount NUMERIC;
  v_order public.production_orders%ROWTYPE;
  v_tx_id UUID;
  v_event_id UUID;
  v_result JSONB;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Avans payload göndərilməyib';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    v_cached := public.find_erp_event_by_idempotency(v_idempotency);
    IF v_cached IS NOT NULL THEN
      RETURN v_cached->'result';
    END IF;
  END IF;

  IF NOT public.user_has_permission('can_manage_production') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'İcazəniz yoxdur';
  END IF;

  v_order_id := NULLIF(p_payload->>'order_id', '')::uuid;
  IF v_order_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'İstehsal sifarişi identifikatoru tələb olunur';
  END IF;

  SELECT * INTO v_order
  FROM public.production_orders
  WHERE id = v_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'İstehsal sifarişi tapılmadı';
  END IF;

  IF v_order.advance_transaction_id IS NOT NULL THEN
    v_result := jsonb_build_object(
      'success', true,
      'event_type', 'production_advance_payment',
      'order_id', v_order_id,
      'transaction_id', v_order.advance_transaction_id,
      'already_posted', true
    );
    IF v_idempotency IS NOT NULL THEN
      PERFORM public.log_erp_event(
        'production_advance_payment',
        'production_orders',
        v_order_id,
        p_payload,
        NULL,
        v_idempotency,
        v_result
      );
    END IF;
    RETURN v_result;
  END IF;

  v_amount := COALESCE(
    NULLIF(p_payload->>'amount', '')::numeric,
    v_order.advance_payment,
    0
  );

  IF v_amount <= 0.0001 THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'no_advance');
  END IF;

  v_account_id := COALESCE(
    NULLIF(p_payload->>'account_id', '')::uuid,
    v_order.advance_account_id
  );

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Avans ödənişi üçün kassa/bank hesabı seçilməlidir';
  END IF;

  IF v_order.customer_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Avans üçün müştəri seçilməlidir';
  END IF;

  PERFORM id FROM public.accounts WHERE id = v_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
  END IF;

  UPDATE public.production_orders
  SET advance_payment = v_amount,
      advance_account_id = v_account_id
  WHERE id = v_order_id;

  v_tx_id := public.post_cash_transaction(
    v_account_id,
    'Mədaxil',
    v_amount,
    'Satış Ödənişi',
    format('İstehsalat avansı — %s', v_order.order_no),
    v_order_id,
    'production',
    v_order_id
  );

  UPDATE public.production_orders
  SET advance_transaction_id = v_tx_id,
      advance_posted_at = NOW()
  WHERE id = v_order_id;

  PERFORM public.refresh_customer_ar_balance(v_order.customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'production_advance_payment',
    'order_id', v_order_id,
    'transaction_id', v_tx_id,
    'amount', v_amount
  );

  v_event_id := public.log_erp_event(
    'production_advance_payment',
    'production_orders',
    v_order_id,
    p_payload,
    NULL,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_delivery_event(p_order_id uuid, p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_order production_orders%ROWTYPE;
  v_existing_sale_id UUID;
  v_sale_id UUID;
  v_product_id UUID;
  v_product_code TEXT;
  v_product_name TEXT;
  v_product_unit TEXT;
  v_sell_price NUMERIC;
  v_qty NUMERIC;
  v_project_price NUMERIC;
  v_install_fee NUMERIC;
  v_subtotal NUMERIC;
  v_advance NUMERIC;
  v_remaining NUMERIC;
  v_doc_no TEXT;
  v_material_cost NUMERIC := 0;
  v_outsource_cost NUMERIC := 0;
  v_expense_cost NUMERIC := 0;
  v_contractor_cost NUMERIC := 0;
  v_total_cost NUMERIC := 0;
  v_unit_cogs NUMERIC := 0;
  v_unit_sell NUMERIC := 0;
  v_stock NUMERIC := 0;
  v_payments JSONB := '[]'::jsonb;
  v_create_sale BOOLEAN := false;
  v_revenue_journal_id UUID;
  v_cogs_journal_id UUID;
  v_tx_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_payload JSONB;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'order_required'
      USING ERRCODE = '22023',
            MESSAGE = 'İstehsal sifarişi identifikatoru tələb olunur';
  END IF;

  v_idempotency := 'production_delivery:' || p_order_id::text;
  v_cached := public.find_erp_event_by_idempotency(v_idempotency);
  IF v_cached IS NOT NULL THEN
    RETURN v_cached->'result';
  END IF;

  IF NOT public.user_has_permission('can_manage_production') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'İcazəniz yoxdur';
  END IF;

  SELECT * INTO v_order
  FROM production_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_order_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'İstehsal sifarişi tapılmadı';
  END IF;

  IF v_order.sale_id IS NOT NULL AND v_order.status = 'Delivered' THEN
    SELECT doc_no INTO v_doc_no FROM sales WHERE id = v_order.sale_id;
    RETURN jsonb_build_object(
      'success', true,
      'event_type', 'production_delivery',
      'order_id', p_order_id,
      'order_type', v_order.type,
      'sale_id', v_order.sale_id,
      'doc_no', COALESCE(v_doc_no, v_order.order_no),
      'product_id', v_order.finished_product_id,
      'already_completed', true,
      'invoice_created', true
    );
  END IF;

  SELECT id INTO v_existing_sale_id
  FROM sales
  WHERE production_order_id = p_order_id
  LIMIT 1;

  IF v_existing_sale_id IS NOT NULL THEN
    RAISE EXCEPTION 'duplicate_sale_orphan'
      USING ERRCODE = '23505',
            MESSAGE = 'Bu sifariş üçün satış fakturası artıq mövcuddur, lakin sifariş bağlanmayıb. Administratorla əlaqə saxlayın.';
  END IF;

  IF v_order.status IS DISTINCT FROM 'Ready' THEN
    RAISE EXCEPTION 'order_not_ready'
      USING ERRCODE = '22023',
            MESSAGE = 'Təhvil yalnız «Hazır» statusundan verilə bilər';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM production_materials
    WHERE production_order_id = p_order_id
      AND COALESCE(issued, false) = false
  ) THEN
    RAISE EXCEPTION 'materials_pending'
      USING ERRCODE = '22023',
            MESSAGE = 'Bütün material sətirləri verilməlidir';
  END IF;

  v_qty := GREATEST(COALESCE(v_order.quantity, 1), 1);

  IF v_order.type = 'Series' THEN
    IF NOT COALESCE(v_order.finished_goods_posted, false) THEN
      RAISE EXCEPTION 'finished_goods_not_posted'
        USING ERRCODE = '22023',
              MESSAGE = 'Hazır məhsul anbara yazılmayıb. Ævvəlcə «Hazır» statusuna keçin.';
    END IF;

    IF v_order.finished_product_id IS NULL THEN
      RAISE EXCEPTION 'finished_product_required'
        USING ERRCODE = '22023',
              MESSAGE = 'Seriya sifarişi üçün hazır məhsul təyin edilməyib';
    END IF;

    v_product_id := v_order.finished_product_id;
    v_create_sale := v_order.customer_id IS NOT NULL;

    SELECT code, name, unit, COALESCE(sell_price, 0)
    INTO v_product_code, v_product_name, v_product_unit, v_sell_price
    FROM products
    WHERE id = v_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'finished_product_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Hazır məhsul tapılmadı';
    END IF;

    SELECT stock INTO v_stock FROM products WHERE id = v_product_id FOR UPDATE;
    IF COALESCE(v_stock, 0) + 0.0001 < v_qty THEN
      RAISE EXCEPTION 'insufficient_finished_stock'
        USING ERRCODE = '22023',
              MESSAGE = format(
                'Hazır məhsul stok kifayət etmir (mövcud: %s, tələb: %s)',
                COALESCE(v_stock, 0),
                v_qty
              );
    END IF;

    v_total_cost := public.compute_production_wip_cost(p_order_id);

    IF v_create_sale THEN
      IF v_order.customer_id IS NULL THEN
        RAISE EXCEPTION 'customer_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Təhvil üçün müştəri seçilməlidir';
      END IF;

      v_project_price := COALESCE(NULLIF(v_order.total_project_price, 0), v_sell_price * v_qty);
      IF v_project_price <= 0 THEN
        RAISE EXCEPTION 'invalid_total_price'
          USING ERRCODE = '22023',
                MESSAGE = 'Satış qiyməti sıfırdan böyük olmalıdır';
      END IF;

      v_install_fee := COALESCE(v_order.installation_fee, 0);
      v_subtotal := v_project_price + v_install_fee;
      v_advance := GREATEST(COALESCE(v_order.advance_payment, 0), 0);
      v_remaining := GREATEST(v_subtotal - v_advance, 0);

      IF v_advance > 0.0001 AND p_account_id IS NULL THEN
        RAISE EXCEPTION 'advance_account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Avans ödənişi üçün kassa/bank hesabı seçilməlidir';
      END IF;

      IF v_advance > 0.0001 THEN
        v_payments := jsonb_build_array(
          jsonb_build_object(
            'id', gen_random_uuid()::text,
            'method', 'Avans',
            'amount', v_advance,
            'account_id', p_account_id
          )
        );
      END IF;

      v_doc_no := 'SF-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int;

      INSERT INTO sales (
        doc_no, invoice_number, doc_date, customer_id, customer_name,
        seller_id, seller_name, warehouse_name, subtotal, discount_total, vat_total,
        total_amount, paid_amount, remaining_balance, delivery_type, delivery_fee,
        note, notes, production_order_id, payments
      )
      VALUES (
        v_doc_no, v_doc_no, CURRENT_DATE, v_order.customer_id, v_order.customer_name,
        auth.uid(), NULL, v_order.warehouse_name, v_subtotal, 0, 0,
        v_subtotal, v_advance, v_remaining,
        CASE WHEN v_install_fee > 0 THEN 'paid' ELSE 'free' END,
        v_install_fee,
        'Seriya istehsal təhvil: ' || v_order.order_no,
        COALESCE(v_order.notes, v_order.project_scope),
        p_order_id, v_payments
      )
      RETURNING id INTO v_sale_id;

      INSERT INTO sale_items (
        sale_id, product_id, product_code, product_name,
        warehouse_id, warehouse_name, quantity, unit,
        unit_price, discount_percent, vat_rate, line_total, extra_info
      )
      VALUES (
        v_sale_id, v_product_id, v_product_code, v_product_name,
        v_order.warehouse_id, v_order.warehouse_name, v_qty,
        COALESCE(v_product_unit, 'Ædəd'),
        CASE WHEN v_qty > 0 THEN ROUND(v_project_price / v_qty, 2) ELSE v_project_price END,
        0, 0, v_project_price,
        'Seriya istehsal — ' || v_order.order_no
      );

      IF v_install_fee > 0.0001 THEN
        INSERT INTO sale_items (
          sale_id, product_id, product_code, product_name,
          warehouse_id, warehouse_name, quantity, unit,
          unit_price, discount_percent, vat_rate, line_total, extra_info
        )
        VALUES (
          v_sale_id, NULL, NULL, 'Quraşdırma və çatdırılma',
          NULL, v_order.warehouse_name, 1, 'Xidmət',
          v_install_fee, 0, 0, v_install_fee, v_order.order_no
        );
      END IF;

      v_revenue_journal_id := public.post_journal_entry(
        jsonb_build_object(
          'source_type', 'production_delivery_revenue',
          'source_id', v_sale_id,
          'idempotency_key', v_idempotency || ':revenue',
          'memo', format('Seriya satış gəliri — %s', v_doc_no),
          'lines', jsonb_build_array(
            jsonb_build_object(
              'coa_code', '1200',
              'debit', v_subtotal,
              'credit', 0,
              'partner_type', 'customer',
              'partner_id', v_order.customer_id,
              'line_memo', 'AR — ' || v_doc_no
            ),
            jsonb_build_object(
              'coa_code', '4100',
              'debit', 0,
              'credit', v_subtotal,
              'line_memo', 'Gəlir — ' || v_doc_no
            )
          )
        )
      );

      IF v_advance > 0.0001 THEN
        IF v_order.advance_transaction_id IS NOT NULL THEN
          v_tx_id := v_order.advance_transaction_id;
        ELSE
          v_tx_id := public.post_cash_transaction(
            p_account_id,
            'Mədaxil',
            v_advance,
            'Satış Ödənişi',
            format('Seriya istehsal avansı — %s (%s)', v_doc_no, v_order.order_no),
            p_order_id,
            'production',
            p_order_id
          );
        END IF;
      END IF;

      PERFORM public.refresh_customer_ar_balance(v_order.customer_id);
    END IF;

    UPDATE products
    SET stock = COALESCE(v_stock, 0) - v_qty
    WHERE id = v_product_id;

    IF v_total_cost > 0.0001 THEN
      v_cogs_journal_id := public.post_journal_entry(
        jsonb_build_object(
          'source_type', 'production_delivery_cogs',
          'source_id', p_order_id,
          'idempotency_key', v_idempotency || ':cogs',
          'memo', format('Seriya COGS — %s', v_order.order_no),
          'lines', jsonb_build_array(
            jsonb_build_object(
              'coa_code', '5100',
              'debit', v_total_cost,
              'credit', 0,
              'line_memo', 'COGS — ' || v_order.order_no
            ),
            jsonb_build_object(
              'coa_code', '1300',
              'debit', 0,
              'credit', v_total_cost,
              'line_memo', 'Inventar — ' || v_order.order_no
            )
          )
        )
      );
    END IF;

    UPDATE production_orders
    SET sale_id = COALESCE(v_sale_id, sale_id),
        delivered_at = NOW(),
        status = 'Delivered',
        updated_at = NOW()
    WHERE id = p_order_id;

    v_result := jsonb_build_object(
      'success', true,
      'event_type', 'production_delivery',
      'order_type', 'Series',
      'order_id', p_order_id,
      'sale_id', v_sale_id,
      'doc_no', COALESCE(v_doc_no, v_order.order_no),
      'product_id', v_product_id,
      'invoice_created', v_create_sale,
      'revenue_journal_entry_id', v_revenue_journal_id,
      'cogs_journal_entry_id', v_cogs_journal_id,
      'transaction_id', v_tx_id,
      'already_completed', false
    );

  ELSIF v_order.type = 'Custom' THEN
    IF v_order.customer_id IS NULL THEN
      RAISE EXCEPTION 'customer_required'
        USING ERRCODE = '22023',
              MESSAGE = 'Təhvil üçün müştəri seçilməlidir';
    END IF;

    v_project_price := COALESCE(v_order.total_project_price, 0);
    IF v_project_price <= 0 THEN
      RAISE EXCEPTION 'invalid_total_price'
        USING ERRCODE = '22023',
              MESSAGE = 'Layihə qiyməti sıfırdan böyük olmalıdır';
    END IF;

    v_install_fee := COALESCE(v_order.installation_fee, 0);
    v_subtotal := v_project_price + v_install_fee;
    v_advance := GREATEST(COALESCE(v_order.advance_payment, 0), 0);
    v_remaining := GREATEST(v_subtotal - v_advance, 0);

    IF v_advance > 0.0001 AND p_account_id IS NULL THEN
      RAISE EXCEPTION 'advance_account_required'
        USING ERRCODE = '22023',
              MESSAGE = 'Avans ödənişi üçün kassa/bank hesabı seçilməlidir';
    END IF;

    IF v_advance > 0.0001 THEN
      PERFORM id FROM accounts WHERE id = p_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;

      v_payments := jsonb_build_array(
        jsonb_build_object(
          'id', gen_random_uuid()::text,
          'method', 'Avans',
          'amount', v_advance,
          'account_id', p_account_id
        )
      );
    END IF;

    v_total_cost := public.compute_production_wip_cost(p_order_id);
    v_unit_cogs := CASE WHEN v_qty > 0 THEN ROUND(v_total_cost / v_qty, 2) ELSE 0 END;
    v_unit_sell := CASE WHEN v_qty > 0 THEN ROUND(v_subtotal / v_qty, 2) ELSE v_subtotal END;

    IF v_order.finished_product_id IS NOT NULL THEN
      v_product_id := v_order.finished_product_id;
      SELECT code, name, unit
      INTO v_product_code, v_product_name, v_product_unit
      FROM products
      WHERE id = v_product_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'finished_product_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Hazır məhsul tapılmadı';
      END IF;
    ELSE
      v_product_code := 'MTO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
      v_product_name := COALESCE(NULLIF(btrim(v_order.project_name), ''), v_order.order_no);
      v_product_unit := 'Ædəd';

      INSERT INTO products (
        code, name, category, subcategory, unit,
        buy_price, sell_price, stock, min_stock, extra_info
      )
      VALUES (
        v_product_code, v_product_name, 'Fərdi istehsal', 'Make-to-Order', v_product_unit,
        v_unit_cogs, v_unit_sell, 0, 0,
        'Production order ' || v_order.order_no
      )
      RETURNING id INTO v_product_id;
    END IF;

    SELECT stock INTO v_stock FROM products WHERE id = v_product_id FOR UPDATE;
    UPDATE products SET stock = COALESCE(v_stock, 0) + v_qty WHERE id = v_product_id;

    v_doc_no := 'SF-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int;

    INSERT INTO sales (
      doc_no, invoice_number, doc_date, customer_id, customer_name,
      seller_id, seller_name, warehouse_name, subtotal, discount_total, vat_total,
      total_amount, paid_amount, remaining_balance, delivery_type, delivery_fee,
      note, notes, production_order_id, payments
    )
    VALUES (
      v_doc_no, v_doc_no, CURRENT_DATE, v_order.customer_id, v_order.customer_name,
      auth.uid(), NULL, v_order.warehouse_name, v_subtotal, 0, 0,
      v_subtotal, v_advance, v_remaining,
      CASE WHEN v_install_fee > 0 THEN 'paid' ELSE 'free' END,
      v_install_fee,
      'Fərdi istehsal təhvil: ' || v_order.order_no,
      COALESCE(v_order.project_scope, v_order.notes),
      p_order_id, v_payments
    )
    RETURNING id INTO v_sale_id;

    INSERT INTO sale_items (
      sale_id, product_id, product_code, product_name,
      warehouse_id, warehouse_name, quantity, unit,
      unit_price, discount_percent, vat_rate, line_total, extra_info
    )
    VALUES (
      v_sale_id, v_product_id, v_product_code, v_product_name,
      v_order.warehouse_id, v_order.warehouse_name, v_qty,
      COALESCE(v_product_unit, 'Ædəd'),
      CASE WHEN v_qty > 0 THEN ROUND(v_project_price / v_qty, 2) ELSE v_project_price END,
      0, 0, v_project_price,
      'COGS ref: ' || v_order.order_no
    );

    IF v_install_fee > 0.0001 THEN
      INSERT INTO sale_items (
        sale_id, product_id, product_code, product_name,
        warehouse_id, warehouse_name, quantity, unit,
        unit_price, discount_percent, vat_rate, line_total, extra_info
      )
      VALUES (
        v_sale_id, NULL, NULL, 'Quraşdırma və çatdırılma',
        NULL, v_order.warehouse_name, 1, 'Xidmət',
        v_install_fee, 0, 0, v_install_fee, v_order.order_no
      );
    END IF;

    SELECT stock INTO v_stock FROM products WHERE id = v_product_id FOR UPDATE;
    IF COALESCE(v_stock, 0) + 0.0001 < v_qty THEN
      RAISE EXCEPTION 'insufficient_finished_stock'
        USING ERRCODE = '22023',
              MESSAGE = 'Hazır məhsul stok çıxışı mümkün deyil';
    END IF;

    UPDATE products SET stock = COALESCE(v_stock, 0) - v_qty WHERE id = v_product_id;

    v_revenue_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'production_delivery_revenue',
        'source_id', v_sale_id,
        'idempotency_key', v_idempotency || ':revenue',
        'memo', format('Fərdi satış gəliri — %s', v_doc_no),
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', '1200',
            'debit', v_subtotal,
            'credit', 0,
            'partner_type', 'customer',
            'partner_id', v_order.customer_id,
            'line_memo', 'AR — ' || v_doc_no
          ),
          jsonb_build_object(
            'coa_code', '4100',
            'debit', 0,
            'credit', v_subtotal,
            'line_memo', 'Gəlir — ' || v_doc_no
          )
        )
      )
    );

    IF v_total_cost > 0.0001 THEN
      v_cogs_journal_id := public.post_journal_entry(
        jsonb_build_object(
          'source_type', 'production_delivery_cogs',
          'source_id', p_order_id,
          'idempotency_key', v_idempotency || ':cogs',
          'memo', format('Fərdi COGS — %s', v_order.order_no),
          'lines', jsonb_build_array(
            jsonb_build_object(
              'coa_code', '5100',
              'debit', v_total_cost,
              'credit', 0,
              'line_memo', 'COGS — ' || v_order.order_no
            ),
            jsonb_build_object(
              'coa_code', '1350',
              'debit', 0,
              'credit', v_total_cost,
              'line_memo', 'WIP — ' || v_order.order_no
            )
          )
        )
      );
    END IF;

    IF v_advance > 0.0001 THEN
      IF v_order.advance_transaction_id IS NOT NULL THEN
        v_tx_id := v_order.advance_transaction_id;
      ELSE
        v_tx_id := public.post_cash_transaction(
          p_account_id,
          'Mədaxil',
          v_advance,
          'Satış Ödənişi',
          format('Fərdi istehsal avansı — %s (%s)', v_doc_no, v_order.order_no),
          p_order_id,
          'production',
          p_order_id
        );
      END IF;
    END IF;

    PERFORM public.refresh_customer_ar_balance(v_order.customer_id);

    UPDATE production_orders
    SET finished_product_id = v_product_id,
        finished_product_name = v_product_name,
        sale_id = v_sale_id,
        delivered_at = NOW(),
        finished_goods_posted = true,
        status = 'Delivered',
        updated_at = NOW()
    WHERE id = p_order_id;

    v_result := jsonb_build_object(
      'success', true,
      'event_type', 'production_delivery',
      'order_type', 'Custom',
      'order_id', p_order_id,
      'sale_id', v_sale_id,
      'doc_no', v_doc_no,
      'product_id', v_product_id,
      'invoice_created', true,
      'revenue_journal_entry_id', v_revenue_journal_id,
      'cogs_journal_entry_id', v_cogs_journal_id,
      'transaction_id', v_tx_id,
      'already_completed', false
    );
  ELSE
    RAISE EXCEPTION 'invalid_order_type'
      USING ERRCODE = '22023',
            MESSAGE = 'Naməlum istehsal sifarişi tipi';
  END IF;

  v_payload := jsonb_build_object(
    'order_id', p_order_id,
    'account_id', p_account_id
  );

  v_event_id := public.log_erp_event(
    'production_delivery',
    'production_orders',
    p_order_id,
    v_payload,
    COALESCE(v_revenue_journal_id, v_cogs_journal_id),
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_material_issue_event(p_order_id uuid, p_material_ids uuid[] DEFAULT NULL::uuid[], p_update_status boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_order production_orders%ROWTYPE;
  v_material RECORD;
  v_product RECORD;
  v_issue_cost NUMERIC := 0;
  v_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_update_status BOOLEAN;
  v_pending_count INT;
  v_issued_count INT := 0;
  v_payload JSONB;
  v_issued_ids UUID[] := '{}';
  v_slip_id UUID;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'order_required'
      USING ERRCODE = '22023',
            MESSAGE = 'İstehsal sifarişi identifikatoru tələb olunur';
  END IF;

  v_update_status := COALESCE(
    p_update_status,
    p_material_ids IS NULL OR cardinality(p_material_ids) = 0
  );

  v_idempotency := CASE
    WHEN p_material_ids IS NOT NULL AND cardinality(p_material_ids) > 0 THEN
      'production_material_issue:' || p_order_id::text || ':' || md5(p_material_ids::text)
    ELSE
      'production_material_issue:' || p_order_id::text
  END;

  v_cached := public.find_erp_event_by_idempotency(v_idempotency);
  IF v_cached IS NOT NULL THEN
    RETURN v_cached->'result';
  END IF;

  IF NOT public.user_has_permission('can_manage_production') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'İcazəniz yoxdur';
  END IF;

  SELECT * INTO v_order
  FROM production_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_order_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'İstehsal sifarişi tapılmadı';
  END IF;

  IF v_update_status AND v_order.status IS DISTINCT FROM 'Draft' AND v_order.status IS DISTINCT FROM 'In-Progress' THEN
    RAISE EXCEPTION 'invalid_status'
      USING ERRCODE = '22023',
            MESSAGE = 'Material verilməsi yalnız «Layihə» və ya «İstehsalda» statusundan mümkündür';
  END IF;

  FOR v_material IN
    SELECT pm.*, p.inventory_mode, p.name AS product_display_name
    FROM production_materials pm
    LEFT JOIN products p ON p.id = pm.product_id
    WHERE pm.production_order_id = p_order_id
      AND COALESCE(pm.issued, false) = false
      AND (
        p_material_ids IS NULL
        OR cardinality(p_material_ids) = 0
        OR pm.id = ANY(p_material_ids)
      )
    ORDER BY pm.created_at NULLS LAST, pm.id
  LOOP
    IF v_material.product_id IS NULL THEN
      UPDATE production_materials
      SET issued = true,
          issued_at = COALESCE(issued_at, NOW())
      WHERE id = v_material.id;
      v_issued_ids := array_append(v_issued_ids, v_material.id);
      v_issued_count := v_issued_count + 1;
      CONTINUE;
    END IF;

    SELECT id, stock, inventory_mode, name
    INTO v_product
    FROM products
    WHERE id = v_material.product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = format('Material çıxışı: %s — məhsul tapılmadı', COALESCE(v_material.product_display_name, v_material.product_id::text));
    END IF;

    IF COALESCE(v_product.inventory_mode, 'standard') <> 'polywood' THEN
      IF COALESCE(v_product.stock, 0) + 0.000001 < COALESCE(v_material.quantity, 0) THEN
        RAISE EXCEPTION 'insufficient_stock'
          USING ERRCODE = '22023',
                MESSAGE = format(
                  'Material çıxışı: %s — stok kifayət etmir (mövcud: %s, tələb: %s)',
                  COALESCE(v_product.name, v_material.product_id::text),
                  trim(to_char(COALESCE(v_product.stock, 0), 'FM999999990.00')),
                  trim(to_char(COALESCE(v_material.quantity, 0), 'FM999999990.00'))
                );
      END IF;

      UPDATE products
      SET stock = COALESCE(stock, 0) - COALESCE(v_material.quantity, 0)
      WHERE id = v_material.product_id;

      INSERT INTO stock_movements (
        product_id,
        warehouse_id,
        movement_type,
        quantity,
        unit,
        reference_type,
        reference_id,
        source_line_id,
        description,
        created_by
      )
      VALUES (
        v_material.product_id,
        v_material.warehouse_id,
        'out',
        COALESCE(v_material.quantity, 0),
        COALESCE(v_material.unit, 'Ədəd'),
        'production',
        p_order_id,
        v_material.id,
        'İstehsalat üçün material',
        auth.uid()
      );
    END IF;

    v_issue_cost := v_issue_cost + public.production_material_line_cost(
      v_material.quantity,
      v_material.unit_cost,
      v_material.line_cost
    );

    UPDATE production_materials
    SET issued = true,
        issued_at = COALESCE(issued_at, NOW())
    WHERE id = v_material.id;

    UPDATE production_stock_reservations
    SET status = 'consumed',
        consumed_at = COALESCE(consumed_at, NOW())
    WHERE production_material_id = v_material.id;

    v_issued_ids := array_append(v_issued_ids, v_material.id);
    v_issued_count := v_issued_count + 1;
  END LOOP;

  IF v_issued_count = 0 THEN
    IF p_material_ids IS NOT NULL AND cardinality(p_material_ids) > 0 THEN
      RAISE EXCEPTION 'materials_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Verilməmiş material tapılmadı';
    END IF;
    RAISE EXCEPTION 'materials_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Material çıxışı: BOM material sətri tapılmadı';
  END IF;

  IF v_issue_cost > 0.0001 THEN
    v_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'production_material_issue',
        'source_id', p_order_id,
        'idempotency_key', v_idempotency,
        'memo', format('Material verilməsi — %s', v_order.order_no),
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', '1350',
            'debit', v_issue_cost,
            'credit', 0,
            'line_memo', 'WIP — ' || v_order.order_no
          ),
          jsonb_build_object(
            'coa_code', '1300',
            'debit', 0,
            'credit', v_issue_cost,
            'line_memo', 'Xammal — ' || v_order.order_no
          )
        )
      )
    );
  END IF;

  v_slip_id := public.production_record_material_issue_slip(p_order_id, v_issued_ids);

  SELECT COUNT(*) INTO v_pending_count
  FROM production_materials
  WHERE production_order_id = p_order_id
    AND COALESCE(issued, false) = false;

  IF v_pending_count = 0 OR v_update_status THEN
    UPDATE production_orders
    SET materials_allocated = true,
        status = CASE
          WHEN v_update_status AND v_order.status = 'Draft' THEN 'In-Progress'
          ELSE status
        END,
        updated_at = NOW()
    WHERE id = p_order_id;
  END IF;

  v_payload := jsonb_build_object(
    'order_id', p_order_id,
    'material_ids', COALESCE(to_jsonb(p_material_ids), '[]'::jsonb),
    'update_status', v_update_status
  );

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'production_material_issue',
    'order_id', p_order_id,
    'issued_count', v_issued_count,
    'issue_cost', v_issue_cost,
    'journal_entry_id', v_journal_id,
    'warehouse_slip_id', v_slip_id,
    'materials_allocated', true,
    'status', CASE WHEN v_update_status THEN 'In-Progress' ELSE v_order.status END
  );

  v_event_id := public.log_erp_event(
    'production_material_issue',
    'production_orders',
    p_order_id,
    v_payload,
    v_journal_id,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_production_ready_event(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_order production_orders%ROWTYPE;
  v_qty NUMERIC;
  v_wip_cost NUMERIC;
  v_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_stock NUMERIC;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'order_required'
      USING ERRCODE = '22023',
            MESSAGE = 'İstehsal sifarişi identifikatoru tələb olunur';
  END IF;

  v_idempotency := 'production_ready:' || p_order_id::text;
  v_cached := public.find_erp_event_by_idempotency(v_idempotency);
  IF v_cached IS NOT NULL THEN
    RETURN v_cached->'result';
  END IF;

  IF NOT public.user_has_permission('can_manage_production') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'İcazəniz yoxdur';
  END IF;

  SELECT * INTO v_order
  FROM production_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_order_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'İstehsal sifarişi tapılmadı';
  END IF;

  IF v_order.type IS DISTINCT FROM 'Series' THEN
    RAISE EXCEPTION 'invalid_order_type'
      USING ERRCODE = '22023',
            MESSAGE = 'Hazır statusu yalnız seriya sifarişləri üçün aktivdir';
  END IF;

  IF COALESCE(v_order.finished_goods_posted, false) THEN
    RETURN jsonb_build_object(
      'success', true,
      'event_type', 'production_ready',
      'order_id', p_order_id,
      'already_completed', true,
      'finished_goods_posted', true
    );
  END IF;

  IF v_order.status IS DISTINCT FROM 'In-Progress' AND v_order.status IS DISTINCT FROM 'Ready' THEN
    RAISE EXCEPTION 'invalid_status'
      USING ERRCODE = '22023',
            MESSAGE = 'Hazır statusu yalnız «İstehsalda» statusundan aktivdir';
  END IF;

  IF v_order.finished_product_id IS NULL THEN
    RAISE EXCEPTION 'finished_product_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Hazır məhsul təyin edilməyib';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM production_materials
    WHERE production_order_id = p_order_id
      AND COALESCE(issued, false) = false
  ) THEN
    RAISE EXCEPTION 'materials_pending'
      USING ERRCODE = '22023',
            MESSAGE = 'Bütün BOM materialları verilməlidir';
  END IF;

  v_qty := GREATEST(COALESCE(v_order.quantity, 1), 1);

  SELECT stock INTO v_stock
  FROM products
  WHERE id = v_order.finished_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'finished_product_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hazır məhsul tapılmadı';
  END IF;

  UPDATE products
  SET stock = COALESCE(v_stock, 0) + v_qty
  WHERE id = v_order.finished_product_id;

  v_wip_cost := public.compute_production_wip_cost(p_order_id);

  IF v_wip_cost > 0.0001 THEN
    v_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'production_ready',
        'source_id', p_order_id,
        'idempotency_key', v_idempotency,
        'memo', format('Hazır məhsul anbara — %s', v_order.order_no),
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', '1300',
            'debit', v_wip_cost,
            'credit', 0,
            'line_memo', 'Hazır məhsul — ' || v_order.order_no
          ),
          jsonb_build_object(
            'coa_code', '1350',
            'debit', 0,
            'credit', v_wip_cost,
            'line_memo', 'WIP bağlanması — ' || v_order.order_no
          )
        )
      )
    );
  END IF;

  UPDATE production_orders
  SET finished_goods_posted = true,
      status = 'Ready',
      updated_at = NOW()
  WHERE id = p_order_id;

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'production_ready',
    'order_id', p_order_id,
    'finished_product_id', v_order.finished_product_id,
    'quantity', v_qty,
    'wip_cost', v_wip_cost,
    'journal_entry_id', v_journal_id,
    'finished_goods_posted', true,
    'status', 'Ready'
  );

  v_event_id := public.log_erp_event(
    'production_ready',
    'production_orders',
    p_order_id,
    jsonb_build_object('order_id', p_order_id),
    v_journal_id,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_purchase_receipt_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_supplier_id UUID;
  v_purchase_id UUID;
  v_invoice_number TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_debt_amount NUMERIC;
  v_item JSONB;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_unit_price NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_account_name TEXT;
  v_pay_note TEXT;
  v_stock_demand JSONB := '{}'::jsonb;
  v_price_map JSONB := '{}'::jsonb;
  v_key TEXT;
  v_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_add_exp_total NUMERIC;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Alış event payload göndərilməyib';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    v_cached := public.find_erp_event_by_idempotency(v_idempotency);
    IF v_cached IS NOT NULL THEN
      RETURN v_cached->'result';
    END IF;
  END IF;

  IF NOT (
    public.require_permission('can_edit_purchases')
    OR public.require_permission('can_create_purchase')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Alış yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Æn azı bir məhsul tələb olunur';
  END IF;

  v_supplier_id := NULLIF(v_header->>'supplier_id', '')::uuid;
  IF v_supplier_id IS NULL THEN
    RAISE EXCEPTION 'supplier_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Təchizatçı seçilməlidir';
  END IF;

  PERFORM id FROM suppliers WHERE id = v_supplier_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Təchizatçı tapılmadı';
  END IF;

  v_total_amount := COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0);
  v_paid_amount := COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0);
  v_debt_amount := COALESCE(
    NULLIF(v_header->>'debt_amount', '')::numeric,
    GREATEST(v_total_amount - v_paid_amount, 0)
  );

  IF v_total_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_total_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Alış məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF v_paid_amount > v_total_amount + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  IF abs((v_paid_amount + v_debt_amount) - v_total_amount) > 0.01 THEN
    RAISE EXCEPTION 'amount_mismatch'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən və borc məbləğlərinin cəmi ümumi məbləğə bərabər olmalıdır';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
    v_qty := COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0);
    v_unit_price := COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0);

    IF v_product_id IS NULL OR v_qty <= 0 OR v_unit_price <= 0 THEN
      RAISE EXCEPTION 'invalid_item'
        USING ERRCODE = '22023',
              MESSAGE = 'Hər sətirdə məhsul, miqdar və qiymət tələb olunur';
    END IF;

    v_key := v_product_id::text;
    v_stock_demand := jsonb_set(
      v_stock_demand,
      ARRAY[v_key],
      to_jsonb(COALESCE((v_stock_demand->>v_key)::numeric, 0) + v_qty),
      true
    );
    v_price_map := jsonb_set(v_price_map, ARRAY[v_key], to_jsonb(v_unit_price), true);
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    PERFORM id FROM products WHERE id = v_key::uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Məhsul tapılmadı: ' || v_key;
    END IF;
  END LOOP;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  v_invoice_number := COALESCE(
    NULLIF(trim(v_header->>'invoice_number'), ''),
    NULLIF(trim(p_payload->>'invoice_number'), ''),
    'PUR-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int
  );

  INSERT INTO purchases (
    invoice_number, supplier_id, warehouse_id, doc_date, responsible_id, responsible_name,
    total_amount, paid_amount, debt_amount, status, notes
  )
  VALUES (
    v_invoice_number,
    v_supplier_id,
    NULLIF(v_header->>'warehouse_id', '')::uuid,
    COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
    NULLIF(v_header->>'responsible_id', '')::uuid,
    NULLIF(trim(v_header->>'responsible_name'), ''),
    v_total_amount,
    v_paid_amount,
    v_debt_amount,
    COALESCE(
      NULLIF(trim(v_header->>'status'), ''),
      CASE WHEN v_debt_amount > 0.0001 THEN 'Borclu' ELSE 'Ödənilib' END
    ),
    NULLIF(trim(v_header->>'notes'), '')
  )
  RETURNING id INTO v_purchase_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    INSERT INTO purchase_items (
      purchase_id, product_id, product_code, product_name, quantity, unit, unit_price, total_price
    )
    VALUES (
      v_purchase_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ædəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(
        NULLIF(v_item->>'total_price', '')::numeric,
        NULLIF(v_item->>'total', '')::numeric,
        0
      )
    );
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_qty := COALESCE((v_stock_demand->>v_key)::numeric, 0);
    v_unit_price := COALESCE((v_price_map->>v_key)::numeric, 0);

    SELECT stock INTO v_stock
    FROM products
    WHERE id = v_product_id
    FOR UPDATE;

    UPDATE products
    SET stock = COALESCE(v_stock, 0) + v_qty,
        buy_price = v_unit_price
    WHERE id = v_product_id;

    PERFORM public.create_inventory_batch(
      v_product_id,
      v_purchase_id,
      'purchase',
      v_unit_price,
      v_qty
    );
  END LOOP;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;

      SELECT name INTO v_account_name
      FROM accounts
      WHERE id = v_account_id;

      v_pay_note := COALESCE(
        NULLIF(trim(v_pay->>'note'), ''),
        format('Alış fakturası %s', v_invoice_number)
      );
      IF NULLIF(trim(v_pay->>'payment_date'), '') IS NOT NULL THEN
        v_pay_note := trim(v_pay->>'payment_date') || ' — ' || v_pay_note;
      END IF;
      IF v_account_name IS NOT NULL THEN
        v_pay_note := v_pay_note || ' — ' || v_account_name;
      END IF;

      PERFORM public.post_cash_transaction(
        v_account_id,
        'Məxaric',
        v_pay_amount,
        'Alış Ödənişi',
        v_pay_note,
        NULL,
        'purchase',
        v_purchase_id
      );
    END LOOP;
  END IF;

  v_add_exp_total := public.apply_document_additional_expenses(
    COALESCE(p_payload->'additional_expenses', '[]'::jsonb),
    'purchase',
    v_purchase_id,
    v_invoice_number
  );

  UPDATE purchases
  SET additional_expenses = COALESCE(p_payload->'additional_expenses', '[]'::jsonb),
      additional_expenses_total = v_add_exp_total
  WHERE id = v_purchase_id;

  v_journal_id := public.post_purchase_bill_gl_journal(
    v_purchase_id,
    v_invoice_number,
    v_total_amount,
    v_supplier_id,
    v_idempotency
  );

  PERFORM public.refresh_supplier_ap_balance(v_supplier_id);

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'purchase_receipt',
    'purchase_id', v_purchase_id,
    'invoice_number', v_invoice_number,
    'journal_entry_id', v_journal_id,
    'total_amount', v_total_amount,
    'paid_amount', v_paid_amount,
    'debt_amount', v_debt_amount
  );

  v_event_id := public.log_erp_event(
    'purchase_receipt',
    'purchases',
    v_purchase_id,
    p_payload,
    v_journal_id,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_sale_fifo_cogs(p_sale_id uuid, p_doc_no text DEFAULT NULL::text, p_idempotency text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_line_cogs NUMERIC;
  v_total_cogs NUMERIC := 0;
  v_cogs_journal_id UUID;
  v_doc_no TEXT;
BEGIN
  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'sale_id tələb olunur';
  END IF;

  SELECT COALESCE(NULLIF(trim(doc_no), ''), id::text)
  INTO v_doc_no
  FROM public.sales
  WHERE id = p_sale_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Satış tapılmadı';
  END IF;

  v_doc_no := COALESCE(NULLIF(trim(p_doc_no), ''), v_doc_no);

  FOR v_item IN
    SELECT si.id, si.product_id, si.quantity, si.polywood_sale_mode,
           COALESCE(p.is_service, false) AS is_service
    FROM public.sale_items si
    LEFT JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
    ORDER BY si.id
    FOR UPDATE OF si
  LOOP
    IF v_item.product_id IS NULL OR COALESCE(v_item.quantity, 0) <= 0 THEN
      CONTINUE;
    END IF;

    IF v_item.polywood_sale_mode IS NOT NULL THEN
      CONTINUE;
    END IF;

    -- Services have no cost layer.
    IF v_item.is_service THEN
      CONTINUE;
    END IF;

    v_line_cogs := public.fifo_deplete_sale_item(
      v_item.id,
      v_item.product_id,
      v_item.quantity,
      p_sale_id
    );

    UPDATE public.sale_items
    SET cogs_amount = v_line_cogs
    WHERE id = v_item.id;

    v_total_cogs := v_total_cogs + v_line_cogs;
  END LOOP;

  v_total_cogs := ROUND(v_total_cogs, 2);
  v_cogs_journal_id := public.post_sale_cogs_journal(
    p_sale_id,
    v_doc_no,
    v_total_cogs,
    COALESCE(p_idempotency, 'sale_cogs:' || p_sale_id::text)
  );

  UPDATE public.sales
  SET total_cogs = v_total_cogs,
      cogs_journal_entry_id = v_cogs_journal_id
  WHERE id = p_sale_id;

  RETURN jsonb_build_object(
    'total_cogs', v_total_cogs,
    'cogs_journal_entry_id', v_cogs_journal_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.process_sales_invoice_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_decrement_stock BOOLEAN := true;
  v_customer_id UUID;
  v_customer_name TEXT;
  v_sale_id UUID;
  v_doc_no TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_item JSONB;
  v_pay JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_stock NUMERIC;
  v_account_id UUID;
  v_pay_amount NUMERIC;
  v_pay_method TEXT;
  v_skip_stock BOOLEAN;
  v_polywood_mode TEXT;
  v_polywood_sale_mode TEXT;
  v_polywood_length_m NUMERIC;
  v_item_ids JSONB := '[]'::jsonb;
  v_item_id UUID;
  v_idx INT := 0;
  v_stock_demand JSONB := '{}'::jsonb;
  v_key TEXT;
  v_journal_id UUID;
  v_cogs_result JSONB;
  v_total_cogs NUMERIC := 0;
  v_cogs_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_add_exp_total NUMERIC;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış event payload göndərilməyib';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    v_cached := public.find_erp_event_by_idempotency(v_idempotency);
    IF v_cached IS NOT NULL THEN
      RETURN v_cached->'result';
    END IF;
  END IF;

  IF NOT (
    public.require_permission('can_edit_sales')
    OR public.require_permission('can_create_invoice')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Æn azı bir satış sətri tələb olunur';
  END IF;

  IF (p_payload ? 'decrement_stock') THEN
    v_decrement_stock := COALESCE((p_payload->>'decrement_stock')::boolean, true);
  END IF;

  v_customer_id := NULLIF(v_header->>'customer_id', '')::uuid;
  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Müştəri seçilməlidir';
  END IF;

  SELECT COALESCE(NULLIF(trim(full_name), ''), NULLIF(trim(name), ''), NULLIF(trim(company_name), ''), '')
  INTO v_customer_name
  FROM customers
  WHERE id = v_customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  v_total_amount := COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0);
  v_paid_amount := COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0);
  v_remaining := GREATEST(
    COALESCE(NULLIF(v_header->>'remaining_balance', '')::numeric, v_total_amount - v_paid_amount),
    0
  );

  IF v_total_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_total_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Satış məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF v_paid_amount > v_total_amount + 0.0001 THEN
    RAISE EXCEPTION 'overpaid'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödənilən məbləğ ümumi məbləğdən böyük ola bilməz';
  END IF;

  IF v_decrement_stock THEN
    v_stock_demand := public.build_and_validate_sale_stock_demand(v_items);
  END IF;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'account_required'
          USING ERRCODE = '22023',
                MESSAGE = 'Ödəniş üçün kassa/bank hesabı seçilməlidir';
      END IF;

      PERFORM id FROM accounts WHERE id = v_account_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_not_found'
          USING ERRCODE = 'P0002',
                MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
      END IF;
    END LOOP;
  END IF;

  v_doc_no := NULLIF(trim(v_header->>'doc_no'), '');
  IF v_doc_no IS NULL THEN
    v_doc_no := 'SF-' || to_char(CURRENT_DATE, 'YYYY') || '-' || floor(10000 + random() * 90000)::int;
  END IF;

  INSERT INTO sales (
    doc_no, invoice_number, doc_date, customer_id, customer_name,
    seller_id, seller_name, warehouse_name, subtotal, discount_total, vat_total,
    total_amount, paid_amount, remaining_balance, delivery_address, delivery_type,
    delivery_fee, note, notes, payments, created_at
  )
  VALUES (
    v_doc_no,
    COALESCE(NULLIF(trim(v_header->>'invoice_number'), ''), v_doc_no),
    COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
    v_customer_id,
    COALESCE(NULLIF(trim(v_header->>'customer_name'), ''), v_customer_name),
    NULLIF(v_header->>'seller_id', '')::uuid,
    NULLIF(trim(v_header->>'seller_name'), ''),
    NULLIF(trim(v_header->>'warehouse_name'), ''),
    COALESCE(NULLIF(v_header->>'subtotal', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'discount_total', '')::numeric, 0),
    COALESCE(NULLIF(v_header->>'vat_total', '')::numeric, 0),
    v_total_amount,
    v_paid_amount,
    v_remaining,
    NULLIF(trim(v_header->>'delivery_address'), ''),
    COALESCE(NULLIF(trim(v_header->>'delivery_type'), ''), 'free'),
    COALESCE(NULLIF(v_header->>'delivery_fee', '')::numeric, 0),
    NULLIF(trim(v_header->>'note'), ''),
    NULLIF(trim(v_header->>'notes'), ''),
    COALESCE(v_header->'payments', v_payments, '[]'::jsonb),
    COALESCE(NULLIF(v_header->>'created_at', '')::timestamptz, NOW())
  )
  RETURNING id INTO v_sale_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_polywood_sale_mode := CASE
      WHEN v_item ? 'polywood_sale_mode'
      THEN NULLIF(trim(v_item->>'polywood_sale_mode'), '')
      ELSE NULL
    END;

    v_polywood_length_m := NULL;
    IF v_item ? 'polywood_length_m' THEN
      BEGIN
        v_polywood_length_m := NULLIF(trim(v_item->>'polywood_length_m'), '')::numeric;
      EXCEPTION
        WHEN OTHERS THEN
          v_polywood_length_m := NULL;
      END;
    END IF;

    INSERT INTO sale_items (
      sale_id, product_id, product_code, product_name, warehouse_id, warehouse_name,
      quantity, unit, unit_price, discount_percent, vat_rate, line_total, extra_info,
      polywood_sale_mode, polywood_length_m
    )
    VALUES (
      v_sale_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      NULLIF(v_item->>'warehouse_id', '')::uuid,
      NULLIF(trim(v_item->>'warehouse_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ædəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'discount_percent', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'vat_rate', '')::numeric, 0),
      COALESCE(NULLIF(v_item->>'line_total', '')::numeric, NULLIF(v_item->>'total', '')::numeric, 0),
      NULLIF(trim(v_item->>'extra_info'), ''),
      v_polywood_sale_mode,
      v_polywood_length_m
    )
    RETURNING id INTO v_item_id;

    v_item_ids := v_item_ids || jsonb_build_array(
      jsonb_build_object(
        'index', v_idx,
        'id', v_item_id,
        'product_id', NULLIF(v_item->>'product_id', '')::uuid,
        'polywood_sale_mode', v_polywood_sale_mode
      )
    );
    v_idx := v_idx + 1;
  END LOOP;

  IF v_decrement_stock THEN
    PERFORM public.apply_sale_stock_decrement(v_stock_demand);

    v_cogs_result := public.process_sale_fifo_cogs(
      v_sale_id,
      v_doc_no,
      COALESCE(v_idempotency, 'sale_invoice:' || v_sale_id::text) || ':cogs'
    );
    v_total_cogs := COALESCE((v_cogs_result->>'total_cogs')::numeric, 0);
    v_cogs_journal_id := NULLIF(v_cogs_result->>'cogs_journal_entry_id', '')::uuid;
  END IF;

  IF jsonb_typeof(v_payments) = 'array' THEN
    FOR v_pay IN SELECT value FROM jsonb_array_elements(v_payments)
    LOOP
      v_pay_amount := COALESCE(NULLIF(v_pay->>'amount', '')::numeric, 0);
      IF v_pay_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_account_id := NULLIF(v_pay->>'account_id', '')::uuid;
      v_pay_method := COALESCE(NULLIF(trim(v_pay->>'method'), ''), 'Ödəniş');

      PERFORM public.post_cash_transaction(
        v_account_id,
        'Mədaxil',
        v_pay_amount,
        'Satış Ödənişi',
        format('Satış fakturası %s — %s', v_doc_no, v_pay_method),
        NULL,
        'sale',
        v_sale_id
      );
    END LOOP;
  END IF;

  v_add_exp_total := public.apply_document_additional_expenses(
    COALESCE(p_payload->'additional_expenses', '[]'::jsonb),
    'sale',
    v_sale_id,
    v_doc_no
  );

  UPDATE sales
  SET additional_expenses = COALESCE(p_payload->'additional_expenses', '[]'::jsonb),
      additional_expenses_total = v_add_exp_total
  WHERE id = v_sale_id;

  v_journal_id := public.post_sale_invoice_gl_journal(
    v_sale_id,
    v_doc_no,
    v_total_amount,
    v_customer_id,
    v_idempotency
  );

  PERFORM public.refresh_customer_ar_balance(v_customer_id);

  v_result := jsonb_build_object(
    'success', true,
    'event_type', 'sales_invoice',
    'sale_id', v_sale_id,
    'doc_no', v_doc_no,
    'items', v_item_ids,
    'journal_entry_id', v_journal_id,
    'cogs_journal_entry_id', v_cogs_journal_id,
    'total_cogs', v_total_cogs,
    'total_amount', v_total_amount,
    'paid_amount', v_paid_amount,
    'remaining_balance', v_remaining
  );

  v_event_id := public.log_erp_event(
    'sales_invoice',
    'sales',
    v_sale_id,
    p_payload,
    COALESCE(v_cogs_journal_id, v_journal_id),
    v_idempotency,
    v_result
  );

  v_result := v_result || jsonb_build_object('event_id', v_event_id);
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.production_record_furniture_receipt_from_order(p_order_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.production_orders%ROWTYPE;
  v_product_id UUID;
  v_product_code TEXT;
  v_product_name TEXT;
  v_product_unit TEXT;
  v_wh_id UUID;
  v_wh_name TEXT;
  v_items JSONB;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.warehouse_slips
    WHERE source_type = 'production'
      AND source_document_id = p_order_id
      AND type = 'inbound'
  ) THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_order
  FROM public.production_orders
  WHERE id = p_order_id;

  IF NOT FOUND OR v_order.type IS DISTINCT FROM 'Custom' THEN
    RETURN NULL;
  END IF;

  v_product_id := COALESCE(v_order.custom_product_id, v_order.finished_product_id);
  IF v_product_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT code, name, unit
  INTO v_product_code, v_product_name, v_product_unit
  FROM public.products
  WHERE id = v_product_id;

  v_wh_id := COALESCE(v_order.furniture_warehouse_id, v_order.warehouse_id);
  IF v_wh_id IS NOT NULL THEN
    SELECT name INTO v_wh_name FROM public.warehouses WHERE id = v_wh_id;
  END IF;
  IF v_wh_name IS NULL THEN
    v_wh_name := v_order.warehouse_name;
  END IF;

  v_items := jsonb_build_array(
    jsonb_build_object(
      'product_id', v_product_id,
      'product_code', v_product_code,
      'product_name', v_product_name,
      'quantity', GREATEST(COALESCE(v_order.quantity, 1), 1),
      'unit', COALESCE(v_product_unit, 'Ədəd')
    )
  );

  RETURN public.create_production_warehouse_slip(
    p_order_id,
    'inbound',
    v_wh_id,
    v_wh_name,
    v_items,
    'Fərdi istehsal təhvil — ' || v_order.order_no
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.production_record_material_issue_slip(p_order_id uuid, p_material_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.production_orders%ROWTYPE;
  v_wh_id UUID;
  v_wh_name TEXT;
  v_items JSONB := '[]'::jsonb;
  v_material RECORD;
BEGIN
  SELECT * INTO v_order
  FROM public.production_orders
  WHERE id = p_order_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_wh_id := COALESCE(v_order.raw_material_warehouse_id, v_order.warehouse_id);
  v_wh_name := v_order.warehouse_name;
  IF v_wh_id IS NOT NULL THEN
    SELECT name INTO v_wh_name FROM public.warehouses WHERE id = v_wh_id;
  END IF;

  FOR v_material IN
    SELECT pm.id, pm.product_id, pm.product_code, pm.product_name, pm.quantity, pm.unit
    FROM public.production_materials pm
    WHERE pm.production_order_id = p_order_id
      AND pm.issued = true
      AND pm.product_id IS NOT NULL
      AND (
        p_material_ids IS NULL
        OR cardinality(p_material_ids) = 0
        OR pm.id = ANY(p_material_ids)
      )
  LOOP
    v_items := v_items || jsonb_build_array(
      jsonb_build_object(
        'product_id', v_material.product_id,
        'product_code', v_material.product_code,
        'product_name', v_material.product_name,
        'quantity', v_material.quantity,
        'unit', COALESCE(v_material.unit, 'Ədəd')
      )
    );
  END LOOP;

  IF jsonb_array_length(v_items) = 0 THEN
    RETURN NULL;
  END IF;

  RETURN public.create_production_warehouse_slip(
    p_order_id,
    'outbound',
    v_wh_id,
    v_wh_name,
    v_items,
    'Material verilməsi — ' || v_order.order_no
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.purchases_default_posted_when_blank()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IS NULL OR btrim(NEW.status) = '' THEN
    NEW.status := 'posted';
  END IF;
  IF NEW.payments IS NULL THEN
    NEW.payments := '[]'::jsonb;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_expired_audit_logs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg JSONB;
  v_days INT;
  v_count INT := 0;
BEGIN
  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'audit_config';

  v_days := COALESCE((v_cfg ->> 'log_retention_days')::int, 0);
  IF v_days IS NULL OR v_days <= 0 THEN
    RETURN 0;
  END IF;

  DELETE FROM public.audit_alerts
   WHERE created_at < NOW() - make_interval(days => v_days);

  DELETE FROM public.audit_logs
   WHERE created_at < NOW() - make_interval(days => v_days);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_account_balance_atomic(p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row RECORD;
  v_ledger NUMERIC;
  v_previous NUMERIC;
  v_fixed INT := 0;
  v_results JSONB := '[]'::jsonb;
BEGIN
  IF NOT (
    public.require_permission('can_manage_finance')
    OR public.require_permission('can_manage_settings')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Balans uyğunlaşdırması üçün icazəniz yoxdur';
  END IF;

  FOR v_row IN
    SELECT id, balance, name, code
    FROM accounts
    WHERE p_account_id IS NULL OR id = p_account_id
    ORDER BY name
  LOOP
    SELECT COALESCE(SUM(
      CASE
        WHEN type = 'Mədaxil' THEN amount
        WHEN type = 'Məxaric' THEN -amount
        ELSE 0
      END
    ), 0)
    INTO v_ledger
    FROM transactions
    WHERE account_id = v_row.id;

    v_previous := COALESCE(v_row.balance, 0);

    UPDATE accounts
    SET balance = COALESCE(v_ledger, 0)
    WHERE id = v_row.id;

    IF abs(v_previous - COALESCE(v_ledger, 0)) > 0.0001 THEN
      v_fixed := v_fixed + 1;
    END IF;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'account_id', v_row.id,
        'account_name', v_row.name,
        'account_code', v_row.code,
        'previous_balance', v_previous,
        'ledger_balance', COALESCE(v_ledger, 0),
        'adjusted', abs(v_previous - COALESCE(v_ledger, 0)) > 0.0001
      )
    );
  END LOOP;

  IF p_account_id IS NOT NULL AND v_fixed = 0 AND jsonb_array_length(v_results) = 0 THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hesab tapılmadı';
  END IF;

  RETURN jsonb_build_object(
    'accounts_checked', jsonb_array_length(v_results),
    'accounts_adjusted', v_fixed,
    'results', v_results
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_accounts_for_transactions(p_account_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id UUID;
BEGIN
  IF p_account_ids IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_account_id IN ARRAY p_account_ids
  LOOP
    IF v_account_id IS NOT NULL THEN
      PERFORM public.reconcile_account_balance_atomic(v_account_id);
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_customer_ar_balances(p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_customer RECORD;
  v_fixed INT := 0;
  v_results JSONB := '[]'::jsonb;
  v_before NUMERIC;
  v_after NUMERIC;
BEGIN
  IF NOT (
    public.require_permission('can_manage_finance')
    OR public.require_permission('can_edit_sales')
    OR public.require_permission('can_manage_settings')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Müştəri borc uyğunlaşdırması üçün icazəniz yoxdur';
  END IF;

  FOR v_customer IN
    SELECT id, balance, full_name, name, company_name, code
    FROM customers
    WHERE p_customer_id IS NULL OR id = p_customer_id
    ORDER BY full_name NULLS LAST, name NULLS LAST
  LOOP
    v_before := COALESCE(v_customer.balance, 0);
    v_after := public.refresh_customer_ar_balance(v_customer.id);

    IF abs(v_before - COALESCE(v_after, 0)) > 0.01 THEN
      v_fixed := v_fixed + 1;
    END IF;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'customer_id', v_customer.id,
        'customer_name', COALESCE(NULLIF(trim(v_customer.full_name), ''), NULLIF(trim(v_customer.name), ''), NULLIF(trim(v_customer.company_name), ''), v_customer.code, v_customer.id::text),
        'previous_balance', v_before,
        'ledger_balance', COALESCE(v_after, 0),
        'adjusted', abs(v_before - COALESCE(v_after, 0)) > 0.01
      )
    );
  END LOOP;

  IF p_customer_id IS NOT NULL AND jsonb_array_length(v_results) = 0 THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  RETURN jsonb_build_object(
    'customers_checked', jsonb_array_length(v_results),
    'customers_adjusted', v_fixed,
    'results', v_results
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.record_expense_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id          UUID := NULLIF(p_payload->>'id', '')::uuid;
  v_existing    public.expenses%ROWTYPE;
  v_date        DATE := COALESCE(NULLIF(p_payload->>'expense_date', '')::date, CURRENT_DATE);
  v_cat_id      UUID := NULLIF(p_payload->>'category_id', '')::uuid;
  v_mode        TEXT := COALESCE(NULLIF(trim(p_payload->>'payment_mode'), ''), 'company');
  v_employee    UUID := NULLIF(p_payload->>'employee_id', '')::uuid;
  v_account     UUID := NULLIF(p_payload->>'account_id', '')::uuid;
  v_vat_account UUID := NULLIF(p_payload->>'vat_account_id', '')::uuid;
  v_cat_label   TEXT;
  v_net         NUMERIC(14,2) := round(COALESCE(NULLIF(p_payload->>'net_amount', '')::numeric, 0), 2);
  v_vat_rate    NUMERIC(5,2)  := round(COALESCE(NULLIF(p_payload->>'vat_rate', '')::numeric, 0), 2);
  v_vat         NUMERIC(14,2);
  v_total       NUMERIC(14,2);
  v_post        BOOLEAN := COALESCE((p_payload->>'post')::boolean, false);
  v_submit      BOOLEAN := COALESCE((p_payload->>'submit')::boolean, false);
  v_code        TEXT;
  v_tx_id       UUID;
  v_status      TEXT;
BEGIN
  IF NOT public.require_permission('can_manage_expenses') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Xərc yazmaq üçün icazəniz yoxdur';
  END IF;

  IF v_mode NOT IN ('company', 'employee') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Ödəniş üsulu düzgün deyil';
  END IF;
  IF v_mode = 'employee' THEN
    IF v_employee IS NULL OR NOT EXISTS (SELECT 1 FROM public.employees WHERE id = v_employee) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Xərci ödəyən işçini seçin';
    END IF;
    IF v_post THEN
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = 'İşçinin ödədiyi xərc birbaşa ödənilmir — təsdiqə göndərin';
    END IF;
    v_account := NULL;
    v_vat_account := NULL;
  ELSE
    v_employee := NULL;
  END IF;

  IF v_net <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;
  IF v_vat_rate < 0 OR v_vat_rate > 100 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ƏDV dərəcəsi 0–100 arasında olmalıdır';
  END IF;
  v_vat := round(COALESCE(NULLIF(p_payload->>'vat_amount', '')::numeric, v_net * v_vat_rate / 100), 2);
  IF v_vat < 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ƏDV məbləği mənfi ola bilməz';
  END IF;
  v_total := v_net + v_vat;

  IF v_vat = 0 THEN
    v_vat_account := NULL;
  END IF;
  IF v_vat_account IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE id = v_vat_account) THEN
      RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'ƏDV hesabı tapılmadı';
    END IF;
    IF v_vat_account = v_account THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ƏDV hesabı əsas hesabdan fərqli olmalıdır';
    END IF;
  END IF;

  SELECT CASE WHEN p.name IS NOT NULL THEN p.name || ' / ' || c.name ELSE c.name END
  INTO v_cat_label
  FROM public.financial_categories c
  LEFT JOIN public.financial_categories p ON p.id = c.parent_id
  WHERE c.id = v_cat_id AND c.type = 'EXPENSE';
  IF v_cat_label IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Xərc kateqoriyası seçilməlidir';
  END IF;

  IF v_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.expenses WHERE id = v_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
    END IF;
    IF v_existing.status NOT IN ('draft', 'submitted') THEN
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = 'Təsdiqlənmiş xərc dəyişdirilə bilməz — əvvəlcə ləğv edin';
    END IF;

    UPDATE public.expenses
    SET expense_date        = v_date,
        category_id         = v_cat_id,
        category            = left(v_cat_label, 100),
        payment_mode        = v_mode,
        employee_id         = v_employee,
        account_id          = v_account,
        vat_account_id      = v_vat_account,
        supplier_id         = NULLIF(p_payload->>'supplier_id', '')::uuid,
        payee               = NULLIF(trim(p_payload->>'payee'), ''),
        reference_no        = NULLIF(trim(p_payload->>'reference_no'), ''),
        description         = NULLIF(trim(p_payload->>'description'), ''),
        notes               = NULLIF(trim(p_payload->>'notes'), ''),
        department_id       = NULLIF(p_payload->>'department_id', '')::uuid,
        production_order_id = NULLIF(p_payload->>'production_order_id', '')::uuid,
        net_amount          = v_net,
        vat_rate            = v_vat_rate,
        vat_amount          = v_vat,
        amount              = v_total,
        updated_at          = NOW()
    WHERE id = v_id;
    v_code := v_existing.code;
    v_status := v_existing.status;
  ELSE
    v_code := public.next_expense_doc_no(v_date);
    INSERT INTO public.expenses (
      code, expense_date, category_id, category, payment_mode, employee_id, account_id, vat_account_id,
      supplier_id, payee, reference_no, description, notes, department_id, production_order_id,
      net_amount, vat_rate, vat_amount, amount, status, created_by
    )
    VALUES (
      v_code, v_date, v_cat_id, left(v_cat_label, 100), v_mode, v_employee, v_account, v_vat_account,
      NULLIF(p_payload->>'supplier_id', '')::uuid,
      NULLIF(trim(p_payload->>'payee'), ''),
      NULLIF(trim(p_payload->>'reference_no'), ''),
      NULLIF(trim(p_payload->>'description'), ''),
      NULLIF(trim(p_payload->>'notes'), ''),
      NULLIF(p_payload->>'department_id', '')::uuid,
      NULLIF(p_payload->>'production_order_id', '')::uuid,
      v_net, v_vat_rate, v_vat, v_total, 'draft', auth.uid()
    )
    RETURNING id INTO v_id;
    v_status := 'draft';
  END IF;

  IF v_post THEN
    v_tx_id := public.post_expense_internal(v_id);
    v_status := 'posted';
  ELSIF v_submit AND v_status = 'draft' THEN
    UPDATE public.expenses
    SET status = 'submitted', submitted_at = NOW(), submitted_by = auth.uid(),
        rejected_at = NULL, rejected_by = NULL, rejected_reason = NULL, updated_at = NOW()
    WHERE id = v_id;
    v_status := 'submitted';
  END IF;

  RETURN jsonb_build_object('id', v_id, 'code', v_code, 'status', v_status, 'transaction_id', v_tx_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_payment_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_document_type TEXT;
  v_document_id UUID;
  v_amount NUMERIC;
  v_account_id UUID;
  v_method TEXT;
  v_notes TEXT;
  v_payment_id TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_debt_amount NUMERIC;
  v_new_paid NUMERIC;
  v_new_remaining NUMERIC;
  v_new_debt NUMERIC;
  v_customer_id UUID;
  v_supplier_id UUID;
  v_doc_label TEXT;
  v_account_balance NUMERIC;
  v_party_balance NUMERIC;
  v_payments JSONB;
  v_new_payment JSONB;
  v_status TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödəniş məlumatları göndərilməyib';
  END IF;

  v_document_type := lower(trim(COALESCE(p_payload->>'document_type', '')));
  v_document_id := NULLIF(p_payload->>'document_id', '')::uuid;
  v_amount := COALESCE(NULLIF(p_payload->>'amount', '')::numeric, 0);
  v_account_id := NULLIF(p_payload->>'account_id', '')::uuid;
  v_method := COALESCE(NULLIF(trim(p_payload->>'method'), ''), 'Ödəniş');
  v_notes := NULLIF(trim(p_payload->>'notes'), '');
  v_payment_id := COALESCE(NULLIF(trim(p_payload->>'payment_id'), ''), gen_random_uuid()::text);

  IF v_document_id IS NULL THEN
    RAISE EXCEPTION 'document_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd identifikatoru tələb olunur';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;

  PERFORM id FROM accounts WHERE id = v_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
  END IF;

  IF v_document_type = 'sale' THEN
    IF NOT public.require_permission('can_edit_sales') THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Satış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT
      total_amount,
      paid_amount,
      remaining_balance,
      customer_id,
      doc_no,
      payments
    INTO
      v_total_amount,
      v_paid_amount,
      v_remaining,
      v_customer_id,
      v_doc_label,
      v_payments
    FROM sales
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'sale_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Satış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_remaining := GREATEST(
      COALESCE(v_remaining, v_total_amount - v_paid_amount),
      0
    );

    IF v_amount > v_remaining + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_remaining, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_remaining := GREATEST(v_total_amount - v_new_paid, 0);

    v_new_payment := jsonb_build_object(
      'id', v_payment_id,
      'account_id', v_account_id::text,
      'method', v_method,
      'amount', v_amount
    );
    v_payments := COALESCE(v_payments, '[]'::jsonb) || jsonb_build_array(v_new_payment);

    UPDATE sales
    SET
      paid_amount = v_new_paid,
      remaining_balance = v_new_remaining,
      payments = v_payments
    WHERE id = v_document_id;

    SELECT balance INTO v_account_balance
    FROM accounts
    WHERE id = v_account_id
    FOR UPDATE;

    INSERT INTO transactions (account_id, type, amount, category, notes)
    VALUES (
      v_account_id,
      'Mədaxil',
      v_amount,
      'Satış Ödənişi',
      COALESCE(
        v_notes,
        format('Satış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)
      )
    );

    UPDATE accounts
    SET balance = COALESCE(v_account_balance, 0) + v_amount
    WHERE id = v_account_id;

    IF v_customer_id IS NOT NULL THEN
      SELECT balance INTO v_party_balance
      FROM customers
      WHERE id = v_customer_id
      FOR UPDATE;

      UPDATE customers
      SET balance = GREATEST(COALESCE(v_party_balance, 0) - v_amount, 0)
      WHERE id = v_customer_id;
    END IF;

    RETURN jsonb_build_object(
      'document_type', 'sale',
      'document_id', v_document_id,
      'paid_amount', v_new_paid,
      'remaining_balance', v_new_remaining
    );
  END IF;

  IF v_document_type = 'purchase' THEN
    IF NOT public.require_permission('can_edit_purchases') THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Alış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT
      total_amount,
      paid_amount,
      debt_amount,
      supplier_id,
      invoice_number
    INTO
      v_total_amount,
      v_paid_amount,
      v_debt_amount,
      v_supplier_id,
      v_doc_label
    FROM purchases
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Alış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_debt_amount := GREATEST(COALESCE(v_debt_amount, v_total_amount - v_paid_amount), 0);

    IF v_amount > v_debt_amount + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_debt_amount, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_debt := GREATEST(v_total_amount - v_new_paid, 0);
    v_status := CASE WHEN v_new_debt > 0.0001 THEN 'Borclu' ELSE 'Ödənilib' END;

    UPDATE purchases
    SET
      paid_amount = v_new_paid,
      debt_amount = v_new_debt,
      status = v_status
    WHERE id = v_document_id;

    SELECT balance INTO v_account_balance
    FROM accounts
    WHERE id = v_account_id
    FOR UPDATE;

    INSERT INTO transactions (account_id, type, amount, category, notes)
    VALUES (
      v_account_id,
      'Məxaric',
      v_amount,
      'Alış Ödənişi',
      COALESCE(
        v_notes,
        format('Alış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)
      )
    );

    UPDATE accounts
    SET balance = COALESCE(v_account_balance, 0) - v_amount
    WHERE id = v_account_id;

    IF v_supplier_id IS NOT NULL THEN
      SELECT balance INTO v_party_balance
      FROM suppliers
      WHERE id = v_supplier_id
      FOR UPDATE;

      UPDATE suppliers
      SET balance = GREATEST(COALESCE(v_party_balance, 0) - v_amount, 0)
      WHERE id = v_supplier_id;
    END IF;

    RETURN jsonb_build_object(
      'document_type', 'purchase',
      'document_id', v_document_id,
      'paid_amount', v_new_paid,
      'debt_amount', v_new_debt,
      'status', v_status
    );
  END IF;

  RAISE EXCEPTION 'invalid_document_type'
    USING ERRCODE = '22023',
          MESSAGE = 'document_type «sale» və ya «purchase» olmalıdır';
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_customer_ar_balance(p_customer_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open_ar NUMERIC;
BEGIN
  IF p_customer_id IS NULL THEN
    RETURN 0;
  END IF;

  v_open_ar := public.compute_customer_open_ar(p_customer_id);

  UPDATE customers
  SET balance = COALESCE(v_open_ar, 0)
  WHERE id = p_customer_id;

  RETURN COALESCE(v_open_ar, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_partner_linked_balances(p_partner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner public.partners%ROWTYPE;
BEGIN
  SELECT * INTO v_partner
  FROM public.partners
  WHERE id = p_partner_id AND is_deleted = FALSE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_partner.customer_id IS NOT NULL THEN
    PERFORM public.refresh_customer_ar_balance(v_partner.customer_id);
  END IF;

  IF v_partner.supplier_id IS NOT NULL THEN
    PERFORM public.refresh_supplier_ap_balance(v_partner.supplier_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_supplier_ap_balance(p_supplier_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open_ap NUMERIC;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN 0;
  END IF;

  v_open_ap := public.compute_supplier_open_ap(p_supplier_id);

  UPDATE public.suppliers
  SET balance = COALESCE(v_open_ap, 0)
  WHERE id = p_supplier_id;

  RETURN COALESCE(v_open_ap, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.reimburse_expense_atomic(p_expense_id uuid, p_account_id uuid, p_pay_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp     public.expenses%ROWTYPE;
  v_date    DATE := COALESCE(p_pay_date, CURRENT_DATE);
  v_tx_id   UUID;
  v_journal UUID;
  v_memo    TEXT;
BEGIN
  IF NOT public.require_permission('can_manage_finance') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Kompensasiya ödəmək üçün icazəniz yoxdur';
  END IF;
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
  END IF;
  IF v_exp.payment_mode <> 'employee' OR v_exp.status <> 'approved' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Yalnız təsdiqlənmiş işçi xərci üçün kompensasiya ödənilir';
  END IF;
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;
  IF v_date < v_exp.expense_date THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Ödəniş tarixi xərc tarixindən əvvəl ola bilməz';
  END IF;
  PERFORM public.assert_expense_date_postable(v_date);

  v_memo := 'Kompensasiya: ' || public.expense_memo(v_exp.id);
  v_tx_id := public.expense_cash_out(v_exp.id, p_account_id, v_exp.amount, v_date, v_memo);

  v_journal := public.post_journal_entry(jsonb_build_object(
    'source_type', 'expense',
    'source_id', v_exp.id,
    'document_type', 'expense',
    'document_id', v_exp.id,
    'idempotency_key', 'expense-reimburse:' || v_exp.id::text,
    'entry_date', v_date,
    'memo', v_memo,
    'lines', jsonb_build_array(
      jsonb_build_object('coa_code', '2400', 'debit', v_exp.amount, 'credit', 0,
                         'partner_type', 'employee', 'partner_id', v_exp.employee_id, 'line_memo', v_memo),
      jsonb_build_object('coa_code', '1100', 'debit', 0, 'credit', v_exp.amount,
                         'account_id', p_account_id, 'line_memo', v_memo)
    )
  ));

  UPDATE public.transactions SET journal_entry_id = v_journal WHERE id = v_tx_id;

  UPDATE public.expenses
  SET status = 'posted', account_id = p_account_id, transaction_id = v_tx_id,
      reimbursement_journal_id = v_journal, reimbursed_at = NOW(), reimbursed_by = auth.uid(),
      posted_at = NOW(), posted_by = auth.uid(), updated_at = NOW()
  WHERE id = v_exp.id;

  RETURN v_tx_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_expense_atomic(p_expense_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp public.expenses%ROWTYPE;
BEGIN
  IF NOT public.require_permission('can_manage_finance') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Xərci geri qaytarmaq üçün icazəniz yoxdur';
  END IF;
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
  END IF;
  IF v_exp.status <> 'submitted' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Yalnız təsdiq gözləyən xərc geri qaytarıla bilər';
  END IF;
  UPDATE public.expenses
  SET status = 'draft', rejected_at = NOW(), rejected_by = auth.uid(),
      rejected_reason = COALESCE(NULLIF(trim(p_reason), ''), 'Geri qaytarıldı'), updated_at = NOW()
  WHERE id = p_expense_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_financial_category_id(p_name text, p_type text DEFAULT 'EXPENSE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
  v_name TEXT := COALESCE(NULLIF(trim(p_name), ''), 'Digər');
  v_type TEXT := upper(COALESCE(NULLIF(trim(p_type), ''), 'EXPENSE'));
BEGIN
  SELECT id INTO v_id
  FROM financial_categories
  WHERE lower(name) = lower(v_name) AND type = v_type AND is_active = true
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO financial_categories (name, type, is_active)
  VALUES (v_name, v_type, true)
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM financial_categories
    WHERE lower(name) = lower(v_name) AND type = v_type
    LIMIT 1;
  END IF;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.restore_sale_stock(p_sale_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_qty NUMERIC;
  v_restored INT := 0;
BEGIN
  FOR v_item IN
    SELECT product_id, quantity, polywood_sale_mode
    FROM sale_items
    WHERE sale_id = p_sale_id
  LOOP
    IF v_item.product_id IS NULL THEN
      CONTINUE;
    END IF;
    IF NULLIF(trim(COALESCE(v_item.polywood_sale_mode, '')), '') IS NOT NULL THEN
      CONTINUE;
    END IF;

    v_qty := COALESCE(v_item.quantity, 0);
    IF v_qty <= 0 THEN
      CONTINUE;
    END IF;

    UPDATE products
    SET stock = COALESCE(stock, 0) + v_qty
    WHERE id = v_item.product_id;

    v_restored := v_restored + 1;
  END LOOP;

  RETURN v_restored;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_document_cash_transactions(p_source_type text, p_source_id uuid, p_doc_label text, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r          RECORD;
  v_balance  NUMERIC;
  v_is_in    BOOLEAN;
  v_journal  UUID;
  v_count    INTEGER := 0;
BEGIN
  FOR r IN
    SELECT t.*
    FROM public.transactions t
    WHERE (
        (t.source_type = p_source_type AND t.source_id = p_source_id)
        -- Rows written before source linkage existed carry the number in notes.
        OR (t.source_type IS NULL AND t.source_id IS NULL
            AND NULLIF(trim(p_doc_label), '') IS NOT NULL
            AND t.notes ILIKE '%' || trim(p_doc_label) || '%')
      )
      AND COALESCE(t.reference_type, '') <> 'storno'
      AND NOT EXISTS (
        SELECT 1 FROM public.transactions s
        WHERE s.reference_type = 'storno' AND s.reference_id = t.id
      )
    ORDER BY t.created_at, t.id
    FOR UPDATE OF t
  LOOP
    IF r.account_id IS NULL OR COALESCE(r.amount, 0) <= 0 THEN
      CONTINUE;
    END IF;

    v_is_in := r.type LIKE 'M%daxil';

    SELECT balance INTO v_balance
    FROM public.accounts
    WHERE id = r.account_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0002',
        MESSAGE = format('%s: ödənişin kassa/bank hesabı tapılmadı', p_doc_label);
    END IF;

    -- Money received is paid back out of the same kassa/bank.
    IF v_is_in AND COALESCE(v_balance, 0) + 0.0001 < r.amount THEN
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = format(
          '%s: geri qaytarmaq üçün kassa/bank balansı kifayət etmir (lazım: %s, mövcud: %s)',
          p_doc_label,
          trim(to_char(r.amount, 'FM999999990.00')),
          trim(to_char(COALESCE(v_balance, 0), 'FM999999990.00'))
        );
    END IF;

    UPDATE public.accounts
    SET balance = COALESCE(balance, 0) + CASE WHEN v_is_in THEN -r.amount ELSE r.amount END
    WHERE id = r.account_id;

    v_journal := NULL;
    IF r.journal_entry_id IS NOT NULL THEN
      v_journal := public.reverse_journal_entry(r.journal_entry_id, p_reason);
    END IF;

    INSERT INTO public.transactions (
      account_id, type, amount, category, notes,
      source_type, source_id, reference_type, reference_id, journal_entry_id
    )
    VALUES (
      r.account_id,
      CASE WHEN v_is_in THEN 'Məxaric' ELSE 'Mədaxil' END,
      r.amount,
      COALESCE(r.category, 'Digər') || ' (storno)',
      format('STORNO: %s — %s', COALESCE(r.notes, p_doc_label), p_reason),
      r.source_type,
      r.source_id,
      'storno',
      r.id,
      v_journal
    );

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_document_journals(p_document_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r     RECORD;
  v_cnt INTEGER := 0;
BEGIN
  FOR r IN
    SELECT id FROM public.journal_entries
    WHERE COALESCE(document_id, source_id) = p_document_id
      AND reversal_of IS NULL
      AND reversed_by IS NULL
  LOOP
    PERFORM public.reverse_journal_entry(r.id, p_reason);
    v_cnt := v_cnt + 1;
  END LOOP;
  RETURN v_cnt;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_entry_id uuid, p_reason text DEFAULT NULL::text, p_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_src    RECORD;
  v_new_id UUID;
  v_date   DATE;
BEGIN
  SELECT * INTO v_src FROM public.journal_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entry_not_found'
      USING ERRCODE = 'P0002', MESSAGE = 'Müxabirləşmə tapılmadı';
  END IF;

  IF v_src.reversed_by IS NOT NULL THEN
    RETURN v_src.reversed_by;           -- idempotent
  END IF;

  IF v_src.reversal_of IS NOT NULL THEN
    RAISE EXCEPTION 'already_a_reversal'
      USING ERRCODE = '22023', MESSAGE = 'Storno sənədi yenidən stornolana bilməz';
  END IF;

  -- Reverse into the original period when it is open, otherwise today.
  v_date := COALESCE(p_date, v_src.entry_date, CURRENT_DATE);
  IF public.is_accounting_period_closed(v_date) THEN
    v_date := CURRENT_DATE;
  END IF;

  INSERT INTO public.journal_entries (
    entry_no, entry_date, date, source_type, source_id,
    document_type, document_id, memo, description,
    idempotency_key, reversal_of, reversal_reason, created_by
  )
  VALUES (
    'STORNO-' || v_src.entry_no,
    v_date,
    v_date::timestamptz,
    v_src.source_type,
    v_src.source_id,
    v_src.document_type,
    v_src.document_id,
    'STORNO: ' || COALESCE(v_src.memo, v_src.entry_no),
    COALESCE(p_reason, 'Storno: ' || COALESCE(v_src.description, v_src.entry_no)),
    'storno:' || p_entry_id::text,
    p_entry_id,
    p_reason,
    auth.uid()
  )
  RETURNING id INTO v_new_id;

  -- Swap debit and credit, keep account and analytics.
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, coa_id, debit, credit, partner_type, partner_id, account_id, line_memo
  )
  SELECT v_new_id, l.coa_id, l.credit, l.debit, l.partner_type, l.partner_id, l.account_id,
         'STORNO: ' || COALESCE(l.line_memo, '')
  FROM public.journal_entry_lines l
  WHERE l.journal_entry_id = p_entry_id;

  UPDATE public.journal_entries SET reversed_by = v_new_id WHERE id = p_entry_id;

  RETURN v_new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_orphaned_document_journals(p_reason text DEFAULT 'Sənədi silinmiş müxabirləşmənin stornosu'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r     RECORD;
  v_cnt INTEGER := 0;
BEGIN
  FOR r IN SELECT id FROM public.gl_orphaned_document_entries LOOP
    PERFORM public.reverse_journal_entry(r.id, p_reason);
    v_cnt := v_cnt + 1;
  END LOOP;
  RETURN v_cnt;
END;
$function$

CREATE OR REPLACE FUNCTION public.revert_purchase_stock(p_purchase_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_qty NUMERIC;
  v_stock NUMERIC;
  v_reverted INT := 0;
BEGIN
  FOR v_item IN
    SELECT product_id, quantity
    FROM purchase_items
    WHERE purchase_id = p_purchase_id
  LOOP
    IF v_item.product_id IS NULL THEN
      CONTINUE;
    END IF;

    v_qty := COALESCE(v_item.quantity, 0);
    IF v_qty <= 0 THEN
      CONTINUE;
    END IF;

    SELECT stock INTO v_stock
    FROM products
    WHERE id = v_item.product_id
    FOR UPDATE;

    UPDATE products
    SET stock = GREATEST(COALESCE(v_stock, 0) - v_qty, 0)
    WHERE id = v_item.product_id;

    v_reverted := v_reverted + 1;
  END LOOP;

  RETURN v_reverted;
END;
$function$

CREATE OR REPLACE FUNCTION public.rollback_mixed_dimensional_sale(p_sale_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_details JSONB;
  v_step JSONB;
  v_scrap_id TEXT;
BEGIN
  SELECT polywood_cut_details INTO v_details FROM sale_items WHERE id = p_sale_item_id;
  IF v_details IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'noop', true);
  END IF;

  FOR v_scrap_id IN SELECT jsonb_array_elements(v_details -> 'scrap_created') ->> 'piece_id'
  LOOP
    DELETE FROM polywood_pieces WHERE id = v_scrap_id::uuid;
  END LOOP;

  FOR v_step IN SELECT * FROM jsonb_array_elements(v_details -> 'steps')
  LOOP
    IF v_step ->> 'action' IN ('consume', 'split_full') THEN
      UPDATE polywood_pieces
      SET status = 'available', sale_item_id = NULL, updated_at = NOW()
      WHERE id = (v_step ->> 'piece_id')::uuid;
    ELSIF v_step ->> 'action' = 'partial' THEN
      UPDATE polywood_pieces
      SET length_m = length_m + COALESCE((v_step ->> 'used_length')::numeric, 0),
          updated_at = NOW()
      WHERE id = (v_step ->> 'piece_id')::uuid;
    END IF;
  END LOOP;

  UPDATE sale_items SET polywood_cut_details = NULL WHERE id = p_sale_item_id;

  RETURN jsonb_build_object('ok', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.sales_default_posted_when_blank()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IS NULL OR btrim(NEW.status) = '' THEN
    NEW.status := 'posted';
  END IF;
  IF NEW.payment_type IS NULL OR btrim(NEW.payment_type) = '' THEN
    NEW.payment_type := 'cash';
  END IF;
  IF NEW.currency IS NULL OR btrim(NEW.currency) = '' THEN
    NEW.currency := 'AZN';
  END IF;
  IF NEW.exchange_rate IS NULL OR NEW.exchange_rate <= 0 THEN
    NEW.exchange_rate := 1;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_count_progress(p_count_id uuid, p_lines jsonb, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor   UUID := COALESCE(auth.uid(), p_actor);
  v_doc     public.inventory_counts;
  v_item    JSONB;
  v_line_id UUID;
  v_kind    TEXT;
  v_qty     NUMERIC;
  v_full    INTEGER;
  v_cuts    JSONB;
  v_cleared BOOLEAN;
  v_rows    INTEGER;
  v_ids     UUID[] := '{}';
BEGIN
  PERFORM public._inventory_count_authorize('can_writeoff_inventory');
  v_doc := public._inventory_count_lock(p_count_id, ARRAY['in_progress']);

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION '%', 'Sətirlər massiv olmalıdır' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    v_line_id := NULLIF(v_item->>'line_id', '')::uuid;
    v_kind := v_item->>'kind';

    IF v_kind = 'qty' THEN
      v_qty := NULLIF(v_item->>'actual_qty', '')::numeric;
      IF v_qty IS NOT NULL AND v_qty < 0 THEN
        RAISE EXCEPTION '%', 'Miqdar mənfi ola bilməz' USING ERRCODE = '22023';
      END IF;

      UPDATE public.inventory_count_items
      SET actual_qty = v_qty,
          counted_at = CASE WHEN v_qty IS NULL THEN NULL ELSE NOW() END,
          counted_by = CASE WHEN v_qty IS NULL THEN NULL ELSE v_actor END
      WHERE id = v_line_id AND count_id = v_doc.id AND NOT is_metric;

    ELSIF v_kind = 'pieces' THEN
      v_full := NULLIF(v_item->>'full_sheets', '')::integer;
      IF v_full IS NOT NULL AND v_full < 0 THEN
        RAISE EXCEPTION '%', 'Tam vərəq sayı mənfi ola bilməz' USING ERRCODE = '22023';
      END IF;

      SELECT COALESCE(jsonb_agg(ROUND(value::numeric, 3) ORDER BY ordinality), '[]'::jsonb)
      INTO v_cuts
      FROM jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(v_item->'cut_pieces') = 'array' THEN v_item->'cut_pieces' ELSE '[]'::jsonb END
      ) WITH ORDINALITY
      WHERE value::numeric > 0;

      v_cleared := v_full IS NULL AND jsonb_array_length(v_cuts) = 0;

      UPDATE public.inventory_count_items
      SET actual_full_sheets = CASE WHEN v_cleared THEN NULL ELSE COALESCE(v_full, 0) END,
          actual_cut_pieces  = CASE WHEN v_cleared THEN NULL ELSE v_cuts END,
          scanned_piece_ids  = CASE WHEN v_cleared THEN '[]'::jsonb ELSE scanned_piece_ids END,
          counted_at = CASE WHEN v_cleared THEN NULL ELSE NOW() END,
          counted_by = CASE WHEN v_cleared THEN NULL ELSE v_actor END
      WHERE id = v_line_id AND count_id = v_doc.id AND is_metric;

    ELSE
      RAISE EXCEPTION '%', format('Naməlum sətir növü: %s', COALESCE(v_kind, 'null')) USING ERRCODE = '22023';
    END IF;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
      RAISE EXCEPTION '%', 'Sayım sətri tapılmadı' USING ERRCODE = 'P0002';
    END IF;
    v_ids := v_ids || v_line_id;
  END LOOP;

  PERFORM public.inventory_count_refresh_totals(v_doc.id);

  RETURN COALESCE(
    (SELECT jsonb_agg(to_jsonb(i)) FROM public.inventory_count_items i WHERE i.id = ANY (v_ids)),
    '[]'::jsonb
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.save_purchase_invoice_draft(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_header JSONB;
  v_items JSONB;
  v_payments JSONB;
  v_add_exp JSONB;
  v_purchase_id UUID;
  v_invoice_number TEXT;
  v_supplier_id UUID;
  v_item JSONB;
  v_status TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Alış draft payload göndərilməyib';
  END IF;

  IF NOT (
    public.require_permission('can_edit_purchases')
    OR public.require_permission('can_create_purchase')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Alış yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_header := COALESCE(p_payload->'header', '{}'::jsonb);
  v_items := COALESCE(p_payload->'items', '[]'::jsonb);
  v_payments := COALESCE(p_payload->'payments', '[]'::jsonb);
  v_add_exp := COALESCE(p_payload->'additional_expenses', '[]'::jsonb);
  v_purchase_id := NULLIF(p_payload->>'purchase_id', '')::uuid;
  IF v_purchase_id IS NULL THEN
    v_purchase_id := NULLIF(v_header->>'id', '')::uuid;
  END IF;

  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Ən azı bir məhsul tələb olunur';
  END IF;

  v_supplier_id := NULLIF(v_header->>'supplier_id', '')::uuid;
  IF v_supplier_id IS NULL THEN
    RAISE EXCEPTION 'supplier_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Təchizatçı seçilməlidir';
  END IF;

  PERFORM id FROM suppliers WHERE id = v_supplier_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Təchizatçı tapılmadı';
  END IF;

  IF v_purchase_id IS NOT NULL THEN
    SELECT status, invoice_number INTO v_status, v_invoice_number
    FROM purchases
    WHERE id = v_purchase_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Alış sənədi tapılmadı';
    END IF;

    IF v_status = 'posted' THEN
      RAISE EXCEPTION 'already_posted'
        USING ERRCODE = '22023',
              MESSAGE = 'Təsdiqlənmiş sənəd redaktə edilə bilməz';
    END IF;

    IF v_status IN ('cancelled', 'void', 'voided') THEN
      RAISE EXCEPTION 'cancelled_document'
        USING ERRCODE = '22023',
              MESSAGE = 'Ləğv edilmiş sənəd redaktə edilə bilməz';
    END IF;
  ELSE
    v_invoice_number := NULLIF(trim(v_header->>'invoice_number'), '');
    IF v_invoice_number IS NULL OR v_invoice_number ~ '\.{3,}$' THEN
      v_invoice_number := public.next_purchase_doc_no('AS');
    END IF;
  END IF;

  IF v_purchase_id IS NULL THEN
    INSERT INTO purchases (
      invoice_number, supplier_id, warehouse_id, doc_date, responsible_id, responsible_name,
      total_amount, paid_amount, debt_amount, status, notes, due_date,
      additional_expenses, additional_expenses_total, payments,
      is_official, contract_id, vat_mode, subtotal_amount, vat_rate, vat_amount, grand_total
    )
    VALUES (
      v_invoice_number,
      v_supplier_id,
      NULLIF(v_header->>'warehouse_id', '')::uuid,
      COALESCE(NULLIF(v_header->>'doc_date', '')::date, CURRENT_DATE),
      NULLIF(v_header->>'responsible_id', '')::uuid,
      NULLIF(trim(v_header->>'responsible_name'), ''),
      COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0),
      COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0),
      GREATEST(COALESCE(NULLIF(v_header->>'debt_amount', '')::numeric, 0), 0),
      'draft',
      NULLIF(trim(v_header->>'notes'), ''),
      NULLIF(v_header->>'due_date', '')::date,
      v_add_exp,
      COALESCE(NULLIF(v_header->>'additional_expenses_total', '')::numeric, 0),
      v_payments,
      COALESCE((v_header->>'is_official')::boolean, false),
      NULLIF(v_header->>'contract_id', '')::uuid,
      COALESCE(NULLIF(trim(v_header->>'vat_mode'), ''), 'none'),
      NULLIF(v_header->>'subtotal_amount', '')::numeric,
      COALESCE(NULLIF(v_header->>'vat_rate', '')::numeric, 18),
      COALESCE(NULLIF(v_header->>'vat_amount', '')::numeric, 0),
      NULLIF(v_header->>'grand_total', '')::numeric
    )
    RETURNING id INTO v_purchase_id;
  ELSE
    UPDATE purchases SET
      supplier_id = v_supplier_id,
      warehouse_id = NULLIF(v_header->>'warehouse_id', '')::uuid,
      doc_date = COALESCE(NULLIF(v_header->>'doc_date', '')::date, doc_date),
      responsible_id = NULLIF(v_header->>'responsible_id', '')::uuid,
      responsible_name = NULLIF(trim(v_header->>'responsible_name'), ''),
      total_amount = COALESCE(NULLIF(v_header->>'total_amount', '')::numeric, 0),
      paid_amount = COALESCE(NULLIF(v_header->>'paid_amount', '')::numeric, 0),
      debt_amount = GREATEST(COALESCE(NULLIF(v_header->>'debt_amount', '')::numeric, 0), 0),
      status = 'draft',
      notes = NULLIF(trim(v_header->>'notes'), ''),
      due_date = NULLIF(v_header->>'due_date', '')::date,
      additional_expenses = v_add_exp,
      additional_expenses_total = COALESCE(NULLIF(v_header->>'additional_expenses_total', '')::numeric, 0),
      payments = v_payments,
      is_official = COALESCE((v_header->>'is_official')::boolean, is_official),
      contract_id = NULLIF(v_header->>'contract_id', '')::uuid,
      vat_mode = COALESCE(NULLIF(trim(v_header->>'vat_mode'), ''), vat_mode, 'none'),
      subtotal_amount = NULLIF(v_header->>'subtotal_amount', '')::numeric,
      vat_rate = COALESCE(NULLIF(v_header->>'vat_rate', '')::numeric, vat_rate, 18),
      vat_amount = COALESCE(NULLIF(v_header->>'vat_amount', '')::numeric, 0),
      grand_total = NULLIF(v_header->>'grand_total', '')::numeric
    WHERE id = v_purchase_id;

    DELETE FROM purchase_items WHERE purchase_id = v_purchase_id;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    INSERT INTO purchase_items (
      purchase_id, product_id, product_code, product_name, quantity, unit, unit_price, total_price
    )
    VALUES (
      v_purchase_id,
      NULLIF(v_item->>'product_id', '')::uuid,
      NULLIF(trim(v_item->>'product_code'), ''),
      NULLIF(trim(v_item->>'product_name'), ''),
      COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0),
      COALESCE(NULLIF(trim(v_item->>'unit'), ''), 'Ədəd'),
      COALESCE(NULLIF(v_item->>'unit_price', '')::numeric, 0),
      COALESCE(
        NULLIF(v_item->>'total_price', '')::numeric,
        NULLIF(v_item->>'total', '')::numeric,
        0
      )
    );
  END LOOP;

  SELECT invoice_number INTO v_invoice_number FROM purchases WHERE id = v_purchase_id;

  RETURN jsonb_build_object(
    'success', true,
    'event_type', 'purchase_invoice_draft',
    'purchase_id', v_purchase_id,
    'invoice_number', v_invoice_number,
    'status', 'draft'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_account_opening_balance_atomic(p_account_id uuid, p_target_balance numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target NUMERIC;
  v_ledger NUMERIC;
  v_delta NUMERIC;
  v_name TEXT;
  v_code TEXT;
BEGIN
  IF NOT (
    public.require_permission('can_manage_settings')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'İlkin qalıq yeniləmək üçün icazəniz yoxdur';
  END IF;

  IF p_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Hesab identifikatoru tələb olunur';
  END IF;

  v_target := GREATEST(COALESCE(p_target_balance, 0), 0);

  SELECT name, code INTO v_name, v_code
  FROM accounts
  WHERE id = p_account_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hesab tapılmadı';
  END IF;

  DELETE FROM transactions
  WHERE account_id = p_account_id
    AND category = 'İlkin Qalıq';

  SELECT COALESCE(SUM(
    CASE
      WHEN type = 'Mədaxil' THEN amount
      WHEN type = 'Məxaric' THEN -amount
      ELSE 0
    END
  ), 0)
  INTO v_ledger
  FROM transactions
  WHERE account_id = p_account_id;

  v_delta := v_target - COALESCE(v_ledger, 0);

  IF v_delta > 0.0001 THEN
    PERFORM public.post_cash_transaction(
      p_account_id,
      'Mədaxil',
      v_delta,
      'İlkin Qalıq',
      format('İlkin qalıq tənzimləməsi — %s (%s)', v_name, v_code)
    );
  ELSIF v_delta < -0.0001 THEN
    PERFORM public.post_cash_transaction(
      p_account_id,
      'Məxaric',
      ABS(v_delta),
      'İlkin Qalıq',
      format('İlkin qalıq tənzimləməsi (azaldılma) — %s (%s)', v_name, v_code)
    );
  END IF;

  PERFORM public.reconcile_account_balance_atomic(p_account_id);

  RETURN jsonb_build_object(
    'account_id', p_account_id,
    'target_balance', v_target,
    'ledger_balance', (
      SELECT balance FROM accounts WHERE id = p_account_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_consignment_initial_balance_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID := NULLIF(p_payload->>'partner_id', '')::uuid;
  v_balance_date DATE := COALESCE(NULLIF(p_payload->>'balance_date', '')::date, CURRENT_DATE);
  v_notes TEXT := NULLIF(btrim(p_payload->>'notes'), '');
  v_dispatch_no TEXT := NULLIF(btrim(p_payload->>'dispatch_no'), '');
  v_items JSONB := COALESCE(p_payload->'items', '[]'::jsonb);
  v_item JSONB;
  v_product_id UUID;
  v_quantity NUMERIC;
  v_unit_price NUMERIC;
  v_product_name TEXT;
  v_dispatch_id UUID;
  v_balance_ts TIMESTAMPTZ;
  v_inv_id UUID;
  v_delivered NUMERIC;
  v_sold NUMERIC;
  v_returned NUMERIC;
  v_partner_name TEXT;
  v_result JSONB;
  v_created_by UUID := NULLIF(p_payload->>'created_by', '')::uuid;
BEGIN
  -- Permission is checked in JS (requirePermissionAction) before this RPC is
  -- called via the service-role admin client - see create_consignment_dispatch_atomic.

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'partner_required' USING ERRCODE = '22023', MESSAGE = 'Tərəfdaş seçin';
  END IF;
  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'items_required' USING ERRCODE = '22023', MESSAGE = 'Ən azı bir məhsul əlavə edin';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
    v_quantity := COALESCE((v_item->>'quantity')::numeric, 0);
    IF v_product_id IS NULL OR v_quantity <= 0 THEN
      RAISE EXCEPTION 'invalid_item' USING ERRCODE = '22023', MESSAGE = 'Sətirdə məhsul və ya miqdar yanlışdır';
    END IF;

    SELECT name INTO v_product_name FROM public.products WHERE id = v_product_id;
    IF v_product_name IS NULL THEN
      RAISE EXCEPTION 'product_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Məhsul tapılmadı';
    END IF;
  END LOOP;

  IF v_dispatch_no IS NULL THEN
    v_dispatch_no := 'IB-' || EXTRACT(YEAR FROM v_balance_date)::text || '-' || floor(random() * 90000 + 10000)::int::text;
  END IF;

  -- Aging starts from the real-world balance date, not from today, so stock
  -- that has already been sitting with the partner for months shows up as
  -- aging immediately instead of resetting the clock on entry.
  v_balance_ts := v_balance_date::timestamptz;

  INSERT INTO public.consignment_dispatches (
    dispatch_no, partner_id, warehouse_id, warehouse_name, dispatch_date,
    status, items, notes, created_by
  )
  VALUES (
    v_dispatch_no, v_partner_id, NULL, NULL, v_balance_date,
    'initial_balance', v_items, v_notes, v_created_by
  )
  RETURNING id INTO v_dispatch_id;

  -- NOTE: no warehouse_stocks/products.stock adjustment and no stock_movements
  -- row here - that is the entire point of this RPC (see file header).
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_product_id := (v_item->>'product_id')::uuid;
    v_quantity := (v_item->>'quantity')::numeric;
    v_unit_price := COALESCE((v_item->>'unit_price')::numeric, 0);

    SELECT id, delivered_qty, sold_qty, returned_qty INTO v_inv_id, v_delivered, v_sold, v_returned
    FROM public.consignment_inventory
    WHERE partner_id = v_partner_id AND product_id = v_product_id
    FOR UPDATE;

    IF v_inv_id IS NOT NULL THEN
      v_delivered := COALESCE(v_delivered, 0) + v_quantity;
      UPDATE public.consignment_inventory
      SET delivered_qty = v_delivered,
          remaining_qty = GREATEST(0, v_delivered - COALESCE(v_sold, 0) - COALESCE(v_returned, 0)),
          unit_price = COALESCE(v_unit_price, unit_price),
          product_name = COALESCE(v_item->>'product_name', product_name),
          product_code = COALESCE(v_item->>'product_code', product_code),
          category = COALESCE(v_item->>'category', category),
          unit = COALESCE(v_item->>'unit', unit),
          last_dispatch_at = LEAST(COALESCE(last_dispatch_at, v_balance_ts), v_balance_ts),
          updated_at = NOW()
      WHERE id = v_inv_id;
    ELSE
      INSERT INTO public.consignment_inventory (
        partner_id, product_id, product_code, product_name, category, unit,
        delivered_qty, sold_qty, returned_qty, remaining_qty, unit_price,
        last_dispatch_at, updated_at
      )
      VALUES (
        v_partner_id, v_product_id, v_item->>'product_code', v_item->>'product_name',
        v_item->>'category', COALESCE(v_item->>'unit', 'Ədəd'),
        v_quantity, 0, 0, v_quantity, v_unit_price, v_balance_ts, NOW()
      );
    END IF;
  END LOOP;

  SELECT COALESCE(company_name, name) INTO v_partner_name
  FROM public.consignment_partners WHERE id = v_partner_id;

  SELECT to_jsonb(d) || jsonb_build_object('partner_name', v_partner_name)
  INTO v_result
  FROM public.consignment_dispatches d
  WHERE d.id = v_dispatch_id;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_customer_opening_balance_atomic(p_customer_id uuid, p_opening_balance numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old NUMERIC;
  v_new NUMERIC := GREATEST(COALESCE(p_opening_balance, 0), 0);
  v_delta NUMERIC;
BEGIN
  SELECT COALESCE(opening_balance, 0) INTO v_old
  FROM public.customers
  WHERE id = p_customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Müştəri tapılmadı';
  END IF;

  v_delta := v_new - v_old;

  UPDATE public.customers
  SET opening_balance = v_new
  WHERE id = p_customer_id;

  IF abs(v_delta) > 0.0001 THEN
    PERFORM public.create_journal_entry(jsonb_build_object(
      'document_type', 'customer_opening_balance',
      'document_id', p_customer_id,
      'description', 'Müştəri ilkin qalığı',
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_code', '1200',
          'debit', GREATEST(v_delta, 0),
          'credit', GREATEST(-v_delta, 0),
          'partner_type', 'customer',
          'partner_id', p_customer_id
        ),
        jsonb_build_object(
          'account_code', '3900',
          'debit', GREATEST(-v_delta, 0),
          'credit', GREATEST(v_delta, 0)
        )
      )
    ));
  END IF;

  RETURN public.refresh_customer_ar_balance(p_customer_id);
END;
$function$

