CREATE OR REPLACE FUNCTION public.settle_consignment_partner_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID := NULLIF(p_payload->>'partner_id', '')::uuid;
  v_period TEXT := p_payload->>'report_period';
  v_sales_rep_id UUID := NULLIF(p_payload->>'sales_rep_id', '')::uuid;
  v_sales_rep_name TEXT := NULLIF(p_payload->>'sales_rep_name', '');
  v_notes TEXT := NULLIF(btrim(p_payload->>'notes'), '');
  v_return_warehouse_id UUID := NULLIF(p_payload->>'return_warehouse_id', '')::uuid;
  v_report_no TEXT := NULLIF(btrim(p_payload->>'report_no'), '');
  v_lines JSONB := COALESCE(p_payload->'lines', '[]'::jsonb);
  v_line JSONB;
  v_product_id UUID;
  v_qty_sold NUMERIC;
  v_qty_returned NUMERIC;
  v_unit_price NUMERIC;
  v_inv RECORD;
  v_sold_items JSONB := '[]'::jsonb;
  v_returned_items JSONB := '[]'::jsonb;
  v_total_amount NUMERIC := 0;
  v_now TIMESTAMPTZ := NOW();
  v_partner RECORD;
  v_partner_name TEXT;
  v_sale_id UUID;
  v_invoice_no TEXT;
  v_journal_id UUID;
  v_report_id UUID;
  v_result JSONB;
  v_any_sold BOOLEAN := FALSE;
  v_any_returned BOOLEAN := FALSE;
  v_created_by UUID := NULLIF(p_payload->>'created_by', '')::uuid;
BEGIN
  -- Permission is checked in JS (requirePermissionAction) before this RPC is
  -- called via the service-role admin client - see create_consignment_dispatch_atomic.

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'partner_required' USING ERRCODE = '22023', MESSAGE = 'Tərəfdaş seçin';
  END IF;
  IF v_period IS NULL OR v_period !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'invalid_period' USING ERRCODE = '22023', MESSAGE = 'Dövr YYYY-MM formatında olmalıdır';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.consignment_monthly_reports
    WHERE partner_id = v_partner_id AND report_period = v_period
  ) THEN
    RAISE EXCEPTION 'already_settled' USING ERRCODE = '22023', MESSAGE = 'Bu tərəfdaş üçün həmin ay artıq hesabat yazılıb';
  END IF;
  IF jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION 'lines_required' USING ERRCODE = '22023', MESSAGE = 'Ən azı bir sətir daxil edin';
  END IF;

  SELECT * INTO v_partner FROM public.consignment_partners WHERE id = v_partner_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'partner_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Tərəfdaş tapılmadı';
  END IF;
  v_partner_name := COALESCE(v_partner.company_name, v_partner.name);

  -- Validate + lock every touched consignment_inventory row up front.
  FOR v_line IN SELECT value FROM jsonb_array_elements(v_lines)
  LOOP
    v_product_id := NULLIF(v_line->>'product_id', '')::uuid;
    v_qty_sold := COALESCE((v_line->>'quantity_sold')::numeric, 0);
    v_qty_returned := COALESCE((v_line->>'quantity_returned')::numeric, 0);
    IF v_product_id IS NULL OR (v_qty_sold <= 0 AND v_qty_returned <= 0) THEN
      CONTINUE;
    END IF;

    SELECT * INTO v_inv FROM public.consignment_inventory
    WHERE partner_id = v_partner_id AND product_id = v_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_in_consignment' USING ERRCODE = '22023', MESSAGE = 'Məhsul tərəfdaş stokunda yoxdur';
    END IF;

    IF (v_qty_sold + v_qty_returned) - GREATEST(0, v_inv.delivered_qty - v_inv.sold_qty - v_inv.returned_qty) > 0.0001 THEN
      RAISE EXCEPTION 'qty_exceeds_remaining'
        USING ERRCODE = '22023',
              MESSAGE = format('%s: satılan + qaytarılan miqdar qalıqdan çoxdur', v_inv.product_name);
    END IF;
  END LOOP;

  IF v_return_warehouse_id IS NULL THEN
    FOR v_line IN SELECT value FROM jsonb_array_elements(v_lines)
    LOOP
      IF COALESCE((v_line->>'quantity_returned')::numeric, 0) > 0 THEN
        RAISE EXCEPTION 'return_warehouse_required' USING ERRCODE = '22023', MESSAGE = 'Qaytarılan mal üçün anbar seçin';
      END IF;
    END LOOP;
  END IF;

  -- Build sold/returned line snapshots and apply stock/inventory changes.
  FOR v_line IN SELECT value FROM jsonb_array_elements(v_lines)
  LOOP
    v_product_id := NULLIF(v_line->>'product_id', '')::uuid;
    v_qty_sold := COALESCE((v_line->>'quantity_sold')::numeric, 0);
    v_qty_returned := COALESCE((v_line->>'quantity_returned')::numeric, 0);
    IF v_product_id IS NULL OR (v_qty_sold <= 0 AND v_qty_returned <= 0) THEN
      CONTINUE;
    END IF;

    SELECT * INTO v_inv FROM public.consignment_inventory
    WHERE partner_id = v_partner_id AND product_id = v_product_id
    FOR UPDATE;

    v_unit_price := COALESCE((v_line->>'unit_price')::numeric, v_inv.unit_price);

    IF v_qty_sold > 0 THEN
      v_any_sold := TRUE;
      v_total_amount := v_total_amount + (v_qty_sold * v_unit_price);
      v_sold_items := v_sold_items || jsonb_build_array(jsonb_build_object(
        'product_id', v_product_id,
        'product_code', v_inv.product_code,
        'product_name', v_inv.product_name,
        'quantity_sold', v_qty_sold,
        'unit_price', v_unit_price,
        'total_price', v_qty_sold * v_unit_price
      ));
    END IF;

    IF v_qty_returned > 0 THEN
      v_any_returned := TRUE;
      v_returned_items := v_returned_items || jsonb_build_array(jsonb_build_object(
        'product_id', v_product_id,
        'product_code', v_inv.product_code,
        'product_name', v_inv.product_name,
        'quantity', v_qty_returned,
        'unit', v_inv.unit,
        'unit_price', v_unit_price
      ));

      PERFORM public.consignment_adjust_warehouse_stock(v_product_id, v_return_warehouse_id, v_qty_returned);

      INSERT INTO public.stock_movements (
        product_id, warehouse_id, movement_type, quantity, unit,
        reference_type, reference_id, description, created_by
      )
      VALUES (
        v_product_id, v_return_warehouse_id, 'in', v_qty_returned, COALESCE(v_inv.unit, 'Ədəd'),
        'consignment_return', v_partner_id,
        format('Əmanət hesablaşması qaytarma — %s %s', v_partner_name, v_period), v_created_by
      );
    END IF;

    UPDATE public.consignment_inventory
    SET sold_qty = sold_qty + v_qty_sold,
        returned_qty = returned_qty + v_qty_returned,
        remaining_qty = GREATEST(0, v_inv.delivered_qty - (v_inv.sold_qty + v_qty_sold) - (v_inv.returned_qty + v_qty_returned)),
        updated_at = v_now
    WHERE id = v_inv.id;
  END LOOP;

  IF NOT v_any_sold AND NOT v_any_returned THEN
    RAISE EXCEPTION 'nothing_to_settle' USING ERRCODE = '22023', MESSAGE = 'Satılan və ya qaytarılan məhsul daxil edin';
  END IF;

  IF v_any_sold THEN
    v_invoice_no := 'CNS-' || EXTRACT(YEAR FROM v_now)::text || '-' || floor(random() * 90000 + 10000)::int::text;

    INSERT INTO public.sales (
      doc_no, invoice_number, doc_date, customer_id, customer_name, warehouse_name,
      subtotal, discount_total, vat_total, total_amount, paid_amount, remaining_balance,
      note, notes
    )
    VALUES (
      v_invoice_no, v_invoice_no, (v_period || '-01')::date, v_partner.customer_id, v_partner_name,
      'Əmanət / ' || v_partner_name,
      v_total_amount, 0, 0, v_total_amount, 0, v_total_amount,
      format('Əmanət satış hesabatı %s', v_period), format('Consignment settlement %s', v_period)
    )
    RETURNING id INTO v_sale_id;

    INSERT INTO public.sale_items (
      sale_id, product_id, product_code, product_name, warehouse_id, warehouse_name,
      quantity, unit, unit_price, discount_percent, vat_rate, line_total, extra_info
    )
    SELECT
      v_sale_id,
      (item->>'product_id')::uuid,
      item->>'product_code',
      item->>'product_name',
      NULL,
      'Əmanət / ' || v_partner_name,
      (item->>'quantity_sold')::numeric,
      'Ədəd',
      (item->>'unit_price')::numeric,
      0, 0,
      (item->>'total_price')::numeric,
      NULL
    FROM jsonb_array_elements(v_sold_items) AS item;

    v_journal_id := public.post_sale_invoice_gl_journal(
      v_sale_id, v_invoice_no, v_total_amount, v_partner.customer_id,
      'consignment_settlement:' || v_sale_id::text
    );

    IF v_partner.customer_id IS NOT NULL THEN
      PERFORM public.refresh_customer_ar_balance(v_partner.customer_id);
    END IF;
  END IF;

  IF v_report_no IS NULL THEN
    v_report_no := 'CM-' || EXTRACT(YEAR FROM v_now)::text || '-' || floor(random() * 90000 + 10000)::int::text;
  END IF;

  INSERT INTO public.consignment_monthly_reports (
    report_no, partner_id, report_period, sold_items, returned_items, total_amount,
    invoice_id, notes, sales_rep_id, sales_rep_name, created_by
  )
  VALUES (
    v_report_no, v_partner_id, v_period, v_sold_items, v_returned_items, v_total_amount,
    v_sale_id, v_notes, v_sales_rep_id, v_sales_rep_name, v_created_by
  )
  RETURNING id INTO v_report_id;

  SELECT to_jsonb(r) || jsonb_build_object('partner_name', v_partner_name)
  INTO v_result
  FROM public.consignment_monthly_reports r
  WHERE r.id = v_report_id;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_expense_atomic(p_expense_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp public.expenses%ROWTYPE;
BEGIN
  IF NOT public.require_permission('can_manage_expenses') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'İcazəniz yoxdur';
  END IF;
  SELECT * INTO v_exp FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Xərc sənədi tapılmadı';
  END IF;
  IF v_exp.status <> 'draft' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Yalnız qaralama təsdiqə göndərilə bilər';
  END IF;
  UPDATE public.expenses
  SET status = 'submitted', submitted_at = NOW(), submitted_by = auth.uid(),
      rejected_at = NULL, rejected_by = NULL, rejected_reason = NULL, updated_at = NOW()
  WHERE id = p_expense_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_dimensional_product_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_dimensional IS TRUE THEN
    IF NEW.inventory_mode IS NULL OR NEW.inventory_mode = 'standard' THEN
      NEW.inventory_mode := 'polywood';
    END IF;
    IF NEW.base_length IS NOT NULL THEN
      NEW.full_sheet_length_m := NEW.base_length;
    ELSIF NEW.full_sheet_length_m IS NOT NULL THEN
      NEW.base_length := NEW.full_sheet_length_m;
    END IF;
  ELSIF NEW.inventory_mode = 'polywood' THEN
    NEW.is_dimensional := TRUE;
    IF NEW.base_length IS NULL THEN
      NEW.base_length := COALESCE(NEW.full_sheet_length_m, 4);
    END IF;
    IF NEW.full_sheet_length_m IS NULL THEN
      NEW.full_sheet_length_m := NEW.base_length;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_journal_entry_document_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.date IS NULL THEN
    NEW.date := COALESCE((NEW.entry_date::timestamptz), NEW.posted_at, NOW());
  END IF;

  IF NEW.document_type IS NULL AND NEW.source_type IS NOT NULL THEN
    NEW.document_type := NEW.source_type;
  END IF;

  IF NEW.document_id IS NULL AND NEW.source_id IS NOT NULL THEN
    NEW.document_id := NEW.source_id;
  END IF;

  IF NEW.description IS NULL AND NEW.memo IS NOT NULL THEN
    NEW.description := NEW.memo;
  END IF;

  IF NEW.source_type IS NULL AND NEW.document_type IS NOT NULL THEN
    NEW.source_type := NEW.document_type;
  END IF;

  IF NEW.source_id IS NULL AND NEW.document_id IS NOT NULL THEN
    NEW.source_id := NEW.document_id;
  END IF;

  IF NEW.memo IS NULL AND NEW.description IS NOT NULL THEN
    NEW.memo := NEW.description;
  END IF;

  IF NEW.entry_date IS NULL AND NEW.date IS NOT NULL THEN
    NEW.entry_date := (NEW.date AT TIME ZONE 'UTC')::date;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_product_min_stock_level()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.min_stock_level IS NULL OR NEW.min_stock_level = 0 THEN
      NEW.min_stock_level := COALESCE(NEW.min_stock, 0);
    END IF;
    IF NEW.min_stock IS NULL OR (NEW.min_stock = 0 AND COALESCE(NEW.min_stock_level, 0) > 0) THEN
      NEW.min_stock := COALESCE(NEW.min_stock_level, 0);
    END IF;
    NEW.min_stock := COALESCE(NEW.min_stock, 0);
    NEW.min_stock_level := COALESCE(NEW.min_stock_level, NEW.min_stock, 0);
    RETURN NEW;
  END IF;

  IF NEW.min_stock_level IS DISTINCT FROM OLD.min_stock_level THEN
    NEW.min_stock := COALESCE(NEW.min_stock_level, 0);
  ELSIF NEW.min_stock IS DISTINCT FROM OLD.min_stock THEN
    NEW.min_stock_level := COALESCE(NEW.min_stock, 0);
  ELSE
    NEW.min_stock := COALESCE(NEW.min_stock, NEW.min_stock_level, 0);
    NEW.min_stock_level := COALESCE(NEW.min_stock_level, NEW.min_stock, 0);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_production_expense_to_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_category_id UUID;
  v_tx_id UUID;
  v_description TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.finance_transaction_id IS NOT NULL THEN
      RETURN NEW;
    END IF;

    IF NEW.account_id IS NULL THEN
      RETURN NEW;
    END IF;

    v_category_id := resolve_financial_category_id(NEW.category, 'EXPENSE');
    v_description := COALESCE(
      NULLIF(trim(NEW.notes), ''),
      NULLIF(trim(NEW.category), ''),
      'İstehsalat xərci'
    );

    v_tx_id := post_cash_transaction(
      NEW.account_id,
      'Məxaric',
      COALESCE(NEW.amount, 0),
      COALESCE(NEW.category, 'İstehsalat xərci'),
      v_description,
      NEW.production_order_id,
      'production_expense',
      NEW.id
    );

    UPDATE transactions
    SET
      unified_type = 'EXPENSE',
      category_id = v_category_id,
      reference_type = 'production_expense',
      reference_id = NEW.id,
      source_type = 'production_expense',
      source_id = NEW.id,
      production_order_id = NEW.production_order_id,
      description = v_description
    WHERE id = v_tx_id;

    UPDATE production_expenses
    SET finance_transaction_id = v_tx_id,
        is_posted_to_finance = true
    WHERE id = NEW.id;

    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.finance_transaction_id IS NOT NULL THEN
      DELETE FROM transactions WHERE id = OLD.finance_transaction_id;
    END IF;
    IF OLD.account_id IS NOT NULL THEN
      PERFORM public.reconcile_account_balance_atomic(OLD.account_id);
    END IF;
    RETURN OLD;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.unpost_inventory_initial_balance(p_document_id uuid, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- Server actions call through the service role (no auth.uid()) and pass the
  -- already-authorised user in p_actor; a signed-in caller is always itself.
  v_actor      UUID := COALESCE(auth.uid(), p_actor);
  v_doc        RECORD;
  v_ref        TEXT;
  v_label      TEXT;
  r            RECORD;
  v_is_metric  BOOLEAN;
  v_value      NUMERIC;
  v_old_stock  NUMERIC;
  v_old_buy    NUMERIC;
  v_new_stock  NUMERIC;
  v_new_buy    NUMERIC;
  v_moves      INTEGER := 0;
  v_journals   INTEGER := 0;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT (public.user_is_admin() OR public.has_permission('can_unpost_inventory')) THEN
    RAISE EXCEPTION '%', 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_document_id IS NULL THEN
    RAISE EXCEPTION '%', 'Sənəd ID-si göstərilməyib' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_doc
  FROM public.inventory_initial_balances
  WHERE id = p_document_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', 'Sənəd tapılmadı' USING ERRCODE = 'P0002';
  END IF;

  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION '%', 'Yalnız təsdiqlənmiş sənəd qaralamaya qaytarıla bilər' USING ERRCODE = '22023';
  END IF;

  IF public.is_accounting_period_closed(v_doc.doc_date) THEN
    RAISE EXCEPTION '%', format(
      'Sənəd tarixi bağlı maliyyə dövrünə düşür (%s). Əvvəlcə dövrü açın.',
      to_char(v_doc.doc_date, 'YYYY-MM')
    ) USING ERRCODE = '22023';
  END IF;

  v_ref := CASE WHEN v_doc.entry_type = 'receipt' THEN 'stock_receipt' ELSE 'initial_balance' END;
  v_label := v_doc.document_number;

  -- ─── Guards: nothing from this document may have left the warehouse ──────

  IF EXISTS (
    SELECT 1 FROM public.inventory_batches
    WHERE document_id = p_document_id
      AND document_type = v_ref
      AND remaining_qty < initial_qty
  ) THEN
    RAISE EXCEPTION '%',
      'Bu sənədlə daxil olan stokun bir hissəsi artıq satılıb və ya istifadə olunub. Qaralamaya qaytarmaq mümkün deyil — silinmə və ya düzəliş sənədi ilə düzəldin.'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.polywood_pieces
    WHERE source_document_id = p_document_id
      AND status <> 'available'
  ) THEN
    RAISE EXCEPTION '%',
      'Bu sənədlə daxil olan hissələrin bəziləri artıq satılıb və ya kəsilib. Qaralamaya qaytarmaq mümkün deyil.'
      USING ERRCODE = '22023';
  END IF;

  -- Metric lines posted before pieces were linked to their document cannot be
  -- told apart from other pieces of the same product, so refuse rather than guess.
  IF EXISTS (
    SELECT 1 FROM public.inventory_initial_balance_items i
    WHERE i.document_id = p_document_id
      AND i.is_metric
      AND NOT EXISTS (
        SELECT 1 FROM public.polywood_pieces pp
        WHERE pp.source_document_id = p_document_id
          AND pp.product_id = i.product_id
      )
  ) THEN
    RAISE EXCEPTION '%',
      'Bu sənəddəki metrik hissələr köhnə qaydada təsdiqlənib və sənədə bağlı deyil. Avtomatik geri qaytarmaq mümkün deyil — administratorla əlaqə saxlayın.'
      USING ERRCODE = '22023';
  END IF;

  -- ─── Reverse stock, per product and warehouse ────────────────────────────
  -- Net the document's own movements so earlier post/unpost cycles cancel out.

  FOR r IN
    SELECT
      m.product_id,
      m.warehouse_id,
      MIN(m.unit) AS unit,
      SUM(CASE WHEN m.movement_type = 'in' THEN m.quantity ELSE -m.quantity END) AS net_qty
    FROM public.stock_movements m
    WHERE m.reference_id = p_document_id
      AND m.reference_type = v_ref
    GROUP BY m.product_id, m.warehouse_id
    HAVING SUM(CASE WHEN m.movement_type = 'in' THEN m.quantity ELSE -m.quantity END) > 0.0005
  LOOP
    SELECT EXISTS (
      SELECT 1 FROM public.inventory_initial_balance_items i
      WHERE i.document_id = p_document_id AND i.product_id = r.product_id AND i.is_metric
    ) INTO v_is_metric;

    SELECT COALESCE(SUM(
      (CASE WHEN i.is_metric THEN COALESCE(i.metric_total_meters, i.quantity) ELSE i.quantity END) * i.unit_cost
    ), 0)
    INTO v_value
    FROM public.inventory_initial_balance_items i
    WHERE i.document_id = p_document_id AND i.product_id = r.product_id;

    SELECT COALESCE(stock, 0), COALESCE(buy_price, 0)
    INTO v_old_stock, v_old_buy
    FROM public.products
    WHERE id = r.product_id
    FOR UPDATE;

    IF v_is_metric THEN
      DELETE FROM public.polywood_pieces
      WHERE source_document_id = p_document_id
        AND product_id = r.product_id;

      -- Same rule as syncPolywoodProductStockFromPieces: stock = available metres.
      SELECT ROUND(COALESCE(SUM(length_m), 0), 3)
      INTO v_new_stock
      FROM public.polywood_pieces
      WHERE product_id = r.product_id
        AND warehouse_id = r.warehouse_id
        AND status = 'available';
    ELSE
      IF v_old_stock + 0.0005 < r.net_qty THEN
        RAISE EXCEPTION '%', format(
          'Məhsulun cari qalığı (%s) bu sənədin daxil etdiyi miqdardan (%s) azdır — stok artıq çıxarılıb. Qaralamaya qaytarmaq mümkün deyil.',
          v_old_stock, r.net_qty
        ) USING ERRCODE = '22023';
      END IF;
      v_new_stock := v_old_stock - r.net_qty;
    END IF;

    -- Undo the weighted-average cost the posting applied.
    v_new_buy := v_old_buy;
    IF v_new_stock > 0 THEN
      v_new_buy := ROUND((v_old_stock * v_old_buy - v_value) / v_new_stock, 2);
      IF v_new_buy < 0 THEN
        v_new_buy := v_old_buy;
      END IF;
    END IF;

    UPDATE public.products
    SET stock = v_new_stock, buy_price = v_new_buy
    WHERE id = r.product_id;

    UPDATE public.warehouse_stocks
    SET current_stock = v_new_stock,
        piece_lengths = CASE WHEN v_is_metric THEN (
          SELECT COALESCE(jsonb_agg(pp.length_m ORDER BY pp.length_m DESC), '[]'::jsonb)
          FROM public.polywood_pieces pp
          WHERE pp.product_id = r.product_id
            AND pp.warehouse_id = r.warehouse_id
            AND pp.status = 'available'
        ) ELSE piece_lengths END,
        updated_at = NOW()
    WHERE product_id = r.product_id
      AND warehouse_id IS NOT DISTINCT FROM r.warehouse_id;

    INSERT INTO public.stock_movements (
      product_id, warehouse_id, movement_type, quantity, unit,
      reference_type, reference_id, description, created_by
    )
    VALUES (
      r.product_id, r.warehouse_id, 'out', r.net_qty, r.unit,
      v_ref, p_document_id, 'STORNO: ' || v_label, v_actor
    );

    v_moves := v_moves + 1;
  END LOOP;

  IF v_moves = 0 AND EXISTS (
    SELECT 1 FROM public.inventory_initial_balance_items WHERE document_id = p_document_id
  ) THEN
    RAISE EXCEPTION '%',
      'Bu sənəd üçün anbar hərəkəti tapılmadı. Avtomatik geri qaytarmaq mümkün deyil — administratorla əlaqə saxlayın.'
      USING ERRCODE = '22023';
  END IF;

  -- FIFO layers were verified untouched above; re-posting creates fresh ones.
  DELETE FROM public.inventory_batches
  WHERE document_id = p_document_id
    AND document_type = v_ref;

  -- Ledger is immutable: offset any postings with storno entries.
  v_journals := public.reverse_document_journals(
    p_document_id,
    'Qaralamaya qaytarıldı: ' || v_label || COALESCE(' — ' || NULLIF(trim(p_reason), ''), '')
  );

  UPDATE public.inventory_initial_balances
  SET status = 'draft',
      posted_at = NULL,
      posted_by = NULL,
      unposted_at = NOW(),
      unposted_by = v_actor,
      unpost_reason = NULLIF(trim(p_reason), ''),
      updated_at = NOW()
  WHERE id = p_document_id;

  RETURN jsonb_build_object(
    'document_number', v_label,
    'movements_reversed', v_moves,
    'journals_reversed', v_journals
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_contract_legal_party()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.type IN ('sale', 'service') THEN
    IF NOT EXISTS (
      SELECT 1
      FROM customers c
      WHERE c.id = NEW.party_id
        AND c.entity_type = 'legal'
        AND COALESCE(TRIM(c.voen), '') <> ''
    ) THEN
      RAISE EXCEPTION 'contract_requires_legal_customer_with_voen';
    END IF;
  ELSIF NEW.type = 'purchase' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM suppliers s
      WHERE s.id = NEW.party_id
        AND s.entity_type = 'legal'
        AND COALESCE(TRIM(s.voen), '') <> ''
    ) THEN
      RAISE EXCEPTION 'contract_requires_legal_supplier_with_voen';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_transaction_row()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.account_id IS NULL THEN
    RAISE EXCEPTION 'account_id_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Kassa/bank hesabı (account_id) mütləqdir';
  END IF;

  IF NEW.amount IS NULL OR NEW.amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Əməliyyat məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF NEW.type IS DISTINCT FROM 'Mədaxil' AND NEW.type IS DISTINCT FROM 'Məxaric' THEN
    RAISE EXCEPTION 'invalid_transaction_type'
      USING ERRCODE = '22023',
            MESSAGE = 'Əməliyyat növü Mədaxil və ya Məxaric olmalıdır';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.void_purchase_atomic(p_purchase_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_purchase purchases%ROWTYPE;
  v_note TEXT;
  v_doc_label TEXT;
  v_tx_deleted INT;
  v_stock_reverted INT;
  v_supplier_balance NUMERIC;
BEGIN
  IF NOT public.require_permission('can_delete_purchases')
     AND NOT public.require_permission('can_edit_purchases') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Alış ləğvi üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_purchase
  FROM purchases
  WHERE id = p_purchase_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Alış fakturası tapılmadı';
  END IF;

  IF public.is_invoice_cancelled(v_purchase.status) THEN
    RETURN jsonb_build_object(
      'purchase_id', p_purchase_id,
      'already_void', true,
      'status', v_purchase.status
    );
  END IF;

  v_doc_label := COALESCE(NULLIF(trim(v_purchase.invoice_number), ''), p_purchase_id::text);
  v_note := trim(COALESCE(p_reason, ''));
  IF v_note = '' THEN
    v_note := 'Alış fakturası ləğv edildi';
  END IF;

  v_stock_reverted := public.revert_purchase_stock(p_purchase_id);
  v_tx_deleted := public.delete_document_cash_transactions('purchase', p_purchase_id, v_doc_label);

  IF v_purchase.supplier_id IS NOT NULL AND COALESCE(v_purchase.debt_amount, 0) > 0.0001 THEN
    SELECT balance INTO v_supplier_balance
    FROM suppliers
    WHERE id = v_purchase.supplier_id
    FOR UPDATE;

    UPDATE suppliers
    SET balance = GREATEST(COALESCE(v_supplier_balance, 0) - COALESCE(v_purchase.debt_amount, 0), 0)
    WHERE id = v_purchase.supplier_id;
  END IF;

  UPDATE warehouse_slips
  SET status = 'rejected'
  WHERE source_type = 'purchase'
    AND source_document_id = p_purchase_id
    AND status = 'pending';

  UPDATE purchases
  SET
    status = 'cancelled',
    paid_amount = 0,
    debt_amount = 0,
    warehouse_sent = FALSE,
    warehouse_slip_status = NULL,
    notes = CASE
      WHEN notes IS NULL OR trim(notes) = '' THEN v_note
      ELSE notes || E'\n' || v_note
    END
  WHERE id = p_purchase_id;

  RETURN jsonb_build_object(
    'purchase_id', p_purchase_id,
    'already_void', false,
    'status', 'cancelled',
    'stock_lines_reverted', v_stock_reverted,
    'transactions_removed', v_tx_deleted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.void_sale_atomic(p_sale_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale sales%ROWTYPE;
  v_note TEXT;
  v_doc_label TEXT;
  v_tx_deleted INT;
  v_stock_restored INT;
BEGIN
  IF NOT public.require_permission('can_delete_sales')
     AND NOT public.require_permission('can_edit_sales') THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Satış ləğvi üçün icazəniz yoxdur';
  END IF;

  SELECT * INTO v_sale
  FROM sales
  WHERE id = p_sale_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Satış fakturası tapılmadı';
  END IF;

  IF public.is_invoice_cancelled(v_sale.status) THEN
    RETURN jsonb_build_object(
      'sale_id', p_sale_id,
      'already_void', true,
      'status', v_sale.status
    );
  END IF;

  v_doc_label := COALESCE(NULLIF(trim(v_sale.doc_no), ''), NULLIF(trim(v_sale.invoice_number), ''), p_sale_id::text);
  v_note := trim(COALESCE(p_reason, ''));
  IF v_note = '' THEN
    v_note := 'Satış fakturası ləğv edildi';
  END IF;

  v_stock_restored := public.restore_sale_stock(p_sale_id);
  v_tx_deleted := public.delete_document_cash_transactions('sale', p_sale_id, v_doc_label);

  UPDATE warehouse_slips
  SET status = 'rejected'
  WHERE source_type = 'sale'
    AND source_document_id = p_sale_id
    AND status = 'pending';

  UPDATE sales
  SET
    status = 'cancelled',
    paid_amount = 0,
    remaining_balance = 0,
    payments = '[]'::jsonb,
    warehouse_sent = FALSE,
    warehouse_slip_status = NULL,
    note = COALESCE(note, v_note),
    notes = CASE
      WHEN notes IS NULL OR trim(notes) = '' THEN v_note
      ELSE notes || E'\n' || v_note
    END
  WHERE id = p_sale_id;

  IF v_sale.customer_id IS NOT NULL THEN
    PERFORM public.refresh_customer_ar_balance(v_sale.customer_id);
  END IF;

  RETURN jsonb_build_object(
    'sale_id', p_sale_id,
    'already_void', false,
    'status', 'cancelled',
    'stock_lines_restored', v_stock_restored,
    'transactions_removed', v_tx_deleted
  );
END;
$function$
